var GRAM_UNITS=[{"unit": 1, "section": "Present and Past", "title": "Present Continuous (I am doing)", "pattern": "am/is/are + V-ing", "sections": [{"label": "A", "explain": "ใช้บอกสิ่งที่กำลังเกิดขึ้น ณ ขณะที่พูดพอดี การกระทำเริ่มไปแล้วแต่ยังไม่จบ", "examples": ["Please be quiet. I'm working.", "\"Where's Anna?\" \"She's taking a shower.\"", "Let's go out now. It isn't raining anymore.", "I can't find my keys. I think I'm losing them."]}, {"label": "B", "explain": "ใช้บอกสิ่งที่กำลังดำเนินอยู่ในช่วงเวลานี้ (ช่วงเวลาปัจจุบันโดยรวม) แม้ตอนพูดจะไม่ได้ทำอยู่จริงๆ ก็ได้", "examples": ["I'm reading a great novel at the moment. I only read it in the evenings.", "Tom is looking for a new job these days.", "We're planning to move to a new house next month."]}, {"label": "C", "explain": "ใช้พูดถึงสิ่งที่ตกลง/นัดหมายไว้แน่นอนแล้วสำหรับอนาคตอันใกล้", "examples": ["I'm meeting my friend at 7 tonight.", "What are you doing tomorrow evening?"]}], "notes": ["กริยาบางกลุ่มที่บอกความรู้สึก ความคิด หรือการรับรู้ถาวร (stative verbs) เช่น like, want, need, know, understand, believe, remember, love, hate, seem, belong, mean ปกติไม่ใช้ในรูป continuous", "'I don't understand this.' ไม่ใช่ 'I'm not understanding this.'"], "mistake": {"wrong": "I am wanting to go home.", "right": "I want to go home.", "note": "want เป็น stative verb แสดงความต้องการ ไม่ใช้รูป continuous"}, "tip": "ถ้ากริยาบอกความรู้สึก ความคิด หรือการรับรู้ (know, like, want, believe) ให้สงสัยไว้ก่อนว่าอาจใช้ continuous ไม่ได้", "summary": ["ใช้กับสิ่งที่กำลังเกิดขึ้นตอนนี้/ช่วงนี้/แผนที่วางไว้แล้ว", "โครงสร้าง: am/is/are + V-ing", "Stative verbs (like, want, know, believe) ไม่ใช้ continuous"]}, {"unit": 2, "section": "Present and Past", "title": "Present Simple (I do)", "pattern": "V1 (V-s สำหรับ he/she/it)", "sections": [{"label": "A", "explain": "ใช้บอกสิ่งที่เป็นความจริงทั่วไป ทำเป็นประจำ หรือเกิดขึ้นซ้ำๆ", "examples": ["Nurses look after patients in hospitals.", "I usually go to the gym at weekends.", "The earth goes round the sun.", "The cafe opens at 7 a.m. and closes at 9 p.m."]}, {"label": "B", "explain": "ประธานเอกพจน์บุรุษที่ 3 (he/she/it) ต้องเติม -s หรือ -es ที่กริยา", "examples": ["My sister works in a bank.", "The bus leaves at 8 every morning.", "He watches TV most evenings.", "She goes to bed early."]}, {"label": "C", "explain": "รูปปฏิเสธและคำถามใช้ do/does + not หรือ do/does นำหน้าประโยค", "examples": ["I don't drink coffee.", "She doesn't like spicy food.", "Do you speak English?", "Does he play the guitar?"]}], "notes": ["มักใช้คู่กับคำบอกความถี่: always, usually, often, sometimes, never, every day", "ระวังสะกดคำเมื่อเติม -es: go→goes, watch→watches, study→studies (y เปลี่ยนเป็น i ก่อนเติม -es)"], "mistake": {"wrong": "He don't like tea.", "right": "He doesn't like tea.", "note": "ประธานเอกพจน์บุรุษที่ 3 (he) ต้องใช้ doesn't ไม่ใช่ don't"}, "tip": "he/she/it จำคู่กันเสมอ: กริยาเติม -s หรือใช้ does/doesn't", "summary": ["ใช้กับความจริงทั่วไป/สิ่งที่ทำเป็นประจำ", "he/she/it เติม -s/-es ที่กริยา", "ปฏิเสธ/คำถามใช้ do/does"]}, {"unit": 3, "section": "Present and Past", "title": "Present Continuous vs Present Simple 1", "pattern": "S + is/am/are + V-ing  ⟷  S + V1/V-s", "sections": [{"label": "A", "explain": "Present Continuous ใช้กับสิ่งที่กำลังเกิดขึ้นตอนนี้หรือรอบๆ เวลาพูด การกระทำยังไม่จบ ส่วน Present Simple ใช้กับสิ่งที่เกิดซ้ำๆ หรือเป็นความจริงทั่วไป", "examples": ["The water is boiling. Can you turn it off?", "Water boils at 100 degrees Celsius.", "Listen! Somebody is singing.", "Excuse me, do you speak English?"]}, {"label": "B", "explain": "Present Continuous ใช้กับสถานการณ์ชั่วคราว (ต่อเนื่องช่วงสั้นๆ) ส่วน Present Simple ใช้กับสถานการณ์ถาวรหรือยาวนาน", "examples": ["I'm living with a friend until I find my own apartment.", "My parents live in Chiang Mai. They've lived there for 20 years.", "\"You're working hard today.\" \"Yes, I have a lot to do.\"", "He works hard most of the time."]}], "notes": ["'always doing' (ไม่ใช่ 'always do') ใช้เมื่อบ่นว่าเกิดขึ้นบ่อยเกินไป เช่น 'You're always losing your keys!' (= คุณทำหายบ่อยเกินไป)"], "mistake": {"wrong": "I always go to work by car, I'm always going by car.", "right": "I always go to work by car.", "note": "'I always do' = ทำทุกครั้งเป็นปกติ ไม่ใช้ continuous ในกรณีนี้ ('always doing' สงวนไว้สำหรับการบ่นว่าทำบ่อยเกินไป)"}, "tip": "ถามตัวเองว่า 'เรื่องนี้เป็นสิ่งที่เกิดขึ้นตลอด (Simple) หรือกำลังเกิดขึ้นแค่ตอนนี้/ช่วงนี้ (Continuous)?'", "summary": ["Continuous: กำลังเกิดขึ้น/ชั่วคราว", "Simple: เกิดซ้ำๆ/ถาวร/ความจริงทั่วไป", "'always + V-ing' ใช้บ่นว่าทำบ่อยเกินไป"]}, {"unit": 4, "section": "Present and Past", "title": "Present Continuous vs Present Simple 2 (Stative Verbs)", "pattern": "know/like/want/believe + ... (ไม่ใช้ continuous)", "sections": [{"label": "A", "explain": "กริยาบางกลุ่ม (stative verbs) ไม่ใช้ในรูป continuous แม้จะพูดถึงตอนนี้ก็ตาม กลุ่มนี้ได้แก่ กริยาแสดงความคิด/ความเชื่อ (know, think, believe, understand, remember, mean, suppose) กริยาแสดงความรู้สึก (like, love, hate, want, need, prefer) และกริยาแสดงการรับรู้ (see, hear, smell, taste - เมื่อไม่ได้ตั้งใจทำ)", "examples": ["I understand the problem now. (not I'm understanding)", "Do you believe what she said? (not Are you believing)", "This soup tastes great. (not is tasting)", "I need your help right now. (not am needing)"]}, {"label": "B", "explain": "บางคำมีทั้งความหมายแบบ stative (สภาพ) และ dynamic (การกระทำ) ให้ดูความหมายในประโยค", "examples": ["I think this is a great idea. (ความเห็น = stative)", "I'm thinking about changing my job. (กำลังไตร่ตรอง = dynamic, ใช้ continuous ได้)", "This coffee tastes good. (รสชาติ = stative)", "The chef is tasting the soup to check the salt. (กำลังชิม = dynamic)"]}], "notes": ["have ก็มีสองความหมาย: 'I have a car' (ครอบครอง = stative, ไม่ใช้ continuous) แต่ 'I'm having lunch' (กำลังทำกิจกรรม = dynamic, ใช้ continuous ได้)"], "mistake": {"wrong": "I'm having a headache.", "right": "I have a headache.", "note": "'have' ในความหมาย 'มี/เป็น' (ครอบครองอาการ) เป็น stative verb ไม่ใช้ continuous"}, "tip": "เช็คความหมาย ไม่ใช่แค่ตัวคำ: think/have/taste ใช้ continuous ได้เมื่อหมายถึง 'กำลังทำ' แต่ใช้ไม่ได้เมื่อหมายถึง 'สภาพ/ความเห็น'", "summary": ["Stative verbs (know, want, believe, need) ไม่ใช้ continuous", "some verbs (think, have, taste) เปลี่ยนความหมายได้ทั้ง stative และ dynamic", "ดูบริบทประโยคเพื่อเลือกให้ถูก"]}, {"unit": 5, "section": "Present and Past", "title": "Past Simple (I did)", "pattern": "V2 (regular: -ed / irregular: เปลี่ยนรูป)", "sections": [{"label": "A", "explain": "ใช้บอกเหตุการณ์ที่จบไปแล้วในอดีต กริยาปกติ (regular) เติม -ed ส่วนกริยาไม่ปกติ (irregular) เปลี่ยนรูปเฉพาะตัว", "examples": ["I worked in a shop before I got this job.", "They invited us to their party, but we decided not to go.", "Mozart wrote more than 600 pieces of music. (write → wrote)", "We saw Alice in town yesterday. (see → saw)", "I went to the cinema last week. (go → went)"]}, {"label": "B", "explain": "รูปปฏิเสธและคำถามใช้ did/didn't + กริยาช่องที่ 1 (infinitive) เสมอ ไม่ผัน V2 ซ้ำ", "examples": ["I enjoyed the party a lot. Did you enjoy it?", "How many people did they invite to the wedding?", "I didn't buy anything because I didn't have any money.", "What did you do at the weekend? (not What did you at the weekend?)"]}, {"label": "C", "explain": "อดีตของ be (am/is/are) คือ was/were", "examples": ["I was annoyed because they were late.", "Was the weather good when you were on holiday?", "They weren't able to come because they were busy.", "I wasn't hungry, so I didn't eat anything."]}], "notes": ["มักใช้คู่กับคำบอกเวลาในอดีต: yesterday, last week, ... ago, in 2020", "ดูรายการ irregular verbs เพิ่มเติม (go-went-gone, see-saw-seen, write-wrote-written ฯลฯ) เพราะไม่มีกฎตายตัว ต้องจำเป็นคำๆ ไป"], "mistake": {"wrong": "Did you went to the party?", "right": "Did you go to the party?", "note": "หลัง did ต้องใช้กริยาช่องที่ 1 เสมอ (go) ไม่ใช่ช่องที่ 2 (went) เพราะ did ทำหน้าที่แสดงอดีตไปแล้ว"}, "tip": "เจอ did/didn't แล้ว กริยาต้องกลับเป็นรูปพื้นฐาน (V1) เสมอ ห้ามผัน V2 ซ้ำสอง", "summary": ["Past Simple บอกเหตุการณ์ที่จบไปแล้ว", "regular +ed, irregular เปลี่ยนรูปเฉพาะตัว", "คำถาม/ปฏิเสธ: did/didn't + V1"]}, {"unit": 6, "section": "Present and Past", "title": "Past Continuous (I was doing)", "pattern": "was/were + V-ing", "sections": [{"label": "A", "explain": "ใช้บอกเหตุการณ์ที่กำลังดำเนินอยู่ ณ จุดใดจุดหนึ่งในอดีต (ยังไม่จบ ณ ตอนนั้น)", "examples": ["This time last year I was living in Bangkok.", "What were you doing at 10 o'clock last night?", "I waved to her, but she wasn't looking."]}, {"label": "B", "explain": "ใช้คู่กับ Past Simple เพื่อบอกว่าเหตุการณ์สั้นๆ (Past Simple) เกิดขึ้นแทรกระหว่างเหตุการณ์ที่กำลังดำเนินอยู่ (Past Continuous)", "examples": ["I was watching TV when the phone rang.", "Sarah burnt her hand while she was cooking dinner.", "The doorbell rang while I was having a shower."]}], "notes": ["เปรียบเทียบ: 'When he arrived, I cooked dinner' (ผมเริ่มทำหลังเขามาถึง = สองเหตุการณ์เรียงกัน) กับ 'When he arrived, I was cooking dinner' (ผมทำอยู่ก่อนแล้ว เขามาถึงตอนที่ผมกำลังทำ)"], "mistake": {"wrong": "I watched TV when the phone was ringing.", "right": "I was watching TV when the phone rang.", "note": "เหตุการณ์ที่กำลังดำเนินอยู่ (was watching) ต้องมาก่อน เหตุการณ์สั้นที่แทรกเข้ามา (rang) ไม่ใช่กลับกัน"}, "tip": "จำโครงสร้าง: 'กำลังทำอะไรอยู่ (Past Continuous) ตอนที่มีอะไรมาแทรก (Past Simple)'", "summary": ["Past Continuous: กำลังดำเนินอยู่ ณ จุดหนึ่งในอดีต", "โครงสร้าง: was/were + V-ing", "มักคู่กับ Past Simple ที่แทรกเข้ามา (...when + V2)"]}, {"unit": 7, "section": "Present Perfect and Past", "title": "Present Perfect 1 (I have done)", "pattern": "have/has + V3 (past participle)", "sections": [{"label": "A", "explain": "ใช้บอกเหตุการณ์ที่เพิ่งเกิดขึ้นและยังส่งผลถึงปัจจุบัน (ถือเป็นข้อมูลใหม่ ณ ตอนพูด)", "examples": ["Ow! I've cut my finger.", "Tom has lost his key. He can't get into the house.", "She's forgotten his name.", "Have you seen my bag anywhere?"]}, {"label": "B", "explain": "เปรียบเทียบ 'gone to' (ไปแล้วยังอยู่ที่นั่น/กำลังเดินทาง) กับ 'been to' (ไปแล้วและกลับมาแล้ว)", "examples": ["James has gone to Italy. (เขาอยู่ที่นั่นตอนนี้ หรือกำลังเดินทางไป)", "Amy has been to Italy. (เธอไปแล้ว และตอนนี้กลับมาแล้ว)"]}, {"label": "C", "explain": "ใช้คู่กับ just (เมื่อครู่นี้), already (เร็วกว่าที่คาด), yet (จนถึงตอนนี้ ใช้ในคำถาม/ปฏิเสธ)", "examples": ["'Are you hungry?' 'No, I've just had lunch.'", "'Don't forget to pay the bill.' 'I've already paid it.'", "Has it stopped raining yet?", "I've written the email, but I haven't sent it yet."]}], "notes": ["past participle (V3) ของกริยาปกติเติม -ed แต่หลายคำเป็น irregular (lost, done, written, gone, seen)"], "mistake": {"wrong": "I have seen him yesterday.", "right": "I saw him yesterday.", "note": "'yesterday' เป็นเวลาที่ระบุแน่นอนในอดีต ห้ามใช้ Present Perfect ต้องใช้ Past Simple"}, "tip": "just = เมื่อครู่นี้, already = เร็วกว่าที่คาด, yet = จนถึงตอนนี้ (คำถาม/ปฏิเสธ) — สามคำนี้เป็นสัญญาณของ Present Perfect", "summary": ["Present Perfect เชื่อมอดีตกับปัจจุบัน เป็นข้อมูลใหม่", "โครงสร้าง: have/has + V3", "gone to (ยังอยู่ที่นั่น) ต่างจาก been to (ไปแล้วกลับมาแล้ว)"]}, {"unit": 8, "section": "Present Perfect and Past", "title": "Present Perfect 2 (I have done)", "pattern": "have/has + ever/never + V3", "sections": [{"label": "A", "explain": "ใช้พูดถึงประสบการณ์ในช่วงเวลาที่ต่อเนื่องจากอดีตจนถึงตอนนี้ (เช่น ในชีวิตที่ผ่านมาทั้งหมด)", "examples": ["Have you ever been to China?", "We've never had a car.", "She's read that book three times.", "I haven't seen him recently."]}, {"label": "B", "explain": "ใช้กับโครงสร้าง 'It's the first/second/third time...' เสมอ", "examples": ["It's the first time he has driven a car.", "This is the second time this has happened.", "It's the third time she's phoned tonight."]}], "notes": ["มักใช้คู่กับคำสัญญาณ: ever, never, recently, so far, since..., today, this week (ช่วงเวลาที่ยังไม่จบ)"], "mistake": {"wrong": "It's the first time he drives a car.", "right": "It's the first time he has driven a car.", "note": "หลัง 'It's the (first/second) time...' ต้องใช้ Present Perfect เสมอ ไม่ใช่ Present Simple"}, "tip": "ever/never ในประโยคคำถาม/ปฏิเสธ มักเป็นสัญญาณของ Present Perfect เกือบทุกครั้ง", "summary": ["ใช้พูดถึงประสบการณ์ในชีวิตจนถึงตอนนี้", "'It's the Nth time...' ต้องตามด้วย Present Perfect", "ever/never เป็นคำสัญญาณสำคัญ"]}, {"unit": 9, "section": "Present Perfect and Past", "title": "Present Perfect Continuous (I have been doing)", "pattern": "have/has been + V-ing", "sections": [{"label": "A", "explain": "ใช้กับกิจกรรมที่เพิ่งจบไปหรือเพิ่งหยุดไป โดยดูจากร่องรอย/ผลลัพธ์ที่เห็นได้ตอนนี้", "examples": ["Why are you out of breath? Have you been running?", "I've been talking to Amanda, and she agrees with me.", "The ground is wet. It's been raining.", "Where have you been? I've been looking for you."]}, {"label": "B", "explain": "ใช้กับ how long, for, since เมื่อกิจกรรมยังดำเนินอยู่หรือเพิ่งหยุดไปไม่นาน", "examples": ["How long have you been learning English?", "She's been playing tennis since she was eight.", "They've been going there for years."]}], "notes": ["เปรียบเทียบกับ Present Continuous ธรรมดา: 'I'm working' (กำลังทำอยู่ตอนนี้เท่านั้น) ต่างจาก 'I've been working hard' (ทำต่อเนื่องมาจนถึงตอนนี้)"], "mistake": {"wrong": "How long you learn English?", "right": "How long have you been learning English?", "note": "ถาม how long เกี่ยวกับกิจกรรมต่อเนื่อง ต้องใช้ Present Perfect Continuous"}, "tip": "สังเกตร่องรอยหรือผลลัพธ์ที่เห็นได้ตอนนี้ (พื้นเปียก, เหนื่อยหอบ) มักเป็นสัญญาณของ Present Perfect Continuous", "summary": ["โครงสร้าง: have/has been + V-ing", "ใช้กับกิจกรรมที่เพิ่งจบหรือยังดำเนินอยู่", "มักคู่กับ how long, for, since"]}, {"unit": 10, "section": "Present Perfect and Past", "title": "Present Perfect Continuous vs Simple", "pattern": "have been + V-ing (กิจกรรม)  ⟷  have + V3 (ผลลัพธ์/จำนวน)", "sections": [{"label": "A", "explain": "Continuous เน้นตัวกิจกรรมเอง (จะเสร็จหรือยังก็ได้) ส่วน Simple เน้นผลลัพธ์ที่เสร็จสมบูรณ์แล้ว", "examples": ["She has been painting her bedroom. (เน้นกิจกรรม อาจยังไม่เสร็จ)", "She has painted her bedroom. (เสร็จแล้ว มีผลลัพธ์ชัดเจน)", "Somebody has eaten all the chocolates. The box is empty."]}, {"label": "B", "explain": "Continuous ใช้กับ how long (ระยะเวลาที่ยังดำเนินอยู่) ส่วน Simple ใช้กับ how much/how many/how many times (จำนวนที่นับได้ของสิ่งที่เสร็จแล้ว)", "examples": ["How long have you been reading that book?", "How many pages have you read?", "They've been playing tennis since 2 o'clock.", "They've played tennis three times this week."]}], "notes": ["กริยาบางตัว (know, have แบบครอบครอง) ไม่ใช้รูป continuous แม้จะเป็น Present Perfect: 'I've known him for years' ไม่ใช่ 'I've been knowing'"], "mistake": {"wrong": "I've been knowing him for years.", "right": "I've known him for years.", "note": "'know' เป็น stative verb ไม่ใช้รูป continuous แม้เป็น Present Perfect"}, "tip": "ถามจำนวน (how many/how much) ให้นึกถึง Simple, ถามระยะเวลาที่ยังดำเนินอยู่ (how long) ให้นึกถึง Continuous", "summary": ["Continuous เน้นกิจกรรม, Simple เน้นผลลัพธ์/จำนวน", "how long → continuous, how many/how much → simple", "know, have (ครอบครอง) ไม่ใช้ continuous"]}, {"unit": 11, "section": "Present Perfect and Past", "title": "How long have you (been) ...?", "pattern": "have/has + V3  /  have/has been + V-ing  (+ since/for)", "sections": [{"label": "A", "explain": "เปรียบเทียบ present ธรรมดา กับ present perfect เมื่อพูดถึงสถานการณ์ที่เริ่มในอดีตและยังต่อเนื่องถึงตอนนี้", "examples": ["He's been in hospital since Monday. (ไม่ใช่ 'He is in hospital since Monday')", "We've known each other for a long time.", "How long have they had their car?"]}, {"label": "B", "explain": "live/work ใช้ได้ทั้ง continuous และ simple แต่ always ใช้คู่กับ simple เท่านั้น (ไม่ใช้ continuous)", "examples": ["Julia has been living here for years. / Julia has lived here for years.", "I've always lived in the country. (not 'always been living')"]}], "notes": ["married ใช้ 'How long have they been married?' ไม่ใช่ 'How long are they married?'"], "mistake": {"wrong": "How long are you married?", "right": "How long have you been married?", "note": "สถานการณ์ต่อเนื่องจากอดีตถึงปัจจุบัน ต้องใช้ Present Perfect ไม่ใช่ Present Simple"}, "tip": "ถ้าประโยคถาม 'how long' เกี่ยวกับสถานการณ์ที่ยังดำเนินอยู่ ให้นึกถึง Present Perfect ก่อนเสมอ ไม่ใช่ Present Simple", "summary": ["สถานการณ์ต่อเนื่องจากอดีตถึงตอนนี้ ใช้ Present Perfect", "always + Simple เท่านั้น (ไม่ใช้ continuous)", "live/work ใช้ได้ทั้งสองแบบ"]}, {"unit": 12, "section": "Present Perfect and Past", "title": "for and since, when...? and how long...?", "pattern": "for + ระยะเวลา  /  since + จุดเริ่มต้น", "sections": [{"label": "A", "explain": "for ใช้กับระยะเวลา (two hours, a long time) ส่วน since ใช้กับจุดเริ่มต้น (8 o'clock, Monday, 2015)", "examples": ["We've been waiting for two hours.", "We've been waiting since 8 o'clock.", "I haven't seen Tom for three days.", "Sally has worked here since April."]}, {"label": "B", "explain": "เปรียบเทียบ when...? (+ Past Simple) กับ how long...? (+ Present Perfect)", "examples": ["When did it start raining? — It started an hour ago.", "How long has it been raining? — It's been raining for an hour."]}], "notes": ["ไม่ใช้ for กับ all... (all day, all my life): 'I've lived here all my life' ไม่ใช่ 'for all my life'", "'It's ... since...' หรือ 'It's been ... since...' ใช้บอกว่าผ่านมานานแค่ไหนแล้วนับจากเหตุการณ์หนึ่ง"], "mistake": {"wrong": "I've lived here since ten years.", "right": "I've lived here for ten years.", "note": "ระยะเวลา (ten years) ใช้ for ไม่ใช่ since (since ใช้กับจุดเริ่มต้นเท่านั้น)"}, "tip": "for = 'นานแค่ไหน' (จำนวนระยะเวลา), since = 'ตั้งแต่เมื่อไหร่' (จุดเริ่มต้นที่ระบุได้)", "summary": ["for + ระยะเวลา, since + จุดเริ่มต้น", "when...? ใช้ Past Simple, how long...? ใช้ Present Perfect", "ไม่ใช้ for กับ all..."]}, {"unit": 13, "section": "Present Perfect and Past", "title": "Present Perfect and Past 1 (I have done and I did)", "pattern": "have/has + V3 (ผลตอนนี้)  ⟷  V2 (แค่บอกอดีต)", "sections": [{"label": "A", "explain": "Present Perfect บอกสถานการณ์ ณ ตอนนี้ ส่วน Past Simple บอกแค่ว่าเกิดอะไรในอดีต (ไม่รู้ผลลัพธ์ตอนนี้)", "examples": ["They've gone away. They'll be back on Friday. (ตอนนี้ยังไม่อยู่)", "They went away, but I think they're back home now.", "Tom has lost his key. (ตอนนี้ยังหาไม่เจอ)", "Did he lose his key? Yes. Has he found it? Yes, he has now."]}, {"label": "B", "explain": "ใช้ Present Perfect กับข่าว/เหตุการณ์ใหม่ แต่ใช้ Past Simple กับเรื่องที่ไม่ใหม่แล้วหรือเป็นประวัติศาสตร์", "examples": ["I've repaired the washing machine. It's working now.", "Mozart wrote more than 600 pieces of music. (not 'has written' — ประวัติศาสตร์)", "Who invented the telephone? (not 'has invented')"]}], "notes": ["เมื่อเริ่มเล่าเรื่องต่อจาก Present Perfect (ให้ข้อมูลใหม่) มักเปลี่ยนไปใช้ Past Simple ในประโยคถัดไป: 'I've burnt myself.' 'How did you do that?'"], "mistake": {"wrong": "Mozart has written more than 600 pieces of music.", "right": "Mozart wrote more than 600 pieces of music.", "note": "เรื่องประวัติศาสตร์หรือบุคคลที่เสียชีวิตแล้ว ใช้ Past Simple ไม่ใช่ Present Perfect"}, "tip": "ถามตัวเองว่า 'เรื่องนี้ยังส่งผลถึงตอนนี้ไหม (Present Perfect) หรือจบไปแล้วในอดีตไม่เกี่ยวกับตอนนี้ (Past Simple)?'", "summary": ["Present Perfect: ผลยังอยู่ถึงตอนนี้/ข่าวใหม่", "Past Simple: แค่บอกว่าเกิดอะไรในอดีต", "ประวัติศาสตร์/คนที่เสียชีวิตแล้ว ใช้ Past Simple เสมอ"]}, {"unit": 14, "section": "Present Perfect and Past", "title": "Present Perfect and Past 2 (I have done and I did)", "pattern": "Present Perfect (เวลาที่ยังไม่จบ)  ⟷  Past Simple (เวลาที่จบแล้ว)", "sections": [{"label": "A", "explain": "ไม่ใช้ Present Perfect กับเวลาที่จบไปแล้วชัดเจน (yesterday, last year, ... ago) ต้องใช้ Past Simple เท่านั้น", "examples": ["It was cold yesterday. (not 'has been')", "Paul arrived ten minutes ago. (not 'has arrived')", "When did your friends arrive? (not 'have arrived')"]}, {"label": "B", "explain": "เปรียบเทียบช่วงเวลาที่ยังไม่จบ (today, this week, since 2010) กับช่วงเวลาที่จบแล้ว (yesterday, last week)", "examples": ["It hasn't rained this week. / It didn't rain last week.", "Have you seen Anna this morning? (ยังเป็นตอนเช้าอยู่)", "Did you see Anna this morning? (ตอนนี้เป็นบ่ายหรือเย็นแล้ว)", "I've never ridden a horse. / I never rode a bike as a child."]}], "notes": ["ตัวช่วยจำ: yesterday / ... ago / last... = Past Simple เสมอ, today / this week / since... = ใช้ Present Perfect ได้ถ้าช่วงเวลานั้นยังไม่จบ"], "mistake": {"wrong": "I have seen that movie last week.", "right": "I saw that movie last week.", "note": "'last week' เป็นเวลาที่จบไปแล้ว ต้องใช้ Past Simple ไม่ใช่ Present Perfect"}, "tip": "เจอคำว่า yesterday, ago, last + เวลา ให้ตัด Present Perfect ทิ้งได้เลย ต้องเป็น Past Simple เท่านั้น", "summary": ["เวลาที่จบแล้ว (yesterday, ago, last...) ใช้ Past Simple เท่านั้น", "เวลาที่ยังไม่จบ (today, this week) ใช้ Present Perfect ได้", "When...? ใช้ Past Simple เสมอ"], "timeline": [{"label": "Past Simple", "note": "เวลาที่จบแล้ว: yesterday, last week", "start": 5, "end": 30, "style": "solid"}, {"label": "Present Perfect", "note": "เวลาที่ยังไม่จบ: today, this week", "start": 30, "end": 50, "style": "solid"}]}, {"unit": 15, "section": "Present Perfect and Past", "title": "Past Perfect (I had done)", "pattern": "had + V3", "sections": [{"label": "A", "explain": "ใช้บอกเหตุการณ์ที่เกิดขึ้นก่อนอีกเหตุการณ์หนึ่งในอดีต (เปรียบเหมือน 'อดีตของอดีต')", "examples": ["When Sarah arrived at the party, Paul had already gone home.", "When we got home, we found that somebody had broken into the flat.", "Karen didn't come to the cinema. She'd already seen the movie.", "They hadn't flown before."]}, {"label": "B", "explain": "เปรียบเทียบ Present Perfect (พูดจากมุมมองปัจจุบัน) กับ Past Perfect (เล่าเรื่องในอดีต)", "examples": ["I've seen her before, but I can't remember where. (Present Perfect)", "I'd seen her before, but I couldn't remember where. (Past Perfect - เล่าเรื่องในอดีต)", "Was Tom there when you arrived? No, he'd already left."]}], "notes": ["Past Perfect มักใช้เมื่อมีจุดอ้างอิงเวลาในอดีต (เช่น 'when Sarah arrived') แล้วพูดถึงสิ่งที่เกิดขึ้นก่อนจุดนั้น"], "mistake": {"wrong": "When Sarah arrived, Paul already left.", "right": "When Sarah arrived, Paul had already left.", "note": "เหตุการณ์ที่เกิดก่อนอีกเหตุการณ์หนึ่งในอดีต ต้องใช้ Past Perfect (had + V3)"}, "tip": "ถ้ามีสองเหตุการณ์ในอดีตและต้องการบอกว่าอันไหนเกิดก่อน ให้ใช้ Past Perfect กับเหตุการณ์ที่เกิดก่อน", "summary": ["Past Perfect = 'อดีตของอดีต'", "โครงสร้าง: had + V3", "ใช้เมื่อมีจุดอ้างอิงเวลาในอดีตแล้วพูดถึงสิ่งที่เกิดก่อนหน้านั้น"], "timeline": [{"label": "Past Perfect", "note": "Paul had gone home (เกิดก่อน)", "start": 5, "end": 15, "style": "dot"}, {"label": "Past Simple", "note": "Sarah arrived (จุดอ้างอิง)", "start": 22, "end": 22, "style": "dot"}]}, {"unit": 16, "section": "Present Perfect and Past", "title": "Past Perfect Continuous (I had been doing)", "pattern": "had been + V-ing", "sections": [{"label": "A", "explain": "ใช้บอกกิจกรรมที่ดำเนินอยู่ก่อนหน้าจุดหนึ่งในอดีต (มักเป็นสาเหตุของสิ่งที่พบในอดีต)", "examples": ["The ground was wet. It had been raining.", "My hands were dirty because I'd been repairing my bike.", "Tom was tired. He'd been working hard all day."]}, {"label": "B", "explain": "ใช้บอกว่ากิจกรรมหนึ่งดำเนินไปนานแค่ไหนก่อนอีกเหตุการณ์หนึ่งจะเกิดขึ้น", "examples": ["We'd been playing tennis for half an hour when it started to rain.", "At last the bus came. I'd been waiting for 20 minutes."]}], "notes": ["กริยาบางตัว (know, have แบบครอบครอง) ไม่ใช้รูป continuous แม้เป็น Past Perfect: 'We had known each other for years' ไม่ใช่ 'had been knowing'"], "mistake": {"wrong": "I was tired because I worked all day.", "right": "I was tired because I had been working all day.", "note": "กิจกรรมที่ดำเนินมาก่อนหน้าและเป็นสาเหตุของผลลัพธ์ในอดีต ใช้ Past Perfect Continuous"}, "tip": "เทียบกับ Present Perfect Continuous: ถ้าเรื่องทั้งหมดอยู่ในอดีต (ก่อนอีกจุดหนึ่งในอดีต) ให้ใช้ 'had been' แทน 'have been'", "summary": ["โครงสร้าง: had been + V-ing", "ใช้กับกิจกรรมที่ดำเนินอยู่ก่อนอีกเหตุการณ์หนึ่งในอดีต", "know, have (ครอบครอง) ไม่ใช้ continuous"]}, {"unit": 17, "section": "Present Perfect and Past", "title": "have and have got", "pattern": "have / have got (ความหมายเดียวกันสำหรับการครอบครอง)", "sections": [{"label": "A", "explain": "have กับ have got ใช้แทนกันได้เมื่อพูดถึงการครอบครอง ความสัมพันธ์ อาการป่วย หรือนัดหมาย", "examples": ["They have a new car. / They've got a new car.", "I have a headache. / I've got a headache.", "Lisa had long hair when she was young. (อดีตใช้ 'had' เฉยๆ ไม่ใช้ 'got')"]}, {"label": "B", "explain": "have (ไม่ใช้ have got) ใช้กับวลีกิจกรรม เช่น have breakfast, have a shower, have a good time", "examples": ["I have a sandwich for lunch. (not 'I've got')", "He's having a shower. (ใช้ continuous ได้เพราะเป็นกิจกรรม)", "Did you have trouble finding the place?"]}], "notes": ["คำถาม/ปฏิเสธมี 3 แบบ: 'Do you have...?' / 'Have you got...?' / 'Have you...?' (แบบหลังไม่ค่อยนิยมแล้วในปัจจุบัน)"], "mistake": {"wrong": "I'm having a headache.", "right": "I have a headache. / I've got a headache.", "note": "'have a headache' หมายถึงการครอบครองอาการ ไม่ใช้รูป continuous"}, "tip": "ถ้า have แปลว่า 'มี/เป็น' (ครอบครอง) ห้ามใช้ continuous แต่ถ้า have เป็นส่วนหนึ่งของวลีกิจกรรม (have breakfast/a shower) ใช้ continuous ได้ตามปกติ", "summary": ["have = have got (ความหมายเดียวกันสำหรับครอบครอง)", "have breakfast/a shower ฯลฯ ใช้ do/does ในคำถาม ไม่ใช้ have got", "อดีตใช้ 'had' เฉยๆ ไม่ใช้ 'had got'"]}, {"unit": 18, "section": "Present Perfect and Past", "title": "used to (do)", "pattern": "used to + V1", "sections": [{"label": "A", "explain": "ใช้บอกสิ่งที่เคยทำเป็นประจำในอดีตแต่ตอนนี้ไม่ได้ทำแล้ว", "examples": ["She used to travel a lot, but she doesn't travel much these days.", "I used to play tennis a lot, but I don't play much now.", "'Do you go to the cinema much?' 'Not now, but I used to.'"]}, {"label": "B", "explain": "ใช้บอกสภาพที่เคยเป็นจริงในอดีตแต่ตอนนี้ไม่จริงแล้ว", "examples": ["This building used to be a cinema.", "I used to think he was unfriendly, but now I know he's a nice person.", "There used to be four cinemas in town. Now there's only one."]}], "notes": ["คำถามใช้ 'Did you use to...?' ปฏิเสธใช้ 'didn't use to...' — 'used to' ไม่มีรูปปัจจุบัน ('I use to do' ผิดหลักไวยากรณ์ ต้องใช้ Present Simple ธรรมดาแทนถ้าพูดถึงปัจจุบัน)", "ระวังสับสนกับ 'be used to doing' (คุ้นเคยกับการทำ) ซึ่งความหมายต่างกันโดยสิ้นเชิงจาก 'used to do' (เคยทำในอดีต)"], "mistake": {"wrong": "I use to play football when I was young.", "right": "I used to play football when I was young.", "note": "'used to' ไม่มีรูปปัจจุบัน ต้องใช้ 'used to' เสมอเมื่อพูดถึงอดีต ('use to' ผิดหลักไวยากรณ์)"}, "tip": "'used to do' (เคยทำ ตอนนี้ไม่ทำแล้ว) ต่างจาก 'be used to doing' (คุ้นเคยกับการทำ) — อย่าสับสนสองโครงสร้างนี้", "summary": ["used to + V1 = เคยทำ/เคยเป็นประจำ แต่ตอนนี้ไม่ใช่แล้ว", "คำถาม: Did you use to...? ปฏิเสธ: didn't use to...", "ต่างจาก 'be used to doing' (คุ้นเคย) โดยสิ้นเชิง"]}, {"unit": 19, "section": "Future", "title": "Present Tenses for the Future (I am doing / I do)", "pattern": "Present Continuous (แผนที่จัดไว้แล้ว)  /  Present Simple (ตารางเวลา)", "sections": [{"label": "A", "explain": "Present Continuous ใช้กับสิ่งที่ตัดสินใจและจัดเตรียมไว้แล้วสำหรับอนาคต (นัดหมายส่วนตัว)", "examples": ["What are you doing on Saturday evening? (not 'What do you do')", "I'm going to the cinema this evening.", "We're meeting her at the station tomorrow.", "Steve isn't playing football next Saturday. He's hurt his leg."]}, {"label": "B", "explain": "Present Simple ใช้กับตารางเวลาที่แน่นอนตายตัว (รถไฟ หนัง กำหนดการ)", "examples": ["My train leaves at 11.30.", "What time does the film start tonight?", "The meeting is at nine o'clock tomorrow.", "I start my new job on Monday."]}], "notes": ["ไม่ใช้ will กับสิ่งที่ตัดสินใจ/จัดเตรียมไว้แล้ว: 'What are you doing tonight?' ไม่ใช่ 'What will you do tonight?'", "นัดหมาย/เรียน/สอบ สามารถใช้ 'have' หรือ 'have got': 'I have an exam next week.' / 'I've got an exam next week.'"], "mistake": {"wrong": "What will you do this weekend?", "right": "What are you doing this weekend?", "note": "แผนที่ตัดสินใจ/จัดไว้แล้วสำหรับอนาคต ใช้ Present Continuous ไม่ใช่ will"}, "tip": "แยกให้ออก: นัดหมายส่วนตัว (meeting, party) → Present Continuous, ตารางเวลาตายตัว (รถไฟ, หนัง, ชั้นเรียน) → Present Simple", "summary": ["Present Continuous: แผนที่วางไว้แล้วสำหรับอนาคต", "Present Simple: ตารางเวลา/กำหนดการที่แน่นอน", "ไม่ใช้ will กับสิ่งที่ตัดสินใจไว้แล้ว"]}, {"unit": 20, "section": "Future", "title": "I'm going to (do)", "pattern": "am/is/are + going to + V1", "sections": [{"label": "A", "explain": "ใช้บอกสิ่งที่ตั้งใจ/ตัดสินใจจะทำ (อาจยังไม่ได้นัดหมายกับใครก็ได้)", "examples": ["'Are you going to eat anything?' 'No, I'm not hungry.'", "She's going to buy a new car.", "This cheese smells horrible. I'm not going to eat it."]}, {"label": "B", "explain": "ใช้ทำนายจากหลักฐานที่เห็นอยู่ตรงหน้าตอนนี้", "examples": ["Look at those black clouds! It's going to rain.", "The man is walking towards the wall. He's going to walk into it.", "I feel terrible. I think I'm going to be sick."]}, {"label": "C", "explain": "was/were going to ใช้บอกสิ่งที่ตั้งใจจะทำ แต่สุดท้ายไม่ได้ทำจริง", "examples": ["We were going to travel by train, but we decided to drive instead.", "I thought it was going to rain, but it didn't."]}], "notes": ["เปรียบเทียบ: 'I'm doing' (นัดหมายแน่นอนแล้วกับใครสักคน) ต่างจาก 'I'm going to do' (แค่ตัดสินใจ อาจยังไม่ได้นัดกับใคร)"], "mistake": {"wrong": "Look at the sky! It will rain.", "right": "Look at the sky! It's going to rain.", "note": "มีหลักฐานที่เห็นตรงหน้าตอนนี้ (เมฆดำ) ต้องใช้ 'be going to' ไม่ใช่ will"}, "tip": "'was/were going to' ใช้เล่าแผนที่ตั้งใจไว้แต่สุดท้ายไม่ได้ทำจริง", "summary": ["be going to = ตั้งใจ/ทำนายจากหลักฐานตอนนี้", "was/were going to = ตั้งใจแต่ไม่ได้ทำ", "ต่างจาก Present Continuous ตรงที่ยังไม่จำเป็นต้องนัดกับใคร"]}, {"unit": 21, "section": "Future", "title": "will and shall 1", "pattern": "will/I'll + V1 (ตัดสินใจสดๆ ตอนพูด)", "sections": [{"label": "A", "explain": "ใช้ประกาศการตัดสินใจ ณ ตอนพูด (offer / agree / promise)", "examples": ["Oh, I left the door open. I'll go and shut it.", "'What would you like to drink?' 'I'll have orange juice, please.'", "That bag looks heavy. I'll help you with it.", "Thanks for lending me the money. I'll pay you back on Friday."]}, {"label": "B", "explain": "won't ใช้บอกว่าใครบางคน/สิ่งของ 'ปฏิเสธ' หรือ 'ไม่ยอม' ทำ, Will you...? ใช้ขอร้อง", "examples": ["I've tried to give her advice, but she won't listen.", "The car won't start.", "Will you please turn the music down? It's too loud."]}], "notes": ["ไม่ใช้ will กับสิ่งที่ตัดสินใจ/นัดหมายไว้ล่วงหน้าแล้ว: 'I'm going on holiday next Saturday.' ไม่ใช่ 'I'll go...'", "มักใช้คู่กับ 'I think I'll...' / 'I don't think I'll...'"], "mistake": {"wrong": "I'll go on holiday next Saturday. (แผนที่จองตั๋วไว้ล่วงหน้าแล้ว)", "right": "I'm going on holiday next Saturday.", "note": "สิ่งที่จัดเตรียม/นัดหมายไว้ก่อนแล้ว ใช้ Present Continuous ไม่ใช่ will"}, "tip": "will ใช้ตอนตัดสินใจสดๆ ระหว่างพูด ถ้าตัดสินใจไปก่อนหน้าแล้ว ให้ใช้ Present Continuous หรือ be going to แทน", "summary": ["will/I'll = ตัดสินใจสดๆ ตอนพูด (offer/promise/agree)", "won't = ปฏิเสธไม่ยอมทำ", "shall I/we...? ใช้ถามความเห็น/เสนอแนะ"]}, {"unit": 22, "section": "Future", "title": "will and shall 2", "pattern": "will/won't (ทำนาย/คาดการณ์อนาคต)", "sections": [{"label": "A", "explain": "ใช้ทำนายสิ่งที่เชื่อว่าจะเกิดขึ้น (ต่างจากสิ่งที่ตัดสินใจไปแล้ว)", "examples": ["Joe believes that Kate will pass the driving test.", "That plate is hot. If you touch it, you'll burn yourself.", "Anna looks completely different now. You won't recognise her."]}, {"label": "B", "explain": "มักใช้คู่กับ probably, I'm sure, I think, I don't think, I wonder", "examples": ["I'll probably be home late tonight.", "Don't worry about the exam. I'm sure you'll pass.", "I don't think the exam will be very difficult."]}], "notes": ["หลัง 'I hope' มักใช้ Present Simple แทน will: 'I hope it doesn't rain tomorrow.'", "shall ใช้กับ I/we เท่านั้น (ทางการ) ในภาษาพูดทั่วไปมักใช้ I'll/we'll แทน"], "mistake": {"wrong": "I hope it will not rain tomorrow.", "right": "I hope it doesn't rain tomorrow.", "note": "หลัง 'hope' มักใช้ Present Simple แทน will ในภาษาพูดทั่วไป"}, "tip": "จำคำสัญญาณ: probably, I'm sure, I think, I don't think มักตามด้วย will เพราะเป็นการคาดการณ์/ทำนาย", "summary": ["will/won't ใช้ทำนายสิ่งที่เชื่อว่าจะเกิดขึ้น", "มักคู่กับ probably, I'm sure, I think", "shall ใช้กับ I/we เท่านั้น (ทางการ)"]}, {"unit": 23, "section": "Future", "title": "I will and I'm going to", "pattern": "will (ตัดสินใจใหม่)  ⟷  be going to (ตัดสินใจไว้ก่อนแล้ว)", "sections": [{"label": "A", "explain": "will ใช้ประกาศการตัดสินใจใหม่ ณ ตอนพูด ส่วน going to ใช้เมื่อตัดสินใจไว้ล่วงหน้าแล้ว", "examples": ["'Anna is in hospital.' 'Really? I didn't know. I'll go and visit her.' (ตัดสินใจตอนนี้)", "'Anna is in hospital.' 'Yes, I know. I'm going to visit her this evening.' (ตัดสินใจไว้ก่อนแล้ว)", "Let's have a party. We'll invite lots of people.", "Sarah and I have decided to have a party. We're going to invite lots of people."]}, {"label": "B", "explain": "ทำนายเหตุการณ์ในอนาคตใช้ได้ทั้ง will และ going to แต่ going to เน้นหลักฐานที่เห็นตอนนี้", "examples": ["I think the weather will be nice later. / I think the weather is going to be nice later.", "Look at those black clouds. It's going to rain. (not 'it will rain')", "Jane will be late. She's always late. (คาดจากนิสัย ไม่ใช่หลักฐานตอนนี้)"]}], "notes": [], "mistake": {"wrong": "We've decided to have a party. We'll invite lots of people.", "right": "We've decided to have a party. We're going to invite lots of people.", "note": "เมื่อตัดสินใจไว้ล่วงหน้าแล้ว ต้องใช้ be going to ไม่ใช่ will"}, "tip": "will = ตัดสินใจสดๆ ตอนนี้, be going to = ตัดสินใจไปก่อนหน้าแล้ว หรือมีหลักฐานให้เห็นตอนนี้", "summary": ["will: ประกาศการตัดสินใจใหม่", "be going to: ตัดสินใจไว้ล่วงหน้าแล้ว/มีหลักฐานตอนนี้", "ทำนายอนาคตใช้ได้ทั้งสองแบบ"]}, {"unit": 24, "section": "Future", "title": "will be doing and will have done", "pattern": "will be + V-ing (Future Continuous)  /  will have + V3 (Future Perfect)", "sections": [{"label": "A", "explain": "Future Continuous ใช้บอกว่าจะกำลังทำอะไรอยู่ ณ จุดหนึ่งในอนาคต", "examples": ["This time next week I'll be lying on the beach.", "Don't phone between 7 and 8. We'll be eating.", "At 10 o'clock tomorrow, she will be working."]}, {"label": "B", "explain": "Future Perfect ใช้บอกว่าจะเสร็จสิ้น/สมบูรณ์ก่อนจุดหนึ่งในอนาคต", "examples": ["She won't be at home at 9 — she'll have gone to work.", "The film will already have started by the time we get there.", "Next year they will have been married for 25 years."]}], "notes": ["Future Continuous ยังใช้พูดถึงเหตุการณ์ที่จะเกิดขึ้นแน่นอนในอนาคตได้ด้วย ไม่ใช่แค่ 'กำลังทำอยู่': 'The team's star player won't be playing on Saturday.'"], "mistake": {"wrong": "By 9 o'clock, she will go to work already.", "right": "By 9 o'clock, she will have gone to work already.", "note": "เหตุการณ์ที่จะเสร็จสิ้นก่อนจุดหนึ่งในอนาคต ต้องใช้ Future Perfect (will have + V3)"}, "tip": "Future Continuous บอก 'กำลังทำอยู่ ณ จุดนั้น', Future Perfect บอก 'เสร็จไปแล้วก่อนจุดนั้น' — คำว่า 'by' มักเป็นสัญญาณของ Future Perfect", "summary": ["Future Continuous: will be + V-ing (กำลังทำอยู่)", "Future Perfect: will have + V3 (เสร็จก่อนจุดหนึ่ง)", "'by + เวลา' มักเป็นสัญญาณ Future Perfect"]}, {"unit": 25, "section": "Future", "title": "when I do and when I've done / if and when", "pattern": "when/if/while/before/after/until + Present Simple (ห้ามใช้ will)", "sections": [{"label": "A", "explain": "หลัง when, while, before, after, as soon as, until ที่พูดถึงอนาคต ห้ามใช้ will ให้ใช้ Present Simple แทน", "examples": ["I'll call you when I arrive. (not 'when I will arrive')", "We'll go out when it stops raining. (not 'when it will stop')", "Wait here until I come back.", "What are you going to do while I'm away?"]}, {"label": "B", "explain": "ใช้ Present Perfect หลัง when/after/until เพื่อบอกว่าสิ่งหนึ่งเสร็จสิ้นก่อนอีกสิ่งหนึ่งจะเกิดขึ้น", "examples": ["Can I have the newspaper when you've finished with it?", "When I've phoned Kate, we can go out. (โทรก่อน แล้วค่อยออกไป)", "I'll come as soon as I've finished."]}, {"label": "C", "explain": "ใช้ if (ไม่ใช่ when) กับสิ่งที่ไม่แน่ว่าจะเกิดหรือไม่ ส่วน when ใช้กับสิ่งที่แน่นอนว่าจะเกิด", "examples": ["If it's raining this evening, I won't go out. (ไม่แน่ว่าจะตกไหม)", "I'm going out later. When I go out, I'll get some bread. (แน่นอนว่าจะออกไป)", "Don't worry if I'm late tonight."]}], "notes": [], "mistake": {"wrong": "I'll call you when I will arrive.", "right": "I'll call you when I arrive.", "note": "หลัง when/if/while/before/after/until ที่พูดถึงอนาคต ห้ามใช้ will ต้องใช้ Present Simple แทน"}, "tip": "ถ้าสองเหตุการณ์เกิดพร้อมกัน ใช้ Present Simple ('when I phone, I'll ask...') แต่ถ้าอันหนึ่งต้องเสร็จก่อนอีกอันจะเริ่ม ใช้ Present Perfect ('when I've phoned, we can go...')", "summary": ["หลัง when/if/while/before/after/until ห้ามใช้ will", "ใช้ Present Perfect ถ้าเหตุการณ์หนึ่งเสร็จก่อนอีกอันจะเกิด", "if = ไม่แน่นอนว่าจะเกิด, when = แน่นอนว่าจะเกิด"]}, {"unit": 26, "section": "Modals", "title": "can, could and (be) able to", "pattern": "can/could + V1 (ความสามารถ/อนุญาต/ความเป็นไปได้)", "sections": [{"label": "A", "explain": "can ใช้บอกความสามารถ การอนุญาต หรือความเป็นไปได้", "examples": ["We can see the lake from our hotel.", "Can you speak any foreign languages?", "I can come and see you tomorrow.", "I'm afraid I can't come to the party."]}, {"label": "B", "explain": "could ใช้กับความสามารถทั่วไปในอดีต และกับกริยารับรู้ (see, hear, smell, taste, feel, remember, understand)", "examples": ["My grandfather could speak five languages.", "I could see them, but not very clearly.", "As soon as I walked in, I could smell gas."]}, {"label": "C", "explain": "เมื่อพูดถึงความสำเร็จในสถานการณ์เฉพาะครั้งเดียว ต้องใช้ was/were able to หรือ managed to แทน could", "examples": ["The fire spread quickly, but everybody was able to escape. (not 'could escape')", "I didn't know where Max was, but I managed to find him in the end.", "Jack could beat anybody. (ความสามารถทั่วไป) but Jack managed to beat Andy yesterday. (ความสำเร็จครั้งเดียว)"]}], "notes": ["can มีแค่ 2 รูป: can (ปัจจุบัน) และ could (อดีต) เมื่อต้องการรูปอื่น (future, perfect) ต้องใช้ (be) able to แทน เช่น 'I haven't been able to sleep recently.'", "couldn't ใช้ได้ในทุกสถานการณ์ (ทั้งความสามารถทั่วไปและครั้งเดียว)"], "mistake": {"wrong": "The fire spread quickly, but everybody could escape.", "right": "The fire spread quickly, but everybody was able to escape.", "note": "ความสำเร็จในสถานการณ์เฉพาะครั้งเดียว ต้องใช้ 'was/were able to' หรือ 'managed to' ไม่ใช่ could"}, "tip": "could = ความสามารถทั่วไป/กริยารับรู้, was able to/managed to = ทำสำเร็จในสถานการณ์เฉพาะครั้งเดียว", "summary": ["can/could + V1 บอกความสามารถ/อนุญาต", "could ใช้กับความสามารถทั่วไปในอดีตและกริยารับรู้", "ความสำเร็จเฉพาะครั้ง ใช้ was/were able to หรือ managed to"]}, {"unit": 27, "section": "Modals", "title": "could (do) and could have (done)", "pattern": "could + V1 (ข้อเสนอแนะ/เป็นไปได้ตอนนี้)  /  could have + V3 (เป็นไปได้ในอดีตแต่ไม่เกิดขึ้น)", "sections": [{"label": "A", "explain": "could ใช้เสนอแนะสิ่งที่เป็นไปได้ตอนนี้หรืออนาคต (ไม่แน่ใจเท่า can)", "examples": ["'What shall we do tonight?' 'We could go to the cinema.'", "I'm so tired, I could sleep for a week.", "The story could be true, but I don't think it is."]}, {"label": "B", "explain": "could have + V3 ใช้พูดถึงสิ่งที่เป็นไปได้ในอดีต แต่ไม่ได้เกิดขึ้นจริง", "examples": ["Why did you stay at a hotel? You could have stayed with me.", "David could have hurt himself when he fell, but he's all right.", "The situation was bad, but it could have been worse."]}], "notes": ["couldn't = จะเป็นไปไม่ได้ (ตอนนี้/อนาคต): 'I couldn't live in a big city.'", "couldn't have + V3 = ไม่มีทางเป็นไปได้ในอดีต: 'It couldn't have been better.'"], "mistake": {"wrong": "You should stay with me. (ต้องการบอกว่ามีทางเลือกที่เป็นไปได้)", "right": "You could have stayed with me.", "note": "'could have' บอกว่ามีทางเลือกที่เป็นไปได้แต่ไม่ได้ทำ ต่างจาก 'should have' ที่บอกว่าควรทำ"}, "tip": "could + V1 = เป็นไปได้ตอนนี้/ข้อเสนอแนะ, could have + V3 = เป็นไปได้ในอดีตแต่ไม่ได้เกิดขึ้น", "summary": ["could ใช้เสนอแนะ/บอกความเป็นไปได้ตอนนี้", "could have + V3 = เป็นไปได้ในอดีตแต่ไม่เกิดขึ้นจริง", "couldn't have = เป็นไปไม่ได้เลยในอดีต"]}, {"unit": 28, "section": "Modals", "title": "must and can't", "pattern": "must + V1 (มั่นใจว่าจริง)  /  can't + V1 (มั่นใจว่าเป็นไปไม่ได้)", "sections": [{"label": "A", "explain": "must ใช้บอกว่าเชื่อว่าบางสิ่งเป็นความจริงแน่นอน ส่วน can't ใช้บอกว่าเชื่อว่าเป็นไปไม่ได้", "examples": ["You've been travelling all day. You must be tired.", "'Joe is a hard worker.' 'You must be joking.'", "You've just had lunch. You can't be hungry already.", "They haven't lived here long. They can't know many people."]}, {"label": "B", "explain": "สำหรับอดีตใช้ must have + V3 และ can't have + V3", "examples": ["They rang the doorbell twice, but nobody answered. They must have gone out.", "I lost one of my gloves. I must have dropped it somewhere.", "Sarah hasn't contacted me. She can't have got my message."]}], "notes": ["couldn't have ใช้แทน can't have ได้ ความหมายเหมือนกัน: 'Sarah couldn't have got my message.'"], "mistake": {"wrong": "You've just had lunch. You mustn't be hungry.", "right": "You've just had lunch. You can't be hungry already.", "note": "'can't' ใช้บอกว่าเชื่อว่าเป็นไปไม่ได้ ไม่ใช่ 'mustn't' (ซึ่งแปลว่าห้ามทำ)"}, "tip": "must = มั่นใจว่าจริง, can't = มั่นใจว่าเป็นไปไม่ได้ — ทั้งคู่เป็นการคาดเดา/อนุมานจากหลักฐาน ไม่ใช่คำสั่ง", "summary": ["must = เชื่อว่าจริงแน่นอน", "can't = เชื่อว่าเป็นไปไม่ได้", "อดีตใช้ must have/can't have + V3"]}, {"unit": 29, "section": "Modals", "title": "may and might 1", "pattern": "may/might (not) + V1 (เป็นไปได้)", "sections": [{"label": "A", "explain": "may และ might ใช้บอกว่าเป็นไปได้ (ความหมายใกล้เคียงกัน ใช้แทนกันได้เกือบตลอด)", "examples": ["It may be true. / It might be true.", "She might know. / She may know.", "It may not be true. (ปฏิเสธ)", "She might not know."]}, {"label": "B", "explain": "สำหรับอดีตใช้ may have + V3 หรือ might have + V3", "examples": ["'I wonder why Kate didn't answer.' 'She may have been asleep.'", "'I can't find my phone.' 'You might have left it at work.'", "She might not have known about it."]}], "notes": ["ระวังสะกดคำ: 'may be' (may+verb, 2 คำ) ต่างจาก 'maybe' (1 คำ, แปลว่า 'บางที')", "could ก็ใช้ความหมายใกล้เคียง may/might ได้ แต่ couldn't (ปฏิเสธ) มีความหมายต่างจาก may not/might not: couldn't = เป็นไปไม่ได้เลย, may not/might not = อาจจะไม่..."], "mistake": {"wrong": "Maybe true.", "right": "It may be true. / Maybe it's true.", "note": "'may be' (สองคำ) ใช้เป็นกริยา ส่วน 'maybe' (คำเดียว) ใช้เป็นคำวิเศษณ์แปลว่า 'บางที' วางหน้าประโยค"}, "tip": "may/might มักใช้แทนกันได้ ความหมายใกล้เคียงกันมาก (เป็นไปได้)", "summary": ["may/might + V1 = เป็นไปได้ (ปัจจุบัน/อนาคต)", "may/might have + V3 = เป็นไปได้ในอดีต", "may be (2 คำ) ≠ maybe (1 คำ)"]}, {"unit": 30, "section": "Modals", "title": "may and might 2", "pattern": "may/might + V1 (การกระทำที่อาจเกิดขึ้นในอนาคต)", "sections": [{"label": "A", "explain": "ใช้พูดถึงการกระทำ/เหตุการณ์ที่อาจเกิดขึ้นในอนาคต", "examples": ["I haven't decided where to go. I may go to Ireland.", "Take an umbrella. It might rain later.", "We might have to wait a few minutes."]}, {"label": "B", "explain": "ใช้ might (ไม่ใช่ may) เมื่อสถานการณ์เป็นเรื่องสมมติที่ไม่จริง", "examples": ["If they paid me better, I might work harder. (not 'I may work')", "Don't phone at 8.30. I might be watching the football."]}], "notes": ["might as well / may as well = ควรทำเพราะไม่มีทางเลือกที่ดีกว่า: 'I'm ready, so I might as well go now.'"], "mistake": {"wrong": "If they paid me better, I may work harder.", "right": "If they paid me better, I might work harder.", "note": "สถานการณ์สมมติที่ไม่เป็นจริง (unreal) ต้องใช้ might ไม่ใช่ may"}, "tip": "may/might ปกติใช้แทนกันได้ ยกเว้นสถานการณ์สมมติที่ไม่จริง (if-clause แบบ unreal) ต้องใช้ might เท่านั้น", "summary": ["may/might + V1 = อาจเกิดขึ้นในอนาคต", "สถานการณ์สมมติที่ไม่จริง ใช้ might เท่านั้น", "might as well/may as well = ควรทำเพราะไม่มีทางเลือกอื่นที่ดีกว่า"]}, {"unit": 31, "section": "Modals", "title": "have to and must", "pattern": "have to / must (จำเป็นต้องทำ)", "sections": [{"label": "A", "explain": "have to ใช้บอกว่าจำเป็นต้องทำ (มักเป็นข้อเท็จจริงภายนอก ไม่ใช่ความเห็นส่วนตัว)", "examples": ["You can't turn right here. You have to turn left.", "I have to wear glasses for reading.", "Robert has to work late.", "Last week Tina had to go to hospital."]}, {"label": "B", "explain": "must ใช้เมื่อให้ความเห็นส่วนตัวว่าจำเป็น ส่วน have to ใช้บอกข้อเท็จจริง/กฎที่มีอยู่แล้ว", "examples": ["I haven't spoken to Sue for ages. I must phone her. (ความเห็นตัวเอง)", "I have to work from 8.30 to 5.30 every day. (ข้อเท็จจริง)", "Applications must be received by 18 May. (กฎ/ข้อบังคับที่เป็นลายลักษณ์อักษร)"]}], "notes": ["คำถาม/ปฏิเสธของ have to ใช้ do/does/did: 'What do I have to do?' / 'Karen doesn't have to work Saturdays.'", "อดีตใช้ had to เท่านั้น (ไม่ใช้ must ในอดีต): 'I had to leave early.' (not 'I must leave')", "have got to ใช้แทน have to ได้: 'I've got to work tomorrow.'"], "mistake": {"wrong": "Yesterday I must go to the dentist.", "right": "Yesterday I had to go to the dentist.", "note": "อดีตต้องใช้ 'had to' เสมอ ไม่มีรูปอดีตของ must ที่ใช้ในความหมายนี้"}, "tip": "must ในเรื่องความจำเป็น ไม่มีรูปอดีต ต้องใช้ had to แทนเสมอเมื่อพูดถึงอดีต", "summary": ["have to = จำเป็นต้องทำ (ข้อเท็จจริง)", "must = ความเห็นส่วนตัวว่าจำเป็น หรือกฎที่เป็นลายลักษณ์อักษร", "อดีตใช้ had to เท่านั้น"]}, {"unit": 32, "section": "Modals", "title": "must, mustn't, needn't", "pattern": "must (จำเป็น) / mustn't (ห้าม) / needn't (ไม่จำเป็น)", "sections": [{"label": "A", "explain": "must = จำเป็นต้องทำ, mustn't = ห้ามทำ (ความหมายต่างกันโดยสิ้นเชิง ไม่ใช่แค่ปฏิเสธของ must)", "examples": ["Don't tell anybody. You must keep it a secret.", "You mustn't tell anyone. (= ห้ามบอกใคร)", "We must be very quiet. We mustn't make any noise."]}, {"label": "B", "explain": "needn't = ไม่จำเป็นต้องทำ (แต่ทำก็ได้ถ้าต้องการ) — ต่างจาก mustn't อย่างสิ้นเชิง", "examples": ["We have plenty of time. We needn't hurry.", "Joe can stay here. He needn't come with us.", "You needn't tell Steve. I can tell him myself. (ไม่จำเป็น) ต่างจาก 'You mustn't tell Steve.' (ห้ามบอก)"]}], "notes": ["needn't have + V3 = ทำไปแล้วแต่ที่จริงไม่จำเป็นเลย: 'They needn't have reserved a table.' (จองไปแล้วแต่ที่จริงไม่จำเป็น)", "didn't need to + V1 = ไม่จำเป็นต้องทำ (ไม่ได้บอกว่าทำหรือไม่ทำ): 'He didn't need to get up early, so he didn't.'"], "mistake": {"wrong": "You mustn't worry. Everything will be OK.", "right": "You needn't worry. Everything will be OK.", "note": "'ไม่จำเป็นต้องทำ' ใช้ needn't ไม่ใช่ mustn't (ซึ่งแปลว่าห้ามทำ)"}, "tip": "needn't (ไม่จำเป็น) กับ mustn't (ห้าม) มีความหมายต่างกันโดยสิ้นเชิง ห้ามสับสน! needn't have + V3 = ทำไปแล้วทั้งที่ไม่จำเป็น", "summary": ["must = จำเป็น, mustn't = ห้าม, needn't = ไม่จำเป็น", "needn't have + V3 = ทำไปแล้วแต่ไม่จำเป็น", "didn't need to = ไม่จำเป็นต้องทำ (ไม่ระบุว่าทำหรือไม่)"]}, {"unit": 33, "section": "Modals", "title": "should 1", "pattern": "should / shouldn't + V1 (คำแนะนำ/ความเห็น)", "sections": [{"label": "A", "explain": "should ใช้ให้คำแนะนำหรือความเห็นว่าอะไรดี/ถูกต้อง", "examples": ["You look tired. You should go to bed.", "The government should do more to improve schools.", "You shouldn't believe everything you read.", "I think you should apply for this job."]}, {"label": "B", "explain": "should ยังใช้บอกสิ่งที่คาดว่าจะเป็น/จะเกิดขึ้น (ถ้าไม่เป็นแบบนั้นแปลว่าผิดปกติ)", "examples": ["Where's Tina? She should be here by now.", "The price should be £2.50, not £3.50.", "Helen has studied hard, so she should pass."]}], "notes": ["should ไม่หนักแน่นเท่า must/have to: 'You should apologise.' (ควรทำ) ต่างจาก 'You must apologise.' (ไม่มีทางเลือกอื่น)", "ought to ใช้แทน should ได้เกือบทุกกรณี: 'You ought to apply.' = 'You should apply.'"], "mistake": {"wrong": "You must go to bed. (ต้องการให้คำแนะนำทั่วไป ไม่ใช่คำสั่งเด็ดขาด)", "right": "You should go to bed.", "note": "คำแนะนำทั่วไปที่ไม่เด็ดขาด ใช้ should ไม่ใช่ must (ซึ่งหนักแน่นกว่ามาก)"}, "tip": "should = ควรทำ (แนะนำ), must/have to = ต้องทำ (ไม่มีทางเลือก) — should เบากว่ามาก", "summary": ["should/shouldn't = คำแนะนำ/ความเห็น", "should เบากว่า must/have to มาก", "ought to ใช้แทน should ได้"]}, {"unit": 34, "section": "Modals", "title": "should 2 (should have done)", "pattern": "should have + V3 (ควรทำแต่ไม่ได้ทำ)", "sections": [{"label": "A", "explain": "should have + V3 = สิ่งที่ควรทำแต่ไม่ได้ทำ (เสียใจ/ตำหนิ), shouldn't have + V3 = ทำไปแล้วแต่ไม่ควรทำ", "examples": ["You missed a great party. You should have come.", "I'm feeling sick. I shouldn't have eaten so much.", "They should have been here long ago."]}, {"label": "B", "explain": "ใช้ should หลังกริยาบางกลุ่ม (insist, demand, recommend, suggest, propose) หรือหลังวลี 'It's important/essential that...'", "examples": ["Doctors recommend that everyone should eat plenty of fruit.", "It's essential that everyone should be here on time.", "I suggested that she should buy a car. (or 'that she buy a car')"]}], "notes": ["ไม่ใช้ 'to' หลัง suggest: 'What do you suggest we should do?' ไม่ใช่ 'suggest us to do'", "โครงสร้างที่ไม่มี should แต่ใช้กริยาช่องพื้นฐานเลย เรียกว่า subjunctive: 'I insisted that he apologise.'"], "mistake": {"wrong": "You should go to the party yesterday, but you didn't.", "right": "You should have gone to the party yesterday, but you didn't.", "note": "พูดถึงสิ่งที่ควรทำในอดีตแต่ไม่ได้ทำ ต้องใช้ 'should have + V3' ไม่ใช่ 'should + V1'"}, "tip": "should have + V3 มักแฝงความรู้สึกเสียใจหรือตำหนิว่าน่าจะทำ/ไม่น่าทำแบบนั้น", "summary": ["should have + V3 = ควรทำแต่ไม่ได้ทำ (เสียใจ/ตำหนิ)", "shouldn't have + V3 = ทำไปแล้วแต่ไม่ควรทำ", "should ใช้หลัง suggest/recommend/insist ได้"]}, {"unit": 35, "section": "Modals", "title": "I'd better / it's time", "pattern": "had better + V1  /  it's time + Past Simple", "sections": [{"label": "A", "explain": "had better (I'd better) = แนะนำอย่างจริงจัง ถ้าไม่ทำจะมีปัญหาหรืออันตราย", "examples": ["I have to meet Amy in ten minutes. I'd better go now or I'll be late.", "We'd better stop for petrol soon. The tank is almost empty.", "'That jacket looks good. Are you going to buy it?' 'I'd better not. It's very expensive.'"]}, {"label": "B", "explain": "it's time + Past Simple (ความหมายเป็นปัจจุบัน ไม่ใช่อดีต) = ถึงเวลาแล้วที่ควรทำ มักใช้ตำหนิ/บ่น", "examples": ["It's time to go home. / It's time for us to go home.", "It's time we went home. (ถึงเวลาแล้ว)", "It's time you did something about it. (ตำหนิว่าควรทำตั้งนานแล้ว)"]}], "notes": ["had better ใช้ตามด้วยกริยาช่องพื้นฐานเสมอ ไม่ใช้ 'to': 'We'd better take an umbrella.' (not 'to take')", "had better ต่างจาก should ตรงที่ใช้กับสถานการณ์เฉพาะที่มีอันตราย/ปัญหาถ้าไม่ทำตาม ไม่ใช่คำแนะนำทั่วไป"], "mistake": {"wrong": "You'd better to go now.", "right": "You'd better go now.", "note": "'had better' ตามด้วยกริยาช่องพื้นฐานเสมอ ไม่มี 'to'"}, "tip": "had better ใช้เฉพาะสถานการณ์เจาะจงที่มีผลเสียถ้าไม่ทำตาม ต่างจาก should ที่ใช้แนะนำทั่วไปได้", "summary": ["had better + V1 = ควรทำ ไม่งั้นมีปัญหา (เฉพาะสถานการณ์)", "it's time + Past Simple = ถึงเวลาแล้ว (ความหมายปัจจุบัน)", "had better ไม่ใช้ 'to' นำหน้ากริยา"]}, {"unit": 36, "section": "Modals", "title": "would", "pattern": "would ('d) / wouldn't (สมมติ/อดีตของ will)", "sections": [{"label": "A", "explain": "would ใช้จินตนาการสถานการณ์ที่ไม่เป็นจริง และ would have + V3 ใช้จินตนาการสิ่งที่ไม่เกิดขึ้นในอดีต", "examples": ["It would be nice to buy a new car, but we can't afford it.", "I'd love to live by the sea.", "You would have liked the film. (แต่คุณไม่ได้ดู)", "I would call Lisa, but I don't have her number."]}, {"label": "B", "explain": "would/wouldn't เป็นอดีตของ will/won't ในการเล่าคำพูด และ wouldn't ยังหมายถึง 'ปฏิเสธ/ไม่ยอมทำ' ได้ด้วย", "examples": ["Tom said he'd call me on Sunday. (จาก 'I'll call you')", "I tried to warn him, but he wouldn't listen to me.", "The car wouldn't start. (= 'ปฏิเสธ' ไม่สตาร์ท)"]}], "notes": ["would ใช้พูดถึงสิ่งที่เคยทำเป็นประจำในอดีต (คล้าย used to): 'Whenever Richard was angry, he would walk out of the room.'"], "mistake": {"wrong": "I will call Lisa, but I don't have her number.", "right": "I would call Lisa, but I don't have her number.", "note": "สถานการณ์สมมติ (ไม่มีเบอร์ ทำไม่ได้จริง) ต้องใช้ would ไม่ใช่ will"}, "tip": "would = จินตนาการ/สมมติ (ไม่จริง), will = แน่นอน/ตัดสินใจจริง — เทียบ will/would เหมือนเทียบ do/would do", "summary": ["would = สมมติสถานการณ์ที่ไม่จริง", "would have + V3 = จินตนาการสิ่งที่ไม่เกิดขึ้นในอดีต", "wouldn't = ปฏิเสธ/ไม่ยอมทำ หรือเป็นอดีตของ won't"]}, {"unit": 37, "section": "Modals", "title": "can/could/would you...? (Requests, offers, permission, invitations)", "pattern": "Can/Could you...? (ขอร้อง)  /  Would you like...? (เชิญชวน)", "sections": [{"label": "A", "explain": "can/could ใช้ขอร้องให้คนอื่นทำอะไรให้ หรือขอสิ่งของ", "examples": ["Can you wait a moment, please? / Could you wait a moment, please?", "Could you tell me how to get to the bus station?", "Can I have these postcards, please?", "May I have these postcards, please? (ทางการกว่า)"]}, {"label": "B", "explain": "can I / could I ใช้ขออนุญาตทำอะไรบางอย่าง", "examples": ["Can I speak to Steve, please?", "Do you think I could borrow your bike?", "May I ask you a question? (ทางการกว่า can/could)", "Do you mind if I use your phone charger?"]}, {"label": "C", "explain": "Would you like...? ใช้เชิญชวน/เสนอ (ไม่ใช่ Do you like...?)", "examples": ["'Would you like some coffee?' 'No, thanks.'", "Would you like to eat with us tonight?", "I'd like some information about hotels, please."]}], "notes": ["May เป็นทางการมากกว่า can/could", "'Would you like...?' ต่างจาก 'Do you like...?' โดยสิ้นเชิง — อันแรกคือชวน อันหลังคือถามความชอบทั่วไป"], "mistake": {"wrong": "Do you like some coffee?", "right": "Would you like some coffee?", "note": "เชิญชวน/เสนอสิ่งของ ใช้ 'Would you like...?' ไม่ใช่ 'Do you like...?' (ซึ่งถามความชอบทั่วไป)"}, "tip": "จำไว้: Would you like...? = เชิญชวน/เสนอ (ตอนนี้), Do you like...? = ถามความชอบทั่วไป (ไม่เกี่ยวกับตอนนี้)", "summary": ["can/could you...? = ขอร้องให้ทำอะไรให้", "can I/could I...? = ขออนุญาตทำเอง", "Would you like...? = เชิญชวน/เสนอ (ไม่ใช่ Do you like)"]}, {"unit": 38, "section": "if and wish", "title": "if I do... and if I did...", "pattern": "if + present, will + V1 (เป็นไปได้จริง)  /  if + past, would + V1 (ไม่คาดว่าจะเกิด)", "sections": [{"label": "A", "explain": "if + present tense ใช้เมื่อคิดว่าเป็นไปได้จริงในอนาคต", "examples": ["If we take the bus, it will be cheaper. (คิดว่าอาจจะขึ้นรถเมล์จริง)", "I'll be angry if it happens again.", "If you find it, can you call me?"]}, {"label": "B", "explain": "if + past tense (ความหมายไม่ใช่อดีต) ใช้เมื่อไม่คาดว่าจะเกิดขึ้นจริง หรือเป็นสถานการณ์สมมติ", "examples": ["If we took the bus, it would be cheaper, but the train is quicker. (ตัดสินใจนั่งรถไฟไปแล้ว)", "What would you do if you won a lot of money?", "If there was an election tomorrow, who would you vote for?"]}], "notes": ["ห้ามใช้ would ใน if-clause: 'If we went by bus...' ไม่ใช่ 'If we would go...'", "could/might ใช้แทน would ได้ในส่วนผลลัพธ์: 'If I won a lot of money, I might buy a house.'"], "mistake": {"wrong": "If we would go by bus, it would be cheaper.", "right": "If we went by bus, it would be cheaper.", "note": "ห้ามใช้ would ใน if-clause เด็ดขาด ต้องใช้ Past Simple แทน"}, "tip": "if + present = คิดว่าเป็นไปได้จริง, if + past = ไม่คาดว่าจะเกิด/เป็นสมมติ (ความหมายไม่ใช่อดีต)", "summary": ["if + present, will = เป็นไปได้จริง", "if + past, would = ไม่คาดว่าจะเกิด/สมมติ", "ห้ามใช้ would ใน if-clause"]}, {"unit": 39, "section": "if and wish", "title": "if I knew... / I wish I knew...", "pattern": "if + past simple, would + V1 (สถานการณ์สมมติในปัจจุบัน)", "sections": [{"label": "A", "explain": "ใช้ if + past เพื่อจินตนาการสถานการณ์ที่ไม่จริงในปัจจุบัน (ความหมายเป็นปัจจุบัน ไม่ใช่อดีต)", "examples": ["I'd phone him if I knew his number. (แต่ไม่รู้เบอร์)", "There are many things I'd like to do if I had more time.", "If you were in my position, what would you do?"]}, {"label": "B", "explain": "ใช้ were แทน was ได้ทั้งหลัง if และ wish (ทางการกว่า แต่ was ก็ใช้ได้เช่นกัน)", "examples": ["If I were you, I wouldn't buy that coat. / If I was you, ...", "I wish Anna were here. / I wish Anna was here."]}], "notes": ["wish + past ใช้แสดงความเสียใจ/ไม่พอใจกับสิ่งที่เป็นอยู่ปัจจุบัน: 'I wish I knew Paul's number.' (ไม่รู้ และเสียใจ)", "ห้ามใช้ 'wish...would' ในความหมายนี้: 'I wish I had something to read.' ไม่ใช่ 'I wish I would have'"], "mistake": {"wrong": "I wish I would have more time.", "right": "I wish I had more time.", "note": "หลัง wish (พูดถึงปัจจุบัน) ใช้ Past Simple ไม่ใช่ would have"}, "tip": "if/wish + past tense ไม่ได้แปลว่าอดีต แต่หมายถึงสิ่งที่ไม่จริงในปัจจุบัน — นี่คือจุดที่มักสับสน", "summary": ["if + past simple, would = สมมติในปัจจุบัน", "wish + past = เสียใจกับสิ่งที่เป็นอยู่ตอนนี้", "were ใช้แทน was ได้หลัง if/wish"]}, {"unit": 40, "section": "if and wish", "title": "if I had known... / I wish I had known...", "pattern": "if + had + V3, would have + V3 (สมมติตรงข้ามอดีต)", "sections": [{"label": "A", "explain": "ใช้พูดถึงสิ่งที่ตรงข้ามกับความจริงในอดีต (ไม่ได้เกิดขึ้นจริง)", "examples": ["If I'd known you were in hospital, I would have gone to visit you.", "They would have gone out if they hadn't been so tired.", "If you'd been looking, you wouldn't have walked into the wall."]}, {"label": "B", "explain": "wish + had + V3 ใช้เสียใจกับสิ่งที่เกิด/ไม่เกิดในอดีต", "examples": ["I wish I'd known that Gary was ill. I would have gone to see him.", "I feel sick. I wish I hadn't eaten so much.", "I wish it had been warmer. (not 'I wish it would have been')"]}], "notes": ["could have/might have ใช้แทน would have ได้: 'If the weather hadn't been bad, we could have gone out.'", "ห้ามพูด 'if something would have happened' — ต้องใช้ would ในส่วนผล ไม่ใช่ใน if-clause"], "mistake": {"wrong": "If I would have seen you, I would have said hello.", "right": "If I had seen you, I would have said hello.", "note": "if-clause ใช้ had + V3 (ไม่ใช้ would have) ส่วน would have ใช้ในส่วนผลลัพธ์เท่านั้น"}, "tip": "Third Conditional พูดถึง 'ถ้าเป็นแบบนั้นในอดีต...' แต่ความจริงไม่ได้เป็นแบบนั้น — ทั้งประโยคอ้างถึงอดีตทั้งหมด", "summary": ["if + had + V3, would have + V3 = สมมติตรงข้ามอดีต", "wish + had + V3 = เสียใจกับสิ่งที่เกิด/ไม่เกิดในอดีต", "ห้ามใช้ would have ใน if-clause"]}, {"unit": 41, "section": "if and wish", "title": "wish", "pattern": "wish + V2/V3/would + V1 (ความปรารถนา/เสียใจ)", "sections": [{"label": "A", "explain": "wish + somebody + something (luck, all the best) ต่างจาก wish + that-clause — ถ้าไม่ใช่การอวยพร ต้องใช้ hope แทน", "examples": ["I wish you all the best in the future.", "I hope you feel better soon. (not 'I wish you feel')", "I hope you enjoy your stay. (not 'I wish you enjoy')"]}, {"label": "B", "explain": "I wish I could (do) = เสียใจที่ทำไม่ได้ (ปัจจุบัน), I wish I could have (done) = เสียใจที่ทำไม่ได้ (อดีต)", "examples": ["I wish you could stay longer. (แต่คุณทำไม่ได้)", "I wish I could remember his name.", "I wish I could have gone to the party. (แต่ไปไม่ได้)"]}, {"label": "C", "explain": "I wish...would ใช้เมื่ออยากให้บางอย่างเกิดขึ้น/เปลี่ยนแปลง (มักใช้บ่น)", "examples": ["I wish it would stop raining.", "I wish somebody would answer the phone.", "I wish you wouldn't keep interrupting me."]}], "notes": ["'I wish...would' ใช้กับสิ่งที่อยากให้เกิดขึ้น ไม่ใช้กับสภาพที่อยากให้เป็น: 'I wish Sarah would come.' (อยากให้เธอมา) ต่างจาก 'I wish Sarah was here.' (ไม่ใช่ would be)"], "mistake": {"wrong": "I wish I would have a car.", "right": "I wish I had a car.", "note": "เมื่อพูดถึงสภาพที่อยากให้เป็น (ไม่ใช่การกระทำที่อยากให้เกิดขึ้น) ห้ามใช้ 'wish...would' ให้ใช้ 'wish + past simple' แทน"}, "tip": "wish somebody something (luck) / hope + that-clause / wish + past (เสียใจปัจจุบัน) / wish + had+V3 (เสียใจอดีต) / wish + would (อยากให้เปลี่ยน)", "summary": ["wish somebody something (luck/success) ต่างจาก wish + clause", "wish + could (have) = เสียใจที่ทำไม่ได้", "wish + would = อยากให้เกิดขึ้น/เปลี่ยนแปลง (มักบ่น)"]}, {"unit": 42, "section": "Passive", "title": "Passive 1 (is done / was done)", "pattern": "S + is/am/are/was/were + V3 (+ by...)", "sections": [{"label": "A", "explain": "Passive ใช้เมื่อเน้นผู้ถูกกระทำ (ไม่รู้/ไม่สำคัญว่าใครทำ)", "examples": ["This house was built in 1981.", "A lot of money was stolen in the robbery.", "Is this room cleaned every day?", "This house was built by my grandfather. (ระบุผู้กระทำด้วย by)"]}, {"label": "B", "explain": "Passive ผันตาม tense: Present Simple (is/are + V3), Past Simple (was/were + V3)", "examples": ["This room is cleaned every day.", "Many accidents are caused by careless driving.", "We were woken up by a loud noise.", "How much money was stolen in the robbery?"]}], "notes": ["past participle (V3) มักเติม -ed แต่หลายคำเป็น irregular (built, done, stolen)"], "mistake": {"wrong": "This house built in 1981.", "right": "This house was built in 1981.", "note": "ประโยค Passive ต้องมี verb to be (was) เสมอ ก่อนกริยาช่องที่ 3"}, "tip": "ถามตัวเองว่าประธานเป็น 'ผู้กระทำ' หรือ 'ผู้ถูกกระทำ' — ถ้าถูกกระทำ ต้องใช้ Passive (be + V3)", "summary": ["Passive: S + is/was + V3", "ใช้เมื่อเน้นผู้ถูกกระทำ หรือไม่รู้ว่าใครทำ", "by + ผู้กระทำ (ถ้าต้องการระบุ)"]}, {"unit": 43, "section": "Passive", "title": "Passive 2 (be done / been done / being done)", "pattern": "Passive ทุก tense: has been / had been / is being / was being / will be / should have been", "sections": [{"label": "A", "explain": "Present Perfect และ Past Perfect Passive", "examples": ["The room looks nice. It has been cleaned.", "The trip has been cancelled.", "Have you ever been bitten by a dog?", "The car hadn't been used very much."]}, {"label": "B", "explain": "Present/Past Continuous Passive", "examples": ["The room is being cleaned at the moment.", "I think we are being followed.", "A new bridge is being built across the river.", "The room was being cleaned when I arrived."]}, {"label": "C", "explain": "Infinitive และ Perfect Infinitive Passive", "examples": ["This room will be cleaned later.", "Something must be done before it's too late.", "The room should have been cleaned.", "It might have been sent to the wrong address."]}], "notes": ["โครงสร้าง Passive ทุกแบบ: verb to be (ผันตาม tense) + V3 เสมอ ไม่ว่าจะซับซ้อนแค่ไหน"], "mistake": {"wrong": "The room is cleaning at the moment.", "right": "The room is being cleaned at the moment.", "note": "Present Continuous Passive ต้องใช้ is/are + being + V3 ไม่ใช่ is + V-ing (ซึ่งเป็น active)"}, "tip": "แยก tense ให้ออกก่อน แล้วผัน verb to be ตาม tense นั้น จากนั้นเติม V3 ต่อท้ายเสมอ", "summary": ["Present/Past Perfect Passive: has/had been + V3", "Present/Past Continuous Passive: is/was being + V3", "Infinitive Passive: (to) be + V3, Perfect Infinitive: (to) have been + V3"]}, {"unit": 44, "section": "Passive", "title": "Passive 3 (I was offered... / I don't like being...)", "pattern": "S(คน) + is/was + V3 + object (สำหรับกริยาที่มี 2 กรรม)", "sections": [{"label": "A", "explain": "กริยาที่มี 2 กรรม (give, offer, ask, pay, show, tell) สามารถทำ Passive โดยขึ้นต้นด้วยคนได้", "examples": ["I was given this watch. (or 'This watch was given to me.')", "I've been offered the job, but I don't think I want it.", "You will be given plenty of time to decide.", "I was shown a copy of the document."]}, {"label": "B", "explain": "V-ing ในรูป Passive คือ being + V3, และ 'I was born...' ใช้ Past Simple เสมอ", "examples": ["I don't like being told what to do.", "I remember being taken to the zoo when I was a child.", "I was born in Chicago. (not 'I am born')", "How many babies are born every day? (ปัจจุบัน = ความจริงทั่วไป)"]}], "notes": ["get ใช้แทน be ในรูป Passive แบบไม่เป็นทางการได้ (เฉพาะเหตุการณ์ที่ 'เกิดขึ้น'): 'Nobody got hurt.' แต่ใช้กับสภาพถาวรไม่ได้ ('Jessica is liked by everybody' ไม่ใช่ 'gets liked')"], "mistake": {"wrong": "I am born in Bangkok.", "right": "I was born in Bangkok.", "note": "'was/were born' ใช้ Past Simple เสมอ (แม้จะพูดถึงตัวเองในปัจจุบัน) ไม่ใช่ 'am/is born'"}, "tip": "กริยา 2 กรรม (give/offer/tell/show/pay/ask) เปลี่ยนเป็น Passive ได้ 2 แบบ แต่แบบขึ้นต้นด้วยคนพบบ่อยกว่า", "summary": ["กริยา 2 กรรม ทำ Passive ขึ้นต้นด้วยคนได้: I was given/offered/shown/told/paid...", "Passive ของ V-ing คือ being + V3", "'was/were born' ใช้ Past Simple เสมอ"]}, {"unit": 45, "section": "Passive", "title": "it is said that... / he is said to... / he is supposed to...", "pattern": "It is + V3 + that...  =  S + is + V3 + to + V1", "sections": [{"label": "A", "explain": "ใช้พูดถึงสิ่งที่คนทั่วไปเชื่อ/พูดกัน โดยไม่รู้แน่ชัดว่าจริงหรือไม่ (say, believe, think, know, report, expect)", "examples": ["It is said that he is 108 years old. = He is said to be 108 years old.", "It is believed that the boy is wearing a white sweater. = The boy is believed to be wearing...", "It is expected that the strike will end soon. = The strike is expected to end soon.", "It is reported that two people were injured. = Two people are reported to have been injured."]}, {"label": "B", "explain": "supposed to ใช้ความหมายคล้ายกัน (คนพูดกันว่า) และยังใช้บอกสิ่งที่ตั้งใจ/ควรทำ (มักต่างจากความเป็นจริง)", "examples": ["It's supposed to be good. (คนพูดกันว่าดี)", "You're supposed to be on holiday. (ตกลง/วางแผนไว้ว่าจะพักร้อน)", "You're not supposed to park here. (ไม่ได้รับอนุญาต)"]}], "notes": ["โครงสร้างที่พูดถึงอดีต ใช้ 'to have been + V3': 'He is alleged to have stolen a car.'"], "mistake": {"wrong": "He is said that he is 108 years old.", "right": "He is said to be 108 years old. / It is said that he is 108 years old.", "note": "โครงสร้าง 'S is said to + V1' ห้ามใส่ 'that' ตามหลัง (สับสนกับโครงสร้าง 'It is said that...')"}, "tip": "สองโครงสร้างนี้สลับกันได้เสมอ: 'It is said that + ประธาน + กริยา' = 'ประธาน + is said to + กริยา'", "summary": ["It is said that... = S is said to...", "ใช้กับกริยา believe/think/know/report/expect ได้เช่นกัน", "supposed to ใช้บอกสิ่งที่คนพูดกัน หรือสิ่งที่ตั้งใจ/ควรทำ"]}, {"unit": 46, "section": "Passive", "title": "have something done", "pattern": "have/get + object + V3 (จ้าง/ให้คนอื่นทำแทน)", "sections": [{"label": "A", "explain": "have something done = จัดการให้คนอื่นทำสิ่งนั้นให้ (ไม่ได้ทำเอง)", "examples": ["Lisa had the roof repaired. (= จ้างคนอื่นซ่อม ไม่ได้ซ่อมเอง)", "Did you have those curtains made? (= จ้างคนทำ)", "How often do you have your car serviced?", "Our neighbour is having a garage built."]}, {"label": "B", "explain": "get something done ใช้แทน have something done ได้ (ไม่เป็นทางการกว่า)", "examples": ["When are you going to get the roof repaired?", "I think you should get your hair cut really short."]}], "notes": ["have something done ยังใช้ความหมายว่า 'มีบางสิ่งเกิดขึ้นกับตัวเอง/ของของตัวเอง' (ไม่ได้ตั้งใจ/ไม่ได้จัดการ): 'Paul had his bags stolen.' (= กระเป๋าถูกขโมย ไม่ได้จ้างใครขโมย!)"], "mistake": {"wrong": "Lisa repaired the roof by a builder.", "right": "Lisa had the roof repaired (by a builder).", "note": "เมื่อจ้างคนอื่นทำให้ ต้องใช้โครงสร้าง 'have + object + V3' ไม่ใช่ active voice ธรรมดา"}, "tip": "ลำดับคำสำคัญ: have/get + สิ่งของ + กริยาช่อง 3 (ไม่ใช่ 'have + V3 + สิ่งของ')", "summary": ["have something done = จ้าง/ให้คนอื่นทำแทน", "get something done ใช้แทนได้ (ไม่เป็นทางการ)", "ยังใช้บอกว่ามีเรื่องไม่ดีเกิดขึ้นกับตัวเอง (เช่น ถูกขโมย)"]}, {"unit": 47, "section": "Reported Speech", "title": "Reported Speech 1 (he said that...)", "pattern": "S + said (that) + S + V2/would/could... (เปลี่ยนจากปัจจุบันเป็นอดีต)", "sections": [{"label": "A", "explain": "เมื่อเล่าคำพูดของคนอื่น (reported speech) กริยาหลักมักเป็นอดีต และกริยาในส่วนที่เหลือก็มักเปลี่ยนเป็นอดีตด้วย", "examples": ["Paul said, 'I'm feeling ill.' → Paul said that he was feeling ill.", "I told Lisa that I didn't have any money.", "Paul said he was feeling ill. (สามารถตัด 'that' ออกได้)"]}, {"label": "B", "explain": "การเปลี่ยนรูปกริยาทั่วไป: am/is→was, are→were, do/does→did, have/has→had, will→would, can→could", "examples": ["'I've lost my phone.' → She said that she had lost her phone.", "'I can't come to the party.' → She said that she couldn't come to the party.", "'I'll phone you when I get back.' → She said she would phone me when she got back."]}], "notes": ["Past Simple ในคำพูดเดิม อาจคงเดิมหรือเปลี่ยนเป็น Past Perfect ก็ได้: 'I woke up feeling ill.' → 'he woke up feeling ill' หรือ 'he had woken up feeling ill'"], "mistake": {"wrong": "Paul said that he is feeling ill.", "right": "Paul said that he was feeling ill.", "note": "ใน reported speech กริยาปัจจุบันในคำพูดเดิมมักเปลี่ยนเป็นอดีต (is→was)"}, "tip": "จำการเปลี่ยนรูปหลัก: am/is/are→was/were, do/does→did, have/has→had, will→would, can→could", "summary": ["Reported speech: กริยาเปลี่ยนจากปัจจุบันเป็นอดีต", "สามารถตัด 'that' ออกได้", "Past Simple อาจคงเดิมหรือเปลี่ยนเป็น Past Perfect"]}, {"unit": 48, "section": "Reported Speech", "title": "Reported Speech 2 (say and tell)", "pattern": "tell + object + that... / say + (to object) + that...", "sections": [{"label": "A", "explain": "ไม่จำเป็นต้องเปลี่ยนกริยาเป็นอดีตเสมอไป ถ้าสถานการณ์ยังเป็นจริงอยู่ (แต่เปลี่ยนก็ได้)", "examples": ["Paul said, 'My new job is boring.' → Paul said that his new job is boring. (or 'was boring')", "Helen told me that she wants to go to Canada next year. (or 'wanted')", "Paul said (that) he had to go. (not 'has to go' — เพราะสถานการณ์เปลี่ยนไปแล้ว)"]}, {"label": "B", "explain": "say กับ tell ใช้ต่างกัน — tell ต้องมีกรรม (บอกใคร) ส่วน say ไม่มีกรรมตรง (หรือใช้ say...to)", "examples": ["Rachel told me that you were in hospital. (not 'Rachel said me')", "Rachel said that you were in hospital. (not 'Rachel told that')", "Anna said goodbye to me and left."]}, {"label": "C", "explain": "tell somebody to... และ ask somebody to... ใช้กับคำสั่ง/คำขอร้อง", "examples": ["'Drink plenty of water,' the doctor said. → The doctor told me to drink plenty of water.", "'Don't work too hard.' → I told Joe not to work too hard.", "'Can you help me?' → Jackie asked me to help her."]}], "notes": [], "mistake": {"wrong": "Rachel said me that you were in hospital.", "right": "Rachel told me that you were in hospital.", "note": "'tell' ต้องมีกรรม (บอกใคร) ตามหลังทันที ส่วน 'say' ใช้ 'say...to somebody' หรือไม่มีกรรมเลย"}, "tip": "tell + คน + that/to..., say + (to คน) + that... — จำคู่กันไว้ ห้ามสลับ", "summary": ["ไม่จำเป็นต้องเปลี่ยนอดีตเสมอถ้าสถานการณ์ยังจริงอยู่", "tell ต้องมีกรรม, say ไม่มีกรรมตรง", "tell/ask somebody to + V1 ใช้กับคำสั่ง/คำขอร้อง"]}, {"unit": 49, "section": "Questions and Auxiliary Verbs", "title": "Questions 1", "pattern": "verb + subject (คำถามทั่วไป) / do/does/did + subject + V1", "sections": [{"label": "A", "explain": "ในประโยคคำถาม ประธานมักอยู่หลังกริยาตัวแรก", "examples": ["Will Tom be here tomorrow?", "Have you been working hard?", "When was the house built?", "Is Katherine working today? (not 'Is working Katherine')"]}, {"label": "B", "explain": "Present/Past Simple ใช้ do/does/did ในคำถาม ยกเว้นเมื่อ who/what เป็นประธานของประโยคเอง", "examples": ["Do you live near here?", "Did you sell your car?", "Who phoned Emma? (who เป็นประธาน ไม่ใช้ did)", "What happened to you last night? (not 'did happen')"]}], "notes": ["คำถามที่ขึ้นต้นด้วย who/what/which/where มักมี preposition ไปอยู่ท้ายประโยค: 'Who do you want to speak to?'", "negative question (isn't it?/didn't you?) ใช้แสดงความประหลาดใจ หรือคาดว่าคนฟังจะเห็นด้วย"], "mistake": {"wrong": "What did happen to you?", "right": "What happened to you?", "note": "เมื่อ what/who เป็นประธานของประโยคเอง ไม่ต้องใช้ do/does/did"}, "tip": "เช็คก่อนว่า who/what เป็น 'ประธาน' หรือ 'กรรม' ของประโยค — ถ้าเป็นประธาน ไม่ต้องใช้ do/does/did", "summary": ["คำถามทั่วไป: กริยาช่วย + ประธาน", "Present/Past Simple ใช้ do/does/did", "ถ้า who/what เป็นประธานเอง ไม่ใช้ do/does/did"]}, {"unit": 50, "section": "Questions and Auxiliary Verbs", "title": "Questions 2 (embedded and reported questions)", "pattern": "Do you know + (statement word order) / S + asked + (statement word order)", "sections": [{"label": "A", "explain": "เมื่อคำถามอยู่ในประโยคที่ยาวขึ้น (Do you know...? / I don't know... / Can you tell me...?) ลำดับคำเปลี่ยนเป็นแบบประโยคบอกเล่า (ไม่ใช่คำถาม)", "examples": ["Where has Tom gone? → Do you know where Tom has gone? (not 'has Tom gone')", "What time is it? → Do you know what time it is?", "Who are those people? → I don't know who those people are."]}, {"label": "B", "explain": "ระวังคำถามที่ใช้ do/does/did — เมื่ออยู่ใน embedded question จะไม่ใช้ do/does/did อีกต่อไป", "examples": ["What time does the film start? → Do you know what time the film starts? (not 'does the film start')", "Why did she leave early? → I wonder why she left early.", "Did anybody see you? → I don't know if anybody saw me."]}], "notes": ["ใช้ if/whether เมื่อไม่มีคำคำถาม (what/why ฯลฯ): 'I don't know if anybody saw me.'", "หลักการเดียวกันนี้ใช้กับ reported questions: 'Where are you going?' → 'The officer asked where we were going.'"], "mistake": {"wrong": "Do you know what time does the film start?", "right": "Do you know what time the film starts?", "note": "embedded question ใช้ลำดับคำแบบประโยคบอกเล่า ไม่ใช้ do/does/did ซ้ำ"}, "tip": "ทุกครั้งที่คำถามถูก 'ฝัง' อยู่ในประโยคอื่น ให้เปลี่ยนลำดับคำเป็นแบบประโยคบอกเล่าเสมอ และตัด do/does/did ออก", "summary": ["embedded/reported question ใช้ลำดับคำแบบบอกเล่า", "ตัด do/does/did ออกเสมอ", "ใช้ if/whether เมื่อไม่มีคำคำถาม"]}, {"unit": 51, "section": "Questions and Auxiliary Verbs", "title": "Auxiliary verbs / I think so", "pattern": "auxiliary verb (have/do/can/will) แทนกริยาที่ไม่อยากพูดซ้ำ", "sections": [{"label": "A", "explain": "ใช้กริยาช่วยแทนการพูดซ้ำประโยคเดิม", "examples": ["'Have you locked the door?' 'Yes, I have.'", "Gary wasn't working, but Laura was.", "'Do you like onions?' 'Yes, I do.'", "'You didn't lock the door.' 'Yes, I did.'"]}, {"label": "B", "explain": "ใช้ so/neither + กริยาช่วย (สลับตำแหน่งกริยากับประธาน) เพื่อบอกว่า 'เหมือนกัน'", "examples": ["'I'm tired.' 'So am I.'", "'I never read newspapers.' 'Neither do I.'", "I passed the exam and so did Paul. (not 'so Paul did')"]}], "notes": ["'I think so / I hope so / I suppose so' ใช้แทนการพูดซ้ำประโยคยาว ปฏิเสธมักเป็น 'I don't think so' แต่ 'I hope not' (ไม่ใช่ 'I don't hope so')"], "mistake": {"wrong": "I hope not so.", "right": "I hope not.", "note": "ปฏิเสธของ 'I hope so' คือ 'I hope not' ไม่ใช่ 'I don't hope so' หรือ 'I hope not so'"}, "tip": "so/neither + กริยาช่วย + ประธาน (สลับตำแหน่ง) ใช้บอกว่า 'เหมือนกัน' ทั้งทางบวกและทางลบ", "summary": ["ใช้กริยาช่วยแทนการพูดซ้ำประโยคเดิม", "so/neither + กริยาช่วย + ประธาน = เหมือนกัน", "I think so/I hope so มีรูปปฏิเสธเฉพาะตัว (I hope not)"]}, {"unit": 52, "section": "Questions and Auxiliary Verbs", "title": "Question tags", "pattern": "positive sentence + negative tag / negative sentence + positive tag", "sections": [{"label": "A", "explain": "ประโยคบอกเล่า (positive) ใช้ tag ปฏิเสธ ส่วนประโยคปฏิเสธ (negative) ใช้ tag บวก", "examples": ["Kate will be here soon, won't she?", "Joe should pass the exam, shouldn't he?", "Kate won't be late, will she?", "You haven't eaten yet, have you?"]}, {"label": "B", "explain": "เสียงขึ้น/ลงท้ายประโยคเปลี่ยนความหมาย — เสียงลง = ไม่ได้ถามจริง (คาดว่าคนฟังเห็นด้วย), เสียงขึ้น = ถามจริง", "examples": ["'It's a nice day, isn't it?' 'Yes, beautiful.' (เสียงลง)", "'You haven't seen Kate today, have you?' 'No, I haven't.' (เสียงขึ้น = ถามจริง)", "'You couldn't do me a favour, could you?' (ขอความช่วยเหลือ)"]}], "notes": ["Let's... ใช้ tag 'shall we?'", "Don't... ใช้ tag 'will you?'", "I'm... ใช้ tag พิเศษ 'aren't I?'"], "mistake": {"wrong": "I'm right, am I not?", "right": "I'm right, aren't I?", "note": "หลัง 'I'm...' tag พิเศษคือ 'aren't I?' ไม่ใช่รูปมาตรฐาน"}, "tip": "จำ 3 กรณีพิเศษ: Let's... → shall we?, Don't... → will you?, I'm... → aren't I?", "summary": ["positive sentence + negative tag, negative sentence + positive tag", "เสียงลง = ไม่ได้ถามจริง, เสียงขึ้น = ถามจริง", "กรณีพิเศษ: Let's→shall we?, Don't→will you?, I'm→aren't I?"]}, {"unit": 53, "section": "-ing and to...", "title": "กริยา + -ing (1): enjoy, mind, suggest, stop", "pattern": "verb + V-ing", "sections": [{"label": "A", "explain": "กริยาบางกลุ่มต้องตามด้วยกริยาเติม -ing เท่านั้น เพราะโครงสร้างนี้มองการกระทำนั้นเป็นเหมือนหัวข้อหรือวัตถุที่กริยาแรกกระทำต่อ", "examples": ["I **enjoy** cooking for my family on weekends.", "Would you **mind** turning down the music a little?", "The doctor **recommended** cutting down on sugar.", "He finally **admitted** stealing the money.", "She always **avoids** talking about her past."]}, {"label": "B", "explain": "กริยาวลี (phrasal verb) เช่น give up, put off, go on, carry on, keep (on) ก็ตามด้วย -ing เช่นกัน โดยเฉพาะเมื่อพูดถึงการเริ่ม/เลิก/ทำต่อการกระทำหนึ่ง", "examples": ["I've **given up** eating meat completely.", "Let's not **put off** making a decision any longer.", "Despite the rain, they **carried on** playing.", "He **kept on** interrupting me during the meeting."]}, {"label": "C", "explain": "บางครั้งกริยากลุ่มนี้ตามด้วยกรรม (คน) แล้วตามด้วย -ing เพื่อบอกว่าจำได้/นึกภาพออกว่าคนนั้นกำลังทำอะไร", "examples": ["I can't imagine **him wearing** a suit.", "Do you remember **your sister singing** at the wedding?", "I don't recall **anyone mentioning** that."]}], "notes": ["stop doing ≠ stop to do: stop + -ing แปลว่าเลิกทำสิ่งนั้น (He stopped smoking) ส่วน stop + to + verb แปลว่าหยุดเพื่อไปทำอีกอย่าง (He stopped to smoke = หยุดเพื่อไปสูบบุหรี่)", "having + V3 ใช้แทนประโยคที่ทำเสร็จก่อนแล้วจึงทำอีกอย่าง เช่น 'Having finished the report, she went home.'"], "mistake": {"wrong": "I enjoy to travel alone.", "right": "I enjoy travelling alone.", "note": "enjoy ต้องตามด้วย -ing เท่านั้น ห้ามใช้ to + infinitive"}, "tip": "จำกลุ่มคำนี้เป็น 'กริยาที่มองการกระทำเป็นเหมือนวัตถุ/หัวข้อสนทนา' (suggest, discuss, admit, enjoy) จะช่วยให้จำได้ว่าทำไมต้องตามด้วย -ing ซึ่งทำหน้าที่คล้ายคำนาม", "summary": ["enjoy/mind/suggest/finish/consider/recommend/admit/deny/avoid/risk/imagine/fancy + -ing เท่านั้น", "give up/put off/go on/carry on/keep(on) + -ing", "having + V3 ใช้แทนประโยคที่ทำเสร็จก่อนแล้ว"]}, {"unit": 54, "section": "-ing and to...", "title": "กริยา + to...: offer, decide, promise", "pattern": "verb + to + V1", "sections": [{"label": "A", "explain": "กริยากลุ่มนี้ตามด้วย to + verb1 เสมอ มักสื่อถึงความตั้งใจ แผนการ หรือสิ่งที่ยังไม่เกิดขึ้น", "examples": ["She **offered** to help me carry the boxes.", "We **agreed** to meet at seven o'clock.", "He **refused** to answer the question.", "I can't **afford** to buy a new car this year.", "Children **learn** to walk before they learn to run."]}, {"label": "B", "explain": "กริยาบางตัว (ask, know, decide, remember, forget, learn, explain, understand, wonder) ตามด้วยคำคำถาม (how/what/where/whether) + to + verb1 เพื่อถามหรือบอกวิธีการ", "examples": ["I don't **know how to fix** this printer.", "Can you **explain how to get** to the station?", "We haven't **decided where to go** for the holiday.", "She **wondered whether to call** him or not."]}], "notes": ["dare สามารถตามด้วย to หรือไม่มี to ก็ได้: 'I didn't dare to ask.' หรือ 'I didn't dare ask.'", "seem/appear/pretend/claim + to: 'She seems to be tired.' / 'He pretended not to notice.'", "fail to do = ทำไม่สำเร็จ, deserve to do = สมควรได้รับ"], "mistake": {"wrong": "I decided going to Japan.", "right": "I decided to go to Japan.", "note": "decide ต้องตามด้วย to + verb1 ไม่ใช้ -ing"}, "tip": "กริยาในกลุ่มนี้ส่วนใหญ่สื่อถึงความตั้งใจหรือแผนการในอนาคต (offer, plan, decide, promise) ต่างจากกลุ่ม -ing ใน Unit 53 ที่มักพูดถึงสิ่งที่ทำอยู่หรือทำสำเร็จแล้ว", "summary": ["offer/agree/refuse/decide/plan/arrange/hope/forget/manage/fail/promise/threaten/deserve/afford/learn/tend + to", "question word + to (how to, what to, where to)", "dare + (to) เลือกได้ทั้งสองแบบ"]}, {"unit": 55, "section": "-ing and to...", "title": "กริยา + กรรม + to...: want, tell, make", "pattern": "verb + object + to + V1  /  make/let + object + V1", "sections": [{"label": "A", "explain": "กริยากลุ่มนี้ตามด้วย (กรรม) + to + verb1 เพื่อบอกว่าอยากให้ใครทำอะไร: want, expect, ask, help, would like, would prefer", "examples": ["I want **you to be** happy.", "She asked **me to close** the door.", "Would you like **me to call** a taxi?", "We'd prefer **her to stay** with us."]}, {"label": "B", "explain": "กริยากลุ่มนี้ก็ตามด้วยกรรม + to + verb1 เช่นกัน: tell, advise, remind, warn, invite, encourage, persuade, get, force, teach, allow, enable", "examples": ["My mother told **me to clean** my room.", "The doctor advised **him to rest** for a week.", "Please remind **me to buy** milk.", "They persuaded **her to join** the team."]}, {"label": "C", "explain": "make และ let ตามด้วยกรรม + verb1 เปล่าๆ (ไม่มี to) แต่เมื่อเปลี่ยนเป็น passive จะมี to กลับมา (be made to)", "examples": ["Her parents made **her practise** the piano every day.", "Let **me carry** that bag for you.", "He was made **to wait** outside for an hour. (passive)"]}], "notes": ["help + object + (to) + verb1: ใช้ได้ทั้งสองแบบ เช่น 'He helped me (to) fix the car.'"], "mistake": {"wrong": "She made him to apologise.", "right": "She made him apologise.", "note": "make + object ตามด้วย V1 เปล่าๆ ไม่มี to (ยกเว้นในรูป passive)"}, "tip": "สังเกตว่า make/let ไม่ใช้ to แต่พอเปลี่ยนเป็น passive (be made to) จะมี to กลับมา นี่คือข้อยกเว้นสำคัญที่สุดของหมวดนี้", "summary": ["want/expect/ask/help/would like/would prefer + (object) + to", "tell/advise/remind/warn/invite/encourage/persuade/get/force/teach/allow/enable + object + to", "make/let + object + V1 (ไม่มี to) แต่ be made to (passive มี to)"]}, {"unit": 56, "section": "-ing and to...", "title": "กริยา + -ing หรือ to (1): remember, regret, go on", "pattern": "remember/regret/go on + -ing (ย้อนมองอดีต) หรือ + to (มุ่งไปข้างหน้า)", "sections": [{"label": "A", "explain": "remember doing = จำได้ว่าเคยทำ (ทำไปแล้ว แล้วจำได้ทีหลัง) ส่วน remember to do = จำได้ที่ต้องทำ (จำได้ก่อนจะลงมือทำ)", "examples": ["I remember **locking** the door before we left. (ล็อกไปแล้ว และจำได้ว่าล็อก)", "Please remember **to lock** the door when you leave. (อย่าลืมล็อกก่อนออกไป)", "He couldn't remember **meeting** her before."]}, {"label": "B", "explain": "regret doing = เสียใจที่ทำไปแล้ว ส่วน regret to say/tell/inform เป็นสำนวนทางการที่ใช้ก่อนบอกข่าวไม่ดี / go on doing = ทำสิ่งเดิมต่อ ส่วน go on to do = เปลี่ยนไปพูด/ทำสิ่งใหม่", "examples": ["I regret **telling** him the secret. (เสียใจที่บอกไปแล้ว)", "We regret **to inform** you that your application was unsuccessful. (สำนวนทางการ)", "She went on **talking** for another hour. (พูดเรื่องเดิมต่อ)", "After the break, he went on **to describe** the new plan. (เปลี่ยนไปพูดเรื่องใหม่)"]}], "notes": ["begin/start/continue/intend/bother ใช้ -ing หรือ to ได้โดยความหมายไม่ต่างกัน: 'It began raining.' = 'It began to rain.'", "ปกติไม่ใช้ -ing ซ้อนกันสองตัวติดกัน: 'It's starting to rain.' (ไม่ใช้ 'It's starting raining')"], "mistake": {"wrong": "Don't forget locking the door before you go.", "right": "Don't forget to lock the door before you go.", "note": "forget to do = ลืมสิ่งที่ต้องทำ(ยังไม่ได้ทำ) ส่วน forget doing มักใช้ปฏิเสธเพื่อบอกว่าจำเรื่องนั้นไม่ลืม เช่น 'I'll never forget seeing that sunset.'"}, "tip": "เทคนิคจำ: remember/regret/go on + -ing = ย้อนมองสิ่งที่ทำไปแล้ว ส่วน + to = ก้าวไปข้างหน้าสู่สิ่งที่ยังไม่เกิดหรือสิ่งใหม่", "summary": ["remember/regret/go on + -ing = เรื่องที่ทำไปแล้ว, + to = เรื่องที่ยังไม่ทำ/เรื่องใหม่", "begin/start/continue/intend/bother + -ing หรือ to ความหมายเหมือนกัน", "ไม่ใช้ -ing ซ้อนกันสองตัวติดกัน"]}, {"unit": 57, "section": "-ing and to...", "title": "กริยา + -ing หรือ to (2): try, need, help", "pattern": "try to (พยายาม) / try -ing (ลองทำดู)  ·  need to (ตัวเองทำ) / need -ing (ถูกทำ)", "sections": [{"label": "A", "explain": "try to do = พยายามทำ (อาจไม่สำเร็จ) ส่วน try doing = ลองทำเพื่อดูผลลัพธ์ (ทำเป็นการทดลอง)", "examples": ["I tried **to open** the jar, but it was too tight.", "Try **adding** a little salt — it might taste better.", "We tried **calling** her twice, but no one answered."]}, {"label": "B", "explain": "need to do = ฉันต้องลงมือทำเอง ส่วน need -ing มีความหมายเชิง passive คือของสิ่งนั้นต้องถูกทำ; help to do / help do ใช้ได้ทั้งสองแบบ", "examples": ["I need **to charge** my phone.", "My phone needs **charging**. (= needs to be charged)", "This shirt needs **ironing** before the meeting.", "Everyone helped (to) **clean** the venue after the party."]}], "notes": ["can't help doing = อดไม่ได้ที่จะทำ เช่น 'I can't help laughing when he tells that joke.'"], "mistake": {"wrong": "This bike needs to fix.", "right": "This bike needs fixing.", "note": "ของที่ยังไม่ได้ลงมือทำเองต้องใช้ needs + -ing หรือ needs to be + V3 (needs to be fixed)"}, "tip": "ถ้าประธานของประโยคเป็น 'สิ่งของ' ที่ถูกกระทำ ให้ใช้ need + -ing แทนรูป passive แบบเต็ม", "summary": ["try to = พยายามทำ, try -ing = ลองทำดู", "need to do (ตัวเองทำ) ต่างจาก need doing (ของถูกทำ, ความหมาย passive)", "can't help doing = อดไม่ได้ที่จะทำ"]}, {"unit": 58, "section": "-ing and to...", "title": "กริยา + -ing หรือ to (3): like, would like", "pattern": "like/love/hate + -ing หรือ to  ·  would like/would prefer + to", "sections": [{"label": "A", "explain": "เมื่อพูดถึงการกระทำที่ทำซ้ำๆ เป็นประจำ like/love/hate ตามด้วย -ing หรือ to ได้ทั้งคู่ โดย -ing มักเน้นสถานการณ์ที่เป็นอยู่ในปัจจุบัน ส่วน like doing (ทำแล้วสนุก) กับ like to do (เลือกทำเพราะเหตุผลบางอย่าง ไม่จำเป็นต้องสนุก) มีความหมายต่างกันเล็กน้อย", "examples": ["Do you like **getting up** early? = Do you like **to get up** early?", "Paul lives in Rome now. He loves **living** there. (สถานการณ์ปัจจุบัน)", "I like **doing** the cooking. (=ทำแล้วสนุก)", "I like **to do** the cooking every Sunday. (=เลือกทำ อาจไม่ได้สนุก)"]}, {"label": "B", "explain": "would like/would love/would hate/would prefer มักตามด้วย to เสมอ (ไม่ใช่ -ing) ส่วน would mind ตามด้วย -ing", "examples": ["I'd like **to go** away for the weekend.", "Would you prefer **to eat** now or later?", "Would you mind **closing** the window? (would mind ตามด้วย -ing)"]}, {"label": "C", "explain": "would like/love/hate/prefer to have done = เสียดายที่ไม่ได้ทำสิ่งนั้นในอดีต", "examples": ["I would like **to have seen** the final match, but I was working.", "We'd love **to have joined** you, but it was too far."]}], "notes": ["enjoy/mind ใช้ -ing เท่านั้น (ทบทวนจาก Unit 53) ไม่ใช้กับ to"], "mistake": {"wrong": "Would you mind to close the door?", "right": "Would you mind closing the door?", "note": "would mind ตามด้วย -ing เสมอ ไม่ใช่ to"}, "tip": "like doing = ทำแล้วสนุก, like to do = เลือกทำเพราะเหตุผลบางอย่าง(ไม่จำเป็นต้องสนุก) — ถ้าจำสองคำนี้แยกกันได้จะเข้าใจ would like ได้ง่ายขึ้น", "summary": ["like/love/hate + -ing หรือ to (การกระทำซ้ำๆ) โดย -ing เน้นสถานการณ์ที่เป็นอยู่", "would like/would love/would hate/would prefer + to เกือบทุกครั้ง, would mind + -ing", "would like to have done = เสียดายที่ไม่ได้ทำ"]}, {"unit": 59, "section": "-ing and to...", "title": "prefer และ would rather", "pattern": "prefer -ing to -ing / prefer to do rather than do  ·  would rather + V1", "sections": [{"label": "A", "explain": "เมื่อพูดถึงสิ่งที่ชอบโดยทั่วไป ใช้ prefer + -ing/to + to/rather than อีกทางเลือก ส่วน would prefer ใช้พูดถึงสถานการณ์เฉพาะหน้า", "examples": ["I prefer **living** in the countryside **to living** in the city.", "I prefer **to drive rather than travel** by train.", "'Would you prefer tea or coffee?' 'I'd prefer **coffee**.'", "I'd prefer **to stay** home tonight rather than go out."]}, {"label": "B", "explain": "would rather ตามด้วย verb1 เปล่าๆ (ไม่มี to) เพื่อบอกสิ่งที่อยากทำมากกว่าในสถานการณ์เฉพาะหน้า", "examples": ["'Shall we take a taxi?' 'I'd rather **walk**.' (not to walk)", "I'd rather **not go** out this evening.", "I'd rather **stay** home than go to the party."]}, {"label": "C", "explain": "เมื่ออยากให้ 'คนอื่น' ทำสิ่งใดสิ่งหนึ่ง ใช้ I'd rather you + กริยาช่องที่ 2 (past tense) แต่ความหมายเป็นปัจจุบัน/อนาคต ไม่ใช่อดีต", "examples": ["'Who's going to cook?' 'I'd rather **you cooked**.'", "I'd rather you **didn't tell** anyone about this.", "Would you rather I **called** you tomorrow?"]}], "notes": [], "mistake": {"wrong": "I'd rather to stay home.", "right": "I'd rather stay home.", "note": "would rather ตามด้วย V1 เปล่าๆ ไม่มี to"}, "tip": "'I'd rather you + past tense' ฟังดูเหมือนอดีต แต่จริงๆ พูดถึงปัจจุบัน/อนาคต เป็นการใช้ past tense แบบ unreal เพื่อบอกความต้องการ", "summary": ["prefer to.../prefer -ing to -ing = พูดถึงสิ่งที่ชอบโดยทั่วไป, would prefer + to = สถานการณ์เฉพาะ", "would rather + V1 (ไม่มี to), ปฏิเสธคือ would rather not", "I'd rather you + past tense = อยากให้อีกคนทำ (ความหมายปัจจุบัน)"]}, {"unit": 60, "section": "-ing and to...", "title": "บุพบท + -ing", "pattern": "preposition + V-ing  ·  to (บุพบท) + -ing", "sections": [{"label": "A", "explain": "ถ้ากริยาตามหลังคำบุพบท (in, at, with, of, for, about, instead of ฯลฯ) กริยานั้นต้องอยู่ในรูป -ing เสมอ", "examples": ["Are you interested **in learning** French?", "She's not good **at cooking**.", "Thanks for **helping** me move.", "Why don't you go out **instead of sitting** at home all day?", "I'm fed up **with waiting** for the bus."]}, {"label": "B", "explain": "คำว่า to ปกติเป็น infinitive marker (to + verb1) แต่ในบางสำนวน to ทำหน้าที่เป็นบุพบท (เหมือน in/at/about) สังเกตได้จากมีคำนามตามได้ (to the weekend, to lunch) — เมื่อ to เป็นบุพบทแบบนี้ ต้องตามด้วย -ing", "examples": ["I'm looking forward **to seeing** you again.", "I prefer walking **to travelling** by car.", "Are you looking forward **to going** on holiday?"]}, {"label": "C", "explain": "บุพบทที่ใช้บ่อยกับ -ing: before/after/by/without", "examples": ["Before **leaving** the house, check the stove.", "You can improve your health by **exercising** regularly.", "She left without **saying** goodbye.", "I have too many problems of my own without **having to worry** about yours."]}], "notes": [], "mistake": {"wrong": "I'm looking forward to see you.", "right": "I'm looking forward to seeing you.", "note": "to ในสำนวนนี้เป็น preposition ต้องตามด้วย -ing ไม่ใช่ infinitive"}, "tip": "ถ้าหลังคำว่า to สามารถเติมคำนามได้ (to the weekend, to lunch) แสดงว่า to นั้นเป็น preposition → ต้องตามด้วย -ing เมื่อตามด้วยกริยา", "summary": ["preposition ใดๆ ตามด้วยกริยาต้องเป็น -ing เสมอ", "look forward to / prefer...to = to เป็น preposition ตามด้วย -ing", "before/after/by/without + -ing"]}, {"unit": 61, "section": "-ing and to...", "title": "be/get used to", "pattern": "be/get used to + -ing/คำนาม (คุ้นเคยแล้ว)  ·  used to + V1 (เคยทำในอดีต)", "sections": [{"label": "A", "explain": "be used to / get used to + -ing (หรือคำนาม) หมายถึงคุ้นเคยกับสิ่งนั้นแล้ว ไม่รู้สึกแปลกหรือลำบากอีกต่อไป (to ในที่นี้เป็นบุพบท เหมือน Unit 60)", "examples": ["After a year abroad, she **is used to eating** spicy food.", "I **wasn't used to driving** on the left at first.", "We'll **get used to the noise** eventually.", "He **is used to getting up** early now; it doesn't bother him anymore."]}, {"label": "B", "explain": "อย่าสับสนกับ used to + verb1 (ไม่มี be/get นำหน้า) ซึ่งหมายถึงเคยทำเป็นประจำในอดีตแต่ตอนนี้ไม่ทำแล้ว ใช้ได้เฉพาะรูปอดีตเท่านั้น (ดู Unit 18)", "examples": ["I'm used to **living** alone now. (คุ้นเคยแล้ว - ปัจจุบัน)", "I used to **live** with my parents, but now I have my own flat. (อดีต ไม่ได้ทำแล้ว)", "She used to **smoke**, but she quit years ago."]}], "notes": ["be used to ต้องตามด้วย -ing หรือคำนาม ไม่ใช่ V1 เปล่า ('be used to do' ผิด)"], "mistake": {"wrong": "She is used to drive on the left.", "right": "She is used to driving on the left.", "note": "to ในสำนวน be/get used to เป็นบุพบท ต้องตามด้วย -ing เช่นเดียวกับ Unit 60"}, "tip": "อย่าสับสน used to do (อดีต, Unit 18) กับ be/get used to doing (คุ้นเคย, ใช้ได้ทุก tense) — คำว่า be/get ที่นำหน้าเป็นตัวบ่งชี้สำคัญว่าเป็นสำนวนคุ้นเคย ไม่ใช่อดีตกาล", "summary": ["be/get used to + -ing/คำนาม = คุ้นเคยกับสิ่งนั้นแล้ว", "used to + V1 = เคยทำในอดีต (ปัจจุบันไม่ทำแล้ว) ใช้ได้เฉพาะรูปอดีต", "to ใน be/get used to เป็นบุพบท ต้องตามด้วย -ing เสมอ"]}, {"unit": 62, "section": "-ing and to...", "title": "กริยา + บุพบท + -ing", "pattern": "verb + preposition + -ing  ·  verb + object + preposition + -ing", "sections": [{"label": "A", "explain": "กริยาบางตัวตามด้วยบุพบทตายตัวก่อนจะตามด้วย -ing: succeed in, insist on, look forward to, feel like, dream of, approve of, decide against, think of/about", "examples": ["She succeeded **in passing** the exam on her second try.", "He insisted **on paying** for dinner.", "I don't feel **like cooking** tonight.", "They're thinking **of moving** to another city."]}, {"label": "B", "explain": "กริยาบางตัวมีโครงสร้าง verb + object + preposition + -ing: accuse...of, congratulate...on, prevent/stop...from, suspect...of, thank...for", "examples": ["They accused him **of lying** to the committee.", "We congratulated her **on passing** the exam.", "The heavy traffic prevented us **from arriving** on time.", "I thanked them **for helping** me move."]}], "notes": ["stop somebody doing / stop somebody from doing ใช้ได้ทั้งสองแบบ", "apologise to somebody for -ing (ต้องมี to นำหน้ากรรม ไม่ใช่ apologise somebody)"], "mistake": {"wrong": "He apologised me for being late.", "right": "He apologised to me for being late.", "note": "apologise ต้องมี to นำหน้ากรรม (คน) เสมอ"}, "tip": "กริยา + บุพบทเหล่านี้เป็นคู่คำตายตัว การท่องเป็นวลีคู่ (insist on, succeed in, accuse...of) จะช่วยจำได้มากกว่าจำแยกส่วน", "summary": ["verb + preposition + -ing (succeed in, insist on, feel like, look forward to ฯลฯ)", "verb + object + preposition + -ing (accuse...of, congratulate...on, prevent...from, thank...for)", "apologise to somebody for -ing"]}, {"unit": 63, "section": "-ing and to...", "title": "there's no point in -ing, it's worth -ing", "pattern": "there's no point in / it's no use / it's worth + -ing", "sections": [{"label": "A", "explain": "สำนวน there's no point in, it's no use, it's no good ตามด้วย -ing เพื่อบอกว่าทำสิ่งนั้นไปก็ไม่มีประโยชน์ / เทียบกับ 'the point of' ที่ใช้ในประโยคคำถาม", "examples": ["There's no point **in arguing** about it now.", "It's no use **complaining** — nobody will listen.", "It's no good **asking** him; he never remembers anything.", "What's the point **of buying** a car if you never drive it?"]}, {"label": "B", "explain": "it's (not) worth + -ing บอกว่าสิ่งนั้นคุ้มค่า (หรือไม่คุ้มค่า) ที่จะทำ", "examples": ["This museum is small, but it's worth **visiting**.", "It's not worth **repairing** this old radio; buy a new one.", "The book wasn't very good — it wasn't worth **finishing**."]}, {"label": "C", "explain": "สำนวนอื่นที่ตามด้วย -ing: have trouble/difficulty/a problem -ing, spend/waste time -ing, be busy -ing, go -ing (สำหรับกิจกรรมกีฬา/นันทนาการ)", "examples": ["I had no trouble **finding** the hotel.", "She had difficulty **understanding** the instructions.", "He spent hours **repairing** the bike.", "I'm busy **preparing** for the exam this week.", "We go **swimming** every Sunday morning."]}], "notes": [], "mistake": {"wrong": "I had no trouble to find the hotel.", "right": "I had no trouble finding the hotel.", "note": "have trouble/difficulty + -ing ไม่ใช่ + to"}, "tip": "กลุ่มสำนวนนี้ทั้งหมด (no point in, worth, trouble, spend time, go) มีจุดร่วมคือใช้ -ing เพื่อพูดถึงกิจกรรมที่กำลังพูดถึงโดยตรง ไม่ใช่จุดประสงค์แบบ to", "summary": ["there's no point in / it's no use / it's no good + -ing", "it's (not) worth + -ing", "have trouble/difficulty + -ing, spend/waste time + -ing, go + -ing (กิจกรรมกีฬา)"]}, {"unit": 64, "section": "-ing and to...", "title": "to..., for..., so that... (บอกจุดประสงค์)", "pattern": "to + V1 (จุดประสงค์)  ·  for + noun  ·  so that + can/could/will/would", "sections": [{"label": "A", "explain": "to + verb1 ใช้บอกจุดประสงค์ว่าทำไมถึงทำสิ่งหนึ่ง หรือทำไมสิ่งของนั้นมีอยู่/จำเป็น", "examples": ["I called the office **to confirm** my appointment.", "She saved money **to buy** a new laptop.", "Is there anything **to drink**?", "I need something **to write with**. (บุพบทตกท้ายประโยค)"]}, {"label": "B", "explain": "เปรียบเทียบ for + คำนาม (บอกว่าทำเพื่ออะไร/สิ่งของนั้น) กับ to + กริยา (บอกจุดประสงค์ของการกระทำ) — ห้ามใช้ for + -ing เพื่อบอกเหตุผลที่คนทำสิ่งหนึ่ง", "examples": ["We stopped **for coffee**. = We stopped **to get** coffee.", "I ran **for the bus**. = I ran **to catch** the bus.", "This tool is **for opening** cans. (for + -ing บอกหน้าที่ทั่วไปของสิ่งของ)", "I went to the shop **to buy** milk. (not for buying)"]}, {"label": "C", "explain": "so that ใช้บอกจุดประสงค์เช่นกัน มักใช้คู่กับ can/could/will/would เพื่อเน้นผลลัพธ์ที่ต้องการ; สามารถละ that ได้", "examples": ["She left early **so that she could catch** the first train.", "Speak louder **so that everyone can hear** you.", "I wrote it down **so I wouldn't forget**. (ละ that)"]}], "notes": [], "mistake": {"wrong": "I went to the market for buying vegetables.", "right": "I went to the market to buy vegetables.", "note": "บอกจุดประสงค์ของคนต้องใช้ to + verb1 ไม่ใช่ for + -ing"}, "tip": "for + -ing ใช้บอกว่า 'ของสิ่งนี้มีไว้ทำอะไร' (หน้าที่ทั่วไปของสิ่งของ) ส่วน to + verb ใช้บอกว่า 'คนคนนี้ทำสิ่งนี้ไปเพื่ออะไร' (เจตนาเฉพาะครั้ง)", "summary": ["to + verb1 บอกจุดประสงค์ (why); noun + to + verb (a place to live)", "for + noun (เทียบ to + verb); for -ing บอกหน้าที่ทั่วไปของสิ่งของ", "so that + can/could/will/would บอกจุดประสงค์แบบเน้นผลลัพธ์ที่ต้องการ"]}, {"unit": 65, "section": "-ing and to...", "title": "คำคุณศัพท์ + to...", "pattern": "adjective + to...  ·  It's + adj + of + somebody + to...", "sections": [{"label": "A", "explain": "คำคุณศัพท์หลายตัว (easy, hard, difficult, dangerous, interesting ฯลฯ) ตามด้วย to + verb1 เพื่อประเมินสิ่งหนึ่งว่าเป็นอย่างไรเมื่อลงมือทำ", "examples": ["This exercise is **difficult to understand**.", "Her handwriting is **hard to read**.", "The new phone is **easy to use**.", "It is hard to understand him. = **He is hard to understand.** (not to understand him)"]}, {"label": "B", "explain": "สำนวน It's + adjective (nice/kind/silly/careless ฯลฯ) + of + somebody + to... ใช้ประเมิน 'อุปนิสัย' ของคนคนนั้นจากสิ่งที่เขาทำ", "examples": ["It was **kind of you to help** me carry these bags.", "It was **silly of him to leave** the door unlocked.", "I think it was **unfair of them to blame** you."]}, {"label": "C", "explain": "คำคุณศัพท์ที่บอกปฏิกิริยาความรู้สึก (sorry, glad, surprised, pleased ฯลฯ) ตามด้วย to... และคำอื่นๆ เช่น the first/next/only + to, sure/likely/bound + to", "examples": ["I was **surprised to see** him at the party.", "We were **relieved to hear** the news.", "She was **the first to arrive**.", "Carla is bound **to pass** the exam."]}], "notes": [], "mistake": {"wrong": "It was kind for you to help me.", "right": "It was kind of you to help me.", "note": "ใช้ of ไม่ใช่ for กับสำนวน adjective + of + somebody + to"}, "tip": "กลุ่ม nice/kind/silly + of + somebody + to มักเป็นการประเมิน 'อุปนิสัย' ของคนคนนั้นจากสิ่งที่เขาทำ ต่างจาก sorry/glad + to ที่เป็นการบอก 'ปฏิกิริยา/ความรู้สึก' ต่อเหตุการณ์", "summary": ["adjective + to... (easy/hard/difficult/dangerous to do); He is hard to understand (ไม่ใช้กรรมซ้ำ)", "It's + adjective + of + somebody + to... ประเมินอุปนิสัยจากการกระทำ", "sorry/glad/surprised + to = บอกปฏิกิริยาความรู้สึก; the first/next/only + to; sure/likely/bound + to"]}, {"unit": 66, "section": "-ing and to...", "title": "afraid to / afraid of -ing, interested in / interested to", "pattern": "afraid to do (ไม่ทำเพราะอันตราย)  ·  afraid of -ing (กลัวผลลัพธ์)", "sections": [{"label": "A", "explain": "afraid to do = เลือกที่จะไม่ทำเพราะกลัวอันตรายหรือผลไม่ดี (เป็นการตัดสินใจ) ส่วน afraid of -ing = กลัวว่าจะเกิดเหตุการณ์ไม่ดีขึ้น (เป็นความกังวลถึงผลลัพธ์)", "examples": ["Children were **afraid to go** near the dog.", "She was **afraid of losing** her job, so she worked extra hard.", "I was **afraid to tell** him the truth because I was **afraid of upsetting** him."]}, {"label": "B", "explain": "interested in -ing = สนใจ/อยากจะทำสิ่งนั้น ส่วน interested to do = รู้สึกว่าน่าสนใจหลังจากที่ได้รู้/ได้ยินเรื่องหนึ่ง (คล้ายกับ surprised to, glad to)", "examples": ["Are you **interested in joining** the club?", "I was **interested to hear** that she got the job.", "I'd be **interested to know** what you think."]}, {"label": "C", "explain": "sorry for -ing = ขอโทษสำหรับสิ่งที่ทำไปแล้ว ส่วน sorry to do = แสดงความเสียใจ/เสียดายต่อเรื่องหนึ่ง", "examples": ["I'm **sorry for shouting** at you earlier.", "I'm **sorry to hear** that you lost your job.", "I'll be **sorry to leave** this place; I've had a great time here."]}], "notes": [], "mistake": {"wrong": "I'm afraid of go there alone.", "right": "I'm afraid to go there alone. / I'm afraid of going there alone.", "note": "afraid to + V1 หรือ afraid of + -ing เท่านั้น ห้ามผสมกัน (afraid of go ผิด)"}, "tip": "afraid to do = ตัดสินใจไม่ทำ, afraid of -ing = กังวลว่าผลจะเป็นอย่างไร ลองถามตัวเองว่า 'กลัวจะทำ' หรือ 'กลัวผลที่จะตามมา' เพื่อเลือกโครงสร้างที่ถูก", "summary": ["afraid to do = ไม่ทำเพราะอันตราย, afraid of -ing = กลัวผลลัพธ์ที่จะเกิด", "interested in -ing = อยากทำ/สนใจจะทำ, interested to do = รู้สึกน่าสนใจหลังจากได้รู้/ได้ยิน", "sorry for -ing = ขอโทษที่ทำไปแล้ว, sorry to do = แสดงความเสียใจ/เสียดายต่อเรื่องหนึ่ง"]}, {"unit": 67, "section": "-ing and to...", "title": "see somebody do / see somebody doing", "pattern": "verb + object + V1 (เห็นทั้งเหตุการณ์)  ·  verb + object + V-ing (เห็นระหว่างทำ)", "sections": [{"label": "A", "explain": "see/hear/watch/feel + object + verb1 (ไม่มี to) ใช้เมื่อเห็น/ได้ยินเหตุการณ์ทั้งหมดตั้งแต่ต้นจนจบ", "examples": ["I saw her **leave** the building and get into a taxi.", "We heard him **shout** and then slam the door.", "Did you feel the ground **shake**?"]}, {"label": "B", "explain": "see/hear/watch/feel + object + -ing ใช้เมื่อเห็น/ได้ยินแค่ช่วงหนึ่งระหว่างที่กำลังทำอยู่ ไม่ใช่ทั้งเหตุการณ์", "examples": ["I saw her **walking** along the beach when I looked out the window.", "I could hear it **raining** outside all night.", "We found him **sitting** alone in the park, eating a sandwich."]}], "notes": ["บางประโยคใช้ได้ทั้งสองแบบโดยความหมายไม่ต่างมาก เช่น 'I've never seen her dance/dancing.'"], "mistake": {"wrong": "I saw him to cross the street.", "right": "I saw him cross the street.", "note": "หลัง see/hear/watch/feel + object ตามด้วย V1 หรือ V-ing เท่านั้น ห้ามใช้ to"}, "tip": "ถ้าเห็นเหตุการณ์ตั้งแต่ต้นจนจบ ใช้ V1 (ครบเรื่อง) ถ้าเห็นแค่ตอนหนึ่งระหว่างทำ ใช้ V-ing (กำลังทำอยู่ตอนที่เห็น)", "summary": ["see/hear/watch/feel + object + V1 = เห็น/ได้ยินเหตุการณ์ทั้งหมดตั้งแต่ต้นจนจบ", "see/hear/watch/feel + object + V-ing = เห็น/ได้ยินระหว่างที่กำลังทำอยู่", "ห้ามใช้ to แทรกระหว่างกรรมกับกริยาในโครงสร้างนี้"]}, {"unit": 68, "section": "-ing and to...", "title": "อนุประโยค -ing (having done, doing something ในเวลาเดียวกัน)", "pattern": "-ing clause (สองเหตุการณ์พร้อมกัน)  ·  having + V3 (เหตุการณ์ที่จบก่อน)", "sections": [{"label": "A", "explain": "ใช้ -ing clause เมื่อสองเหตุการณ์เกิดขึ้นพร้อมกัน หรือเหตุการณ์หนึ่งเกิดขึ้นระหว่างอีกเหตุการณ์หนึ่ง", "examples": ["She left the room **crying**. (ร้องไห้ไปด้วยตอนออกจากห้อง)", "He hurt his back **lifting** heavy boxes. (บาดเจ็บระหว่างที่ยกของ)", "Be careful **crossing** this road; it's very busy. (= while crossing)"]}, {"label": "B", "explain": "ใช้ having + V3 (กริยาช่องที่ 3) เมื่อเหตุการณ์แรกเสร็จสมบูรณ์แล้วจึงเกิดเหตุการณ์ถัดไป (สามารถใช้ after + -ing แทนได้เช่นกัน)", "examples": ["**Having finished** the report, she sent it to her manager.", "**Having lived** in Japan for years, he speaks Japanese fluently.", "**After finishing** her coffee, she left for work."]}, {"label": "C", "explain": "-ing clause ที่ขึ้นต้นประโยคยังใช้บอกเหตุผลได้ มักใช้ในภาษาเขียนทางการ และต้องมีเครื่องหมายจุลภาค (,) คั่นหลัง clause นั้น", "examples": ["**Feeling exhausted**, I decided to skip the gym today. (= because I felt exhausted)", "**Not knowing** the address, I asked a stranger for directions.", "**Having seen** the movie before, she didn't want to watch it again."]}], "notes": ["ประธานของ -ing clause กับประธานของประโยคหลักต้องเป็นคนเดียวกันเสมอ มิฉะนั้นประโยคจะฟังดูสับสนหรือผิดหลักไวยากรณ์"], "mistake": {"wrong": "Finishing my homework, I watched TV.", "right": "Having finished my homework, I watched TV.", "note": "ถ้าเหตุการณ์แรกทำเสร็จสมบูรณ์ก่อนเหตุการณ์ที่สองจะเริ่ม ให้ใช้ Having + V3 ไม่ใช่ -ing เฉยๆ ซึ่งสื่อว่าเกิดพร้อมกัน"}, "tip": "ประธานของ -ing clause กับประธานของประโยคหลักต้องเป็นคนเดียวกันเสมอ (ห้ามมี dangling participle) และโครงสร้างนี้มักพบในภาษาเขียนมากกว่าภาษาพูด", "summary": ["-ing clause บอกสองเหตุการณ์ที่เกิดพร้อมกัน หรือเหตุการณ์หนึ่งเกิดระหว่างอีกเหตุการณ์", "having + V3 บอกเหตุการณ์ที่เสร็จสมบูรณ์ก่อนเหตุการณ์ถัดไป", "-ing clause ที่ขึ้นต้นประโยคใช้บอกเหตุผลได้เช่นกัน (มักใช้ในภาษาเขียน มีจุลภาคคั่น)"]}, {"unit": 69, "section": "Articles and nouns", "title": "คำนามนับได้และนับไม่ได้ (1)", "pattern": "countable: a/an + เอกพจน์, พหูพจน์ -s  ·  uncountable: รูปเดียว ไม่มี a/an", "sections": [{"label": "A", "explain": "คำนามนับได้ (countable) มีรูปเอกพจน์ (a/an + noun) และพหูพจน์ (noun+s) ใช้กับตัวเลขได้ ส่วนคำนามนับไม่ได้ (uncountable) มีรูปเดียว ไม่มีพหูพจน์ และห้ามใช้ a/an นำหน้าโดยตรง (แต่ใช้ 'a...of' แทนได้)", "examples": ["I ate **a sandwich** for lunch. (นับได้ เอกพจน์)", "I like **sandwiches**. (นับได้ พหูพจน์)", "Do you have any **money**? (นับไม่ได้ ไม่มีพหูพจน์)", "There's **rice** in the bag. (นับไม่ได้)", "Can I have **a bowl of rice**? (a...of แทน a/an ตรงๆ)"]}, {"label": "B", "explain": "some/any/many/a few ใช้กับคำนามนับได้พหูพจน์ ส่วน some/any/much/a little ใช้กับคำนามนับไม่ได้", "examples": ["We bought **some apples**.", "Did you buy **any apples**?", "I don't have **much money**.", "She has **a few friends** here.", "There's **a little milk** left."]}], "notes": ["สังเกตจาก 'รูปพหูพจน์' ได้ทันที ถ้าคำนามนั้นมีรูปพหูพจน์ตามธรรมชาติ (เติม -s ได้) แสดงว่านับได้ ถ้าไม่มีรูปพหูพจน์เลยและฟังดูเป็น 'มวลรวม' (ของเหลว ผง ก๊าซ ความคิดนามธรรม) มักนับไม่ได้"], "mistake": {"wrong": "I want to buy a bread.", "right": "I want to buy some bread. / a loaf of bread.", "note": "bread เป็นคำนามนับไม่ได้ ห้ามใช้ a/an นำหน้าโดยตรง"}, "tip": "ถามตัวเองว่า 'ของสิ่งนี้มีรูปพหูพจน์ตามธรรมชาติไหม' ถ้ามี (two bananas) มักนับได้ ถ้าไม่มี (ไม่มีใครพูด 'two rices') มักนับไม่ได้", "summary": ["countable nouns มีรูปเอกพจน์ (a/an+noun) และพหูพจน์ (noun+s) ใช้กับตัวเลขได้", "uncountable nouns มีรูปเดียว ไม่มีพหูพจน์ ไม่ใช้ a/an นำหน้า แต่ใช้ 'a...of' แทนได้", "some/any/many/a few ใช้กับนับได้พหูพจน์, some/any/much/a little ใช้กับนับไม่ได้"]}, {"unit": 70, "section": "Articles and nouns", "title": "คำนามนับได้และนับไม่ได้ (2): คำเดียวกัน ความหมายต่าง", "pattern": "countable (สิ่งเฉพาะ) vs uncountable (โดยรวม/ประเภทของวัสดุ)", "sections": [{"label": "A", "explain": "คำนามหลายคำเป็นได้ทั้งนับได้และนับไม่ได้ โดยความหมายต่างกัน: นับได้ = เหตุการณ์/สิ่งของเฉพาะครั้งหนึ่ง, นับไม่ได้ = สิ่งนั้นโดยรวม/เป็นวัสดุ", "examples": ["I heard **a strange noise** outside. (นับได้ = เสียงเฉพาะครั้งหนึ่ง)", "I can't concentrate; there's too much **noise** here. (นับไม่ได้ = เสียงโดยรวม)", "She has beautiful **hair**. (นับไม่ได้ = ผมทั้งหมดบนหัว)", "There's **a hair** in my soup! (นับได้ = เส้นผมเส้นเดียว)", "We had **a great time** at the party. (นับได้)", "I don't have **time** to talk right now. (นับไม่ได้)"]}, {"label": "B", "explain": "คำนามกลุ่มนี้มักเป็นคำนามนับไม่ได้เสมอ แม้ในภาษาไทยจะฟังดูนับได้: advice, furniture, luggage/baggage, information, news, progress, weather, work, accommodation, permission, damage, traffic, behaviour, luck, chaos, scenery, travel", "examples": ["Can you give me some **advice**? (not an advice / advices)", "We don't have much **furniture** in our new flat.", "Let me know if you need more **information**.", "The **news** was very surprising. (not The news were)", "They spend a lot of money on **travel**. (การเดินทางโดยทั่วไป)"]}], "notes": ["travel (คำนาม) = การเดินทางโดยทั่วไป (uncountable) ต่างจาก a trip/a journey ที่หมายถึงการเดินทางครั้งหนึ่ง (countable): 'We had a very good trip.' (not a good travel)"], "mistake": {"wrong": "I had a very good travel.", "right": "I had a very good trip/journey.", "note": "travel เป็นคำนามนับไม่ได้ที่แปลว่า 'การเดินทางโดยทั่วไป' ไม่ใช่การเดินทางครั้งหนึ่ง ให้ใช้ trip/journey แทน"}, "tip": "กลุ่มคำนามนับไม่ได้ที่มักสับสน (advice, furniture, information, news, luggage) ควรท่องจำเป็นกลุ่มพิเศษ เพราะในภาษาไทยคำเหล่านี้มักฟังดูเหมือนนับได้ (เช่น 'คำแนะนำหนึ่งข้อ')", "summary": ["คำนามหลายคำมีทั้งความหมายนับได้และนับไม่ได้ ขึ้นกับว่าพูดถึง 'สิ่งเฉพาะ' หรือ 'โดยรวม/ประเภท'", "advice/furniture/luggage/information/news/progress/weather/work ฯลฯ เป็นคำนามนับไม่ได้เสมอ ไม่มีรูปพหูพจน์", "travel (uncountable) ≠ a trip/a journey (countable)"]}, {"unit": 71, "section": "Articles and nouns", "title": "คำนามนับได้กับ a/an และ some", "pattern": "a/an + เอกพจน์นับได้ (ต้องมีเสมอ)  ·  some + พหูพจน์นับได้", "sections": [{"label": "A", "explain": "คำนามนับได้เอกพจน์ต้องมี a/an (หรือ the/my/this ฯลฯ) นำหน้าเสมอ ห้ามใช้ลอยๆ", "examples": ["Do you need **an umbrella**? It looks like rain.", "She never wears **a hat**.", "What **a beautiful day**!", "Did you hurt **your leg**?"]}, {"label": "B", "explain": "some ใช้กับพหูพจน์นับได้ในสองความหมาย: (1) จำนวนหนึ่ง/ไม่กี่ (2) บางส่วนแต่ไม่ใช่ทั้งหมด — แต่เมื่อพูดถึงสิ่งของโดยทั่วไปจะไม่ใช้ some", "examples": ["I've seen **some** good movies recently.", "**Some** children learn languages quickly, but not all.", "I need **some** new sunglasses.", "I love **bananas**. (not some bananas — พูดถึงกล้วยโดยทั่วไป)"]}, {"label": "C", "explain": "a/an ใช้บอกประเภทของสิ่งของ หรืออาชีพของคน และใช้เมื่อบอกลักษณะรูปร่าง แม้จะมีชิ้นเดียวต่อคน (เช่น จมูก)", "examples": ["A dog is **an animal**.", "Sandra is **a nurse**. (not Sandra is nurse)", "Jack has **a long nose**.", "Jack has **blue eyes**. (not the blue eyes)"]}], "notes": [], "mistake": {"wrong": "My father is doctor.", "right": "My father is a doctor.", "note": "บอกอาชีพต้องมี a/an นำหน้าเสมอ (ยกเว้นเมื่อเป็นพหูพจน์)"}, "tip": "อวัยวะที่มีลักษณะเฉพาะตัว (จมูก ใบหน้า) แม้จะมีแค่ชิ้นเดียวต่อคน ก็มักใช้ a/an นำหน้าเมื่อพูดถึงลักษณะ ไม่ใช่ the", "summary": ["คำนามนับได้เอกพจน์ต้องมี a/an (หรือ the/my ฯลฯ) นำหน้าเสมอ ห้ามใช้ลอยๆ", "some ใช้กับพหูพจน์นับได้ได้สองความหมาย: จำนวนหนึ่ง หรือ บางส่วนไม่ใช่ทั้งหมด", "a/an ใช้บอกประเภท/อาชีพ/ลักษณะของคนหรือสิ่งของ"]}, {"unit": 72, "section": "Articles and nouns", "title": "a/an และ the", "pattern": "a/an = พูดถึงครั้งแรก/บอกประเภท  ·  the = สิ่งที่เจาะจง/รู้กันแล้ว", "sections": [{"label": "A", "explain": "เราใช้ a/an เมื่อพูดถึงสิ่งหนึ่งเป็นครั้งแรก หรือบอกว่าเป็น 'ประเภท' ใด และเปลี่ยนมาใช้ the เมื่อพูดถึงสิ่งเดียวกันอีกครั้ง เพราะผู้ฟังรู้แล้วว่าคืออันไหน", "examples": ["I had **a sandwich** and **an apple** for lunch. **The sandwich** wasn't very good, but **the apple** was nice.", "We stayed at **a** very cheap hotel. (ประเภทของโรงแรม)", "**The hotel** where we stayed was very cheap. (โรงแรมที่เจาะจง)"]}, {"label": "B", "explain": "เราใช้ a/an ในสำนวนบอกอัตรา/ความถี่ (ครั้งละ.../กิโลละ...)", "examples": ["I go to the cinema about once **a month**.", "'How much are those potatoes?' '£1.50 **a kilo**.'", "Helen works eight hours **a day**, six days **a week**."]}, {"label": "C", "explain": "เราใช้ the เมื่อชัดเจนอยู่แล้วว่ากำลังพูดถึงสิ่งไหน (จากบริบทของสถานที่/สถานการณ์) รวมถึงสำนวน go to the bank/post office/doctor/dentist", "examples": ["Can you turn off **the light**, please? (= ไฟในห้องนี้)", "I took a taxi to **the station**. (= สถานีในเมืองนั้น)", "I have to go to **the bank** and then **the post office**.", "Clare isn't well. She's gone to **the doctor**."]}], "notes": [], "mistake": {"wrong": "My sister is dentist.", "right": "My sister is a dentist.", "note": "บอกอาชีพต้องมี a/an นำหน้าเสมอ ต่างจาก 'the dentist' ที่หมายถึงหมอฟันประจำตัวที่ไปหา"}, "tip": "ถามตัวเองว่า 'ผู้ฟังรู้ไหมว่าเรากำลังพูดถึงอันไหน' ถ้ารู้แล้ว (เพราะเคยพูดถึงหรือมีอันเดียวในบริบทนั้น) ใช้ the ถ้าเป็นการพูดถึงครั้งแรกหรือบอกประเภททั่วไป ใช้ a/an", "summary": ["a/an = ครั้งแรกที่พูดถึง หรือบอกประเภท, the = สิ่งที่เจาะจง/รู้กันแล้วว่าคืออันไหน", "ใช้ a/an ในสำนวนบอกอัตรา (once a week, £5 a kilo)", "the bank/the post office/the doctor/the dentist ใช้เมื่อพูดถึงที่ที่ผู้พูดนึกถึงเป็นการเฉพาะ"]}, {"unit": 73, "section": "Articles and nouns", "title": "the (1): สิ่งเดียวในโลก, ขั้นสุด, breakfast/platform ไม่มี the", "pattern": "the + สิ่งที่มีหนึ่งเดียว  ·  the + superlative  ·  breakfast/platform 5 (ไม่มี the)", "sections": [{"label": "A", "explain": "เราใช้ the เมื่อมีสิ่งนั้นเพียงหนึ่งเดียว (เช่น เส้นศูนย์สูตร เมืองหลวง) และใช้ the คู่กับคำคุณศัพท์ขั้นสุด (superlative) เสมอ", "examples": ["Have you ever crossed **the equator**?", "Buenos Aires is **the capital** of Argentina.", "What's **the longest** river in Europe?", "The sun is **a star**. (= ดวงหนึ่งในหลายดวง จึงใช้ a ไม่ใช่ the)"]}, {"label": "B", "explain": "เราพูด breakfast/lunch/dinner โดยไม่มี the ตามปกติ แต่ถ้ามีคำคุณศัพท์ขยายต้องเติม a/an นำหน้า และเราไม่ใช้ the กับหมายเลขห้อง ชานชาลา ขนาด หน้าหนังสือ เป็นต้น", "examples": ["What did you have for **breakfast**?", "We had **a very nice lunch**. (not We had very nice lunch)", "Our train leaves from **platform 5**. (not the platform 5)", "Do you have these shoes in **size 43**?"]}, {"label": "C", "explain": "เราใช้ the กับคำที่หมายถึงโลก จักรวาล ท้องฟ้า และสถานที่ตามธรรมชาติที่มีหนึ่งเดียว: the world, the sun, the moon, the sky, the sea, the ground, the country", "examples": ["I love to look at **the stars** in **the sky**.", "Do you live in a town or in **the country**?", "The earth goes round **the sun**.", "I watch **TV** a lot, but I don't listen to **the radio** much."]}], "notes": ["เราพูด 'the same' เสมอ: 'Your sweater is the same colour as mine.' (not is same colour)"], "mistake": {"wrong": "We had very nice lunch.", "right": "We had a very nice lunch.", "note": "breakfast/lunch/dinner ไม่มี the ตามปกติ แต่ถ้ามีคำคุณศัพท์ขยาย ต้องเติม a/an นำหน้า"}, "tip": "กลุ่มคำที่ไม่ใช้ the เพราะมีแค่หนึ่งเดียวในโลก/จักรวาลนั้นอาจดูขัดสามัญสำนึก บางคำใช้ the (the sun, the sky) เพราะเจาะจงหนึ่งเดียวในระบบสุริยะ ในขณะที่ breakfast/platform/room+เลข ไม่ใช้ the เพราะเป็นชื่อเฉพาะเจาะจงในตัวเองอยู่แล้ว (เหมือนชื่อ)", "summary": ["the ใช้เมื่อมีสิ่งเดียวในโลก/บริบทนั้น และกับ superlative เสมอ", "breakfast/lunch/dinner, room/page/platform+เลข ไม่ใช้ the ตามปกติ", "the world/sun/sea/sky/ground/country มี the, แต่ TV และ home/bed/work บางสำนวนไม่มี the"]}, {"unit": 74, "section": "Articles and nouns", "title": "the (2): school / the school", "pattern": "go to school/hospital/prison/church (จุดประสงค์หลัก, ไม่มี the)  ·  go to the school/hospital (บทบาทอื่น, มี the)", "sections": [{"label": "A", "explain": "เราไม่ใช้ the กับ school/university/hospital/prison/church เมื่อพูดถึงจุดประสงค์หลักของสถานที่นั้น (เรียน/รักษา/ถูกคุมขัง/สวดมนต์) แต่ใช้ the เมื่อพูดถึงอาคารนั้นในบทบาทอื่น เช่น ไปเยี่ยม", "examples": ["Ellie is at **school** now. (เป็นนักเรียน)", "Ellie's mother has gone to **the school** to see the teacher. (ไปในฐานะผู้มาเยี่ยม)", "Joe was taken to **hospital** and is still **in hospital** now. (เป็นผู้ป่วย)", "Jane has gone to **the hospital** to visit Joe. (ไปเยี่ยม ไม่ใช่ผู้ป่วย)", "Ken's brother is **in prison**. Ken went to **the prison** to visit his brother."]}, {"label": "B", "explain": "สำนวน go to bed/be in bed, go to work/be at work, go home/be at home ก็ไม่ใช้ the เช่นกัน เพราะเป็นการพูดถึง 'กิจกรรม' ไม่ใช่สิ่งของ/สถานที่จริง", "examples": ["I'm going to **bed** now. Goodnight.", "I sat down on **the bed**. (เตียงจริงๆ ไม่ใช่สำนวน)", "What time do you usually finish **work**?", "Let's go **home**."]}], "notes": [], "mistake": {"wrong": "She's gone to school to see the teacher.", "right": "She's gone to the school to see the teacher.", "note": "ถ้าไปในฐานะผู้มาเยี่ยม (ไม่ใช่นักเรียน) ต้องใช้ the school"}, "tip": "คำถามสำคัญคือ 'คนคนนี้มีบทบาทอะไรกับสถานที่นั้น' ถ้าเป็นบทบาทตามจุดประสงค์เดิมของสถานที่ (นักเรียน/คนไข้/นักโทษ/ผู้มาสวดมนต์) ไม่ใช้ the ถ้าไปในบทบาทอื่น (ผู้มาเยี่ยม/ช่างซ่อม) ให้ใช้ the", "summary": ["school/university/hospital/prison/church ไม่มี the เมื่อพูดถึงจุดประสงค์หลักของสถานที่นั้น", "มี the เมื่อพูดถึงอาคารนั้นในบทบาทอื่น เช่น ไปเยี่ยม", "go to bed/be in bed, go to work/be at work, go home/be at home ไม่มี the"]}, {"unit": 75, "section": "Articles and nouns", "title": "the (3): children / the children (ทั่วไป vs เฉพาะเจาะจง)", "pattern": "ไม่มี the = พูดถึงทั่วไป  ·  the = พูดถึงกลุ่ม/สิ่งที่เจาะจง", "sections": [{"label": "A", "explain": "เมื่อพูดถึงคนหรือสิ่งของ 'โดยทั่วไป' (ทั้งหมดของประเภทนั้น) เราไม่ใช้ the", "examples": ["I'm afraid of **dogs**. (โดยทั่วไป)", "**Doctors** are usually paid more than **teachers**.", "Do you like **classical music**?", "**Most people** enjoy music. (not the most people)"]}, {"label": "B", "explain": "เมื่อพูดถึงคนหรือสิ่งของ 'ที่เจาะจง' (รู้ว่าคือกลุ่มไหน/อันไหน) เราใช้ the", "examples": ["We took **the children** to the zoo. (ลูกของผู้พูดโดยเฉพาะ)", "The film wasn't very good, but I liked **the music**. (ดนตรีในหนังเรื่องนั้น)", "Can you pass **the sugar**, please? (น้ำตาลบนโต๊ะตรงหน้า)"]}, {"label": "C", "explain": "เส้นแบ่งระหว่าง 'ทั่วไป' กับ 'เฉพาะเจาะจง' บางครั้งไม่ชัดเจน ให้พิจารณาจากบริบทว่ากำลังพูดถึงกลุ่มย่อยที่เจาะจงหรือไม่", "examples": ["I like working with **people**. (คนโดยทั่วไป)", "I like **the people** I work with. (คนกลุ่มเฉพาะที่ทำงานด้วย)", "Do you like **coffee**? (โดยทั่วไป)", "**The coffee** we had after dinner wasn't very good. (กาแฟแก้วที่เจาะจง)"]}], "notes": [], "mistake": {"wrong": "The children learn from playing.", "right": "Children learn from playing.", "note": "พูดถึงเด็กโดยทั่วไป (ไม่ใช่กลุ่มเฉพาะ) ห้ามใส่ the"}, "tip": "ลองแทนประโยคด้วยคำว่า 'โดยทั่วไป' ถ้าใส่แล้วยังได้ใจความเดิม แสดงว่าไม่ต้องมี the ถ้าประโยคหมายถึงสิ่งเจาะจงกลุ่มหนึ่งเท่านั้น ต้องมี the", "summary": ["ไม่ใช้ the เมื่อพูดถึงคน/สิ่งของโดยทั่วไป (ทั้งหมดของประเภทนั้น)", "ใช้ the เมื่อพูดถึงกลุ่ม/สิ่งที่เจาะจง (รู้ว่าคืออันไหน)", "เส้นแบ่งระหว่างทั่วไปกับเฉพาะเจาะจงบางครั้งไม่ชัดเจน ให้พิจารณาจากบริบท"]}, {"unit": 76, "section": "Articles and nouns", "title": "the (4): the giraffe / the telephone / the old / the French", "pattern": "the + สัตว์/สิ่งประดิษฐ์เอกพจน์ = ประเภท  ·  the + adjective = กลุ่มคน  ·  the + สัญชาติ -ch/-sh", "sections": [{"label": "A", "explain": "เราใช้ the + คำนามเอกพจน์ เมื่อพูดถึง 'ประเภท' ของสัตว์ สิ่งประดิษฐ์ หรือเครื่องดนตรี ไม่ใช่ตัว/ชิ้นใดชิ้นหนึ่ง", "examples": ["**The giraffe** is the tallest of all animals.", "When was **the camera** invented?", "Can you play **the guitar**?", "I'd like to have a piano, but I can't play **the piano**."]}, {"label": "B", "explain": "เราใช้ the + adjective (ไม่มีคำนามตามหลัง) เพื่อพูดถึงกลุ่มคนตามลักษณะนั้น ความหมายเป็นพหูพจน์เสมอ: the old, the rich, the poor, the unemployed, the injured, the homeless, the sick", "examples": ["Do you think **the rich** should pay higher taxes?", "We need to do more to help **the homeless**.", "For one person, we say **a rich man** (not a rich)."]}, {"label": "C", "explain": "เราใช้ the + คำคุณศัพท์บอกสัญชาติที่ลงท้าย -ch/-sh/-ese/-ss เพื่อหมายถึงคนทั้งชาตินั้น (ความหมายพหูพจน์)", "examples": ["**The French** are famous for their food.", "I met **a French woman**. (ไม่ใช่ 'a French')", "**The Chinese**, **the Swiss** สามารถใช้เอกพจน์ได้ด้วย (a Chinese, a Swiss)", "สัญชาติอื่นเติม -s: **Italians**, **Mexicans**, **Thais**."]}], "notes": [], "mistake": {"wrong": "French are famous for their food.", "right": "The French are famous for their food.", "note": "nationality adjective ที่ลงท้าย -ch/-sh ต้องมี the นำหน้าเมื่อหมายถึงคนทั้งชาติ"}, "tip": "the + สิ่งของ/สัตว์เอกพจน์ = พูดถึง 'ประเภท' ไม่ใช่ตัวใดตัวหนึ่ง (the giraffe = ยีราฟในฐานะสายพันธุ์) ต่างจาก a giraffe ที่หมายถึงยีราฟตัวหนึ่ง", "summary": ["the + คำนามเอกพจน์ ใช้พูดถึงประเภทของสัตว์/สิ่งประดิษฐ์/เครื่องดนตรี", "the + adjective (ไม่มีคำนาม) = กลุ่มคนตามลักษณะนั้น (the rich, the homeless) ความหมายพหูพจน์เสมอ", "the + สัญชาติที่ลงท้าย -ch/-sh/-ese/-ss = คนทั้งชาตินั้น (the French, the Chinese)"]}, {"unit": 77, "section": "Articles and nouns", "title": "ชื่อเฉพาะที่มีและไม่มี the (1)", "pattern": "ไม่มี the: คน ทวีป ประเทศ เกาะ เมือง ภูเขาเดี่ยว  ·  มี the: มหาสมุทร ทะเล แม่น้ำ ทะเลทราย ชื่อพหูพจน์", "sections": [{"label": "A", "explain": "เราไม่ใช้ the กับชื่อคน ทวีป ประเทศ รัฐ เกาะ เมือง และภูเขาเดี่ยว แต่ใช้ the กับชื่อที่มีคำว่า Republic/Kingdom/States", "examples": ["Have you been to **Canada** or **the United States**?", "**Africa**, **Sicily**, **Bangkok**, **Everest** (ไม่มี the)", "**the United Kingdom (the UK)**, **the Czech Republic** (มี the)"]}, {"label": "B", "explain": "เราไม่ใช้ the กับ Mr/Doctor/Captain/President + ชื่อ และกับ Mount/Lake + ชื่อ", "examples": ["We called **Doctor Johnson**. (not the Doctor Johnson)", "**Mount Everest** (not the Mount Everest)", "**Lake Victoria** (not the Lake Victoria)", "They live near **the lake**, but not 'the Lake Superior'."]}, {"label": "C", "explain": "เราใช้ the กับชื่อมหาสมุทร ทะเล แม่น้ำ คลอง และทะเลทราย และกับชื่อพหูพจน์ของคน/ประเทศ/กลุ่มเกาะ/เทือกเขา", "examples": ["**the Atlantic**, **the Nile**, **the Suez Canal**, **the Sahara**", "**the Johnsons** (ครอบครัว), **the Philippines**, **the Andes**"]}], "notes": ["เราพูด 'the north/south (of + ประเทศ)' แต่ 'northern/southern + ประเทศ' (ไม่มี the): 'Sweden is in northern Europe.'"], "mistake": {"wrong": "Everest was first climbed by the Everest expedition of the the mountain.", "right": "Everest was first climbed in 1953.", "note": "ชื่อภูเขาเดี่ยวไม่ใช้ the นำหน้า"}, "tip": "หลักการเดียวกันนี้ใช้ได้กับชื่อเฉพาะส่วนใหญ่: ถ้าเป็น 'ชื่อ' ตรงๆ (Everest, Doctor Johnson, Canada) ไม่มี the แต่ถ้าเป็นคำอธิบาย/หมวดหมู่ที่แฝงอยู่ในชื่อ (the United Kingdom, the Nile, the Andes) มักมี the", "summary": ["ไม่ใช้ the กับชื่อคน ทวีป ประเทศ เกาะ เมือง ภูเขาเดี่ยว (ยกเว้นชื่อที่มีคำว่า Republic/Kingdom/States)", "ไม่ใช้ the กับ Mr/Doctor/Captain + ชื่อ, Mount, Lake", "ใช้ the กับมหาสมุทร ทะเล แม่น้ำ คลอง ทะเลทราย และชื่อพหูพจน์ (ตระกูล, กลุ่มเกาะ, เทือกเขา)"]}, {"unit": 78, "section": "Articles and nouns", "title": "ชื่อเฉพาะที่มีและไม่มี the (2)", "pattern": "ไม่มี the: ถนน สวนสาธารณะ ชื่อสองคำ (สถานที่+อาคาร)  ·  มี the: โรงแรม โรงละคร พิพิธภัณฑ์ ชื่อที่มี 'of'", "sections": [{"label": "A", "explain": "เราไม่ใช้ the กับชื่อถนน/สวนสาธารณะ และไม่ใช้ the กับชื่อสองคำแบบ 'สถานที่หรือบุคคล + ประเภทอาคาร' เช่นสนามบิน มหาวิทยาลัย พระราชวัง", "examples": ["**Union Street**, **Hyde Park** (ไม่มี the)", "**Manchester Airport**, **Edinburgh Castle**, **Buckingham Palace** (ไม่มี the)", "Buckingham Palace (ไม่มี the) แต่ **the Royal Palace** (Royal เป็นคำคุณศัพท์ ไม่ใช่ชื่อ จึงมี the)"]}, {"label": "B", "explain": "ชื่ออาคารส่วนใหญ่อื่นๆ (โรงแรม โรงละคร/โรงหนัง พิพิธภัณฑ์ อาคารสำคัญ) มักมี the นำหน้า และชื่อที่มีคำว่า 'of' มักมี the เสมอ", "examples": ["**the Sheraton Hotel**, **the Palace Theatre**, **the Guggenheim Museum**", "**the White House**, **the Eiffel Tower**", "**the Tower of London**, **the Bank of England**"]}, {"label": "C", "explain": "ชื่อร้าน/ร้านอาหาร/โรงแรมที่ตั้งตามชื่อคน (ลงท้าย -'s หรือ -s) และชื่อบริษัท/สายการบิน มักไม่ใช้ the", "examples": ["**McDonald's**, **Macy's** (ไม่มี the)", "**St Paul's Cathedral** (ไม่มี the)", "**Sony**, **IBM**, **Singapore Airlines** (ไม่มี the)", "แต่หนังสือพิมพ์และองค์กรส่วนใหญ่มี the: **the Washington Post**, **the BBC**, **the Red Cross**"]}], "notes": [], "mistake": {"wrong": "I work for the IBM.", "right": "I work for IBM.", "note": "ชื่อบริษัท/สายการบินส่วนใหญ่ไม่ใช้ the นำหน้า"}, "tip": "ชื่อที่ประกอบด้วย 'ชื่อสถานที่/บุคคล + ประเภทอาคาร' (Manchester Airport, Buckingham Palace) มักไม่มี the ส่วนชื่อที่เป็น 'the + คำนามอธิบาย' (the White House, the Iron Bridge) มักมี the", "summary": ["ไม่ใช้ the กับชื่อถนน/สวนสาธารณะ และชื่อสองคำแบบ 'สถานที่/บุคคล+ประเภทอาคาร'", "ใช้ the กับชื่อโรงแรม โรงละคร พิพิธภัณฑ์ อาคารสำคัญส่วนใหญ่ และชื่อที่มี 'of'", "ไม่ใช้ the กับชื่อร้าน/บริษัท/สายการบินที่ลงท้าย -'s หรือเป็นชื่อคน/แบรนด์ทั่วไป"]}, {"unit": 79, "section": "Articles and nouns", "title": "เอกพจน์และพหูพจน์: trousers, gymnastics, the government", "pattern": "trousers/glasses/scissors (พหูพจน์เสมอ)  ·  -ics เป็นเอกพจน์  ·  government/team/police (กริยาพหูพจน์)", "sections": [{"label": "A", "explain": "คำนามบางคำที่หมายถึงสิ่งของชิ้นเดียวที่มีสองส่วน (trousers, jeans, glasses, scissors, pyjamas) เป็นรูปพหูพจน์เสมอ ใช้กริยาพหูพจน์ และใช้ 'a pair of' เมื่อต้องการนับ", "examples": ["My **trousers are** too long. (not My trousers is)", "That's **a nice pair of jeans**. (not a nice jeans)", "I need some new **glasses**. or **a new pair of glasses**."]}, {"label": "B", "explain": "คำนามที่ลงท้าย -ics (athletics, politics, physics, economics, maths) มักเป็นเอกพจน์ ไม่ใช่พหูพจน์ และ news เป็นเอกพจน์เสมอ ส่วนบางคำ (means, series, species) รูปเดียวกันทั้งเอกพจน์และพหูพจน์", "examples": ["**Gymnastics is** my favourite sport. (not Gymnastics are)", "I have some **news** for you. It's good **news**.", "a TV **series** / two TV **series** (รูปเดียวกัน)"]}, {"label": "C", "explain": "คำนามที่หมายถึงกลุ่มคน (audience, committee, family, government, staff, team) มักใช้กับกริยาพหูพจน์ในภาษาอังกฤษแบบอังกฤษ เพราะมองว่าเป็น 'คนหลายคน' ไม่ใช่ 'สิ่งเดียว'", "examples": ["**The government have** decided to increase taxes.", "**The police are** investigating the crime.", "**Italy are** playing Brazil on Sunday.", "**People** ใช้แทน persons เสมอ: 'They are nice people.' (not nice persons)"]}, {"label": "D", "explain": "เมื่อพูดถึงจำนวนเงิน ช่วงเวลา หรือระยะทางเป็น 'หนึ่งก้อน/หนึ่งช่วง' เราถือว่าเป็นสิ่งเดียว จึงใช้กริยาเอกพจน์", "examples": ["**Fifty thousand pounds was** stolen in the robbery. (not were stolen)", "**Three years is** a long time to be without a job.", "**Two miles isn't** very far to walk."]}], "notes": [], "mistake": {"wrong": "The police is investigating the crime.", "right": "The police are investigating the crime.", "note": "police ใช้กริยาพหูพจน์เสมอ"}, "tip": "ตรวจสอบว่าเรามองคำนามนั้นเป็น 'หนึ่งเดียว' (จำนวนเงิน ระยะเวลา ระยะทาง) หรือ 'กลุ่มคน' (government, team, police) — ถ้าเป็นหนึ่งเดียวใช้กริยาเอกพจน์ ถ้าเป็นกลุ่มคนมักใช้กริยาพหูพจน์ในภาษาอังกฤษแบบอังกฤษ", "summary": ["คำนามที่ประกอบด้วยสองส่วน (trousers, glasses, scissors) เป็นพหูพจน์เสมอ ใช้ a pair of เมื่อนับ", "-ics เป็นเอกพจน์ (politics, physics), news เป็นเอกพจน์เสมอ", "collective nouns (government, team, police, family) มักใช้กริยาพหูพจน์ (แบบอังกฤษ); จำนวนเงิน/เวลา/ระยะทาง ใช้กริยาเอกพจน์เพราะมองเป็นหนึ่งเดียว"]}, {"unit": 80, "section": "Articles and nouns", "title": "คำนาม + คำนาม (a bus driver / a headache)", "pattern": "noun + noun (คำนามแรกทำหน้าที่เหมือนคำคุณศัพท์)", "sections": [{"label": "A", "explain": "เราสามารถใช้คำนามสองคำเรียงติดกัน (noun + noun) เพื่อหมายถึงสิ่งเดียว โดยคำนามแรกทำหน้าที่คล้ายคำคุณศัพท์บอกว่าคำนามที่สองเป็น 'ประเภท' ใด", "examples": ["**a bus driver** = the driver of a bus", "**income tax** = tax that you pay on your income", "**the city centre** = the centre of the city", "**a washing machine**, **a frying pan** (คำแรกลงท้าย -ing)"]}, {"label": "B", "explain": "บางครั้งมีคำนามมากกว่าสองคำเรียงติดกัน และการเขียนติดกันเป็นคำเดียวหรือแยกสองคำไม่มีกฎตายตัว", "examples": ["We waited at the **hotel reception desk**.", "If you want to play **table tennis**, you need a **table tennis table**.", "**a headache**, **toothpaste**, **a weekend** (เขียนติดกัน) vs **a car park**, **a road sign** (แยกคำ)"]}, {"label": "C", "explain": "คำนามตัวแรกในโครงสร้างนี้เป็นเอกพจน์เสมอแม้ความหมายจะเป็นพหูพจน์ และเมื่อใช้ตัวเลข+หน่วย+คำนามขยายคำนามอื่น หน่วยนั้นต้องเป็นเอกพจน์เสมอ", "examples": ["**a car park** (= ที่จอดรถหลายคัน แต่ car ไม่เติม s)", "It was **a four-week course**. (not a four weeks course)", "The course lasted **four weeks**. (พูดแยกประโยค ใช้พหูพจน์ได้)", "two **14-year-old** girls"]}], "notes": ["แยกความหมาย 'ภาชนะเปล่า' (a coffee cup) กับ 'ภาชนะที่มีของอยู่' (a cup of coffee): 'a shopping bag' (ถุงเปล่า) vs 'a bag of shopping' (ถุงที่มีของซื้อมาอยู่ในนั้น)"], "mistake": {"wrong": "It was a four weeks course.", "right": "It was a four-week course.", "note": "เมื่อใช้ตัวเลข+หน่วย+คำนามเป็นคำคุณศัพท์ขยายหน้าคำนาม หน่วยนั้นต้องเป็นเอกพจน์เสมอ (four-week ไม่ใช่ four-weeks)"}, "tip": "คำนามตัวแรกในโครงสร้าง noun+noun ทำหน้าที่เหมือนคำคุณศัพท์ จึงไม่ผัน -s ตามจำนวน แม้ความหมายจะเป็นพหูพจน์ก็ตาม", "summary": ["noun + noun ใช้คำนามตัวแรกขยายตัวที่สองเหมือนคำคุณศัพท์ (a bus driver, a car park)", "แยกความหมาย 'ภาชนะเปล่า' (a coffee cup) กับ 'ภาชนะที่มีของอยู่' (a cup of coffee)", "ตัวเลข+หน่วย+คำนาม ที่ทำหน้าที่ขยายคำนามอื่นต้องใช้หน่วยเป็นเอกพจน์เสมอ (a ten-pound note, a six-mile walk)"]}, {"unit": 81, "section": "Articles and nouns", "title": "-'s และ of...", "pattern": "-'s (คนและสัตว์)  ·  of (สิ่งของและแนวคิด)", "sections": [{"label": "A", "explain": "เราใช้ -'s (apostrophe + s) กับคนหรือสัตว์เพื่อบอกความเป็นเจ้าของ คำนามเอกพจน์เติม -'s ส่วนคำนามพหูพจน์ที่ลงท้าย -s แล้วเติมแค่ (') และคำนามพหูพจน์ที่ไม่ลงท้าย -s (men/women/children/people) เติม -'s ตามปกติ", "examples": ["**Tom's computer** isn't working.", "**my sister's room** (เอกพจน์ - พี่สาวคนเดียว) vs **my sisters' room** (พหูพจน์ - พี่สาวหลายคน)", "**the children's book** (children ไม่ลงท้าย -s จึงเติม -'s)", "**Jack and Karen's children** (เป็นเจ้าของร่วมกัน เติม -'s ครั้งเดียวท้ายชื่อสุดท้าย)"]}, {"label": "B", "explain": "เราใช้ of สำหรับสิ่งของหรือแนวคิด (ไม่ใช่คน/สัตว์) และในสำนวนบอกตำแหน่ง เช่น the beginning/end/top/bottom/front/back of...", "examples": ["**the name of the book** (not the book's name)", "**the temperature of the water**", "**the beginning of the month**, **the top of the hill**"]}, {"label": "C", "explain": "เราสามารถใช้ -'s หรือ of ได้ทั้งคู่กับองค์กรหรือสถานที่ และใช้ -'s กับคำบอกเวลา (yesterday's, next week's) และช่วงเวลา (a week's holiday)", "examples": ["**the government's decision** = **the decision of the government**", "**the city's streets**, **Italy's prime minister**", "Do you still have **yesterday's newspaper**?", "I've got **a week's holiday**. It's only **ten minutes' walk**."]}], "notes": [], "mistake": {"wrong": "the man we met yesterday's mother", "right": "the mother of the man we met yesterday", "note": "ห้ามใช้ -'s ต่อท้ายกลุ่มคำยาวๆ ให้ใช้ of แทน"}, "tip": "กฎง่ายๆ: คน/สัตว์ใช้ -'s, สิ่งของ/แนวคิดนามธรรมใช้ of; แต่องค์กรและสถานที่เลือกได้ทั้งสองแบบ", "summary": ["ใช้ -'s (หรือ -' กับพหูพจน์ที่ลงท้าย s) กับคนและสัตว์เพื่อบอกความเป็นเจ้าของ", "ใช้ of กับสิ่งของ/แนวคิด ที่ไม่ใช่คน/สัตว์", "ใช้ -'s กับคำบอกเวลา (yesterday's, next week's) และช่วงเวลา (a week's holiday, ten minutes' walk)"]}, {"unit": 82, "section": "Pronouns and determiners", "title": "สรรพนามสะท้อน: myself/yourself/themselves", "pattern": "reflexive pronoun เมื่อประธาน=กรรม  ·  each other/one another (กระทำต่อกัน)", "sections": [{"label": "A", "explain": "เราใช้ myself/yourself/himself/herself/itself/ourselves/yourselves/themselves เมื่อประธานและกรรมของประโยคเป็นคนเดียวกัน แต่ไม่ใช้ตามหลัง feel/relax/concentrate/meet และปกติไม่ใช้ตามหลัง wash/shave/dress", "examples": ["I'll pay for **myself**. (not I'll pay for me)", "Amy really enjoyed **herself** on holiday.", "Do you talk to **yourself** sometimes?", "I **feel** nervous.  I can't **relax**. (ไม่ใช้ relax myself)", "He got up, **washed**, **shaved** and **dressed**. (not washed himself)"]}, {"label": "B", "explain": "-selves (สะท้อนกลับตัวเอง) ต่างจาก each other/one another (กระทำต่อกันและกัน แบบ reciprocal)", "examples": ["Kate and Joe looked at **themselves** in the mirror. (มองตัวเอง)", "Kate looked at Joe, and Joe looked at Kate. They looked at **each other**.", "How long have you known **each other**? (or one another)"]}, {"label": "C", "explain": "เราใช้ myself/yourself เพื่อเน้นว่า 'ตัวฉันเอง ไม่ใช่คนอื่น' (emphatic use)", "examples": ["'Who repaired your bike?' 'I repaired it **myself**.'", "You can do it **yourself**. (= you, not me)", "The film **itself** wasn't very good, but I loved the music."]}], "notes": [], "mistake": {"wrong": "I need to concentrate myself.", "right": "I need to concentrate.", "note": "concentrate/relax/feel/meet ไม่ใช้ reflexive pronoun ตามหลัง"}, "tip": "กริยาที่เกี่ยวกับการดูแลร่างกายตัวเอง (wash, shave, dress) มักไม่ใช้ reflexive เพราะโดยธรรมชาติทำกับตัวเองอยู่แล้ว ต่างจากภาษาไทยที่อาจพูดว่า 'อาบน้ำตัวเอง'", "summary": ["ใช้ reflexive pronoun เมื่อประธานและกรรมเป็นคนเดียวกัน", "ไม่ใช้ reflexive หลัง feel/relax/concentrate/meet และปกติไม่ใช้หลัง wash/shave/dress", "-selves = สะท้อนกลับตัวเอง, each other/one another = กระทำต่อกันและกัน; myself/yourself ยังใช้เน้นความหมาย 'ตัวฉันเอง' ได้ด้วย"]}, {"unit": 83, "section": "Pronouns and determiners", "title": "a friend of mine, my own..., on my own/by myself", "pattern": "a friend of mine (double possessive)  ·  my own + noun  ·  on my own / by myself = alone", "sections": [{"label": "A", "explain": "เราพูด '(a friend) of mine/yours/his/hers/ours/theirs' เพื่อหมายถึง 'หนึ่งในเพื่อนของฉัน' และในทำนองเดียวกันใช้ '(a friend) of my sister's / of Tom's' ได้ด้วย", "examples": ["**A friend of mine** is getting married. (not a friend of me)", "We went on holiday with **some friends of ours**.", "It was a good idea **of yours** to go to the cinema.", "That woman is a friend **of my sister's**. (= หนึ่งในเพื่อนของน้องสาวฉัน)"]}, {"label": "B", "explain": "my own / your own / her own ฯลฯ = สิ่งที่เป็นของตัวเองเท่านั้น ไม่ได้แชร์หรือยืมมา ต้องมีคำแสดงความเป็นเจ้าของนำหน้าเสมอ (ห้ามใช้ an own)", "examples": ["I want **my own room**. (not an own room)", "It's **my own fault** that I have no money.", "Why don't you use **your own**? (= your own car)", "I'd like to have **a room of my own**."]}, {"label": "C", "explain": "เรายังใช้ own เพื่อบอกว่า 'ทำเอง' แทนที่จะให้คนอื่นทำให้ และใช้ on my own / by myself ที่แปลว่า 'คนเดียว/ลำพัง' ได้เหมือนกัน", "examples": ["Paul usually cuts **his own hair**. (= เขาตัดเอง)", "I'd like to grow **my own vegetables**.", "I like living **on my own**. or **by myself**.", "Jack was sitting **on his own** in the corner."]}], "notes": [], "mistake": {"wrong": "I have an own car.", "right": "I have my own car.", "note": "own ต้องมีคำแสดงความเป็นเจ้าของ (my/your/his ฯลฯ) นำหน้าเสมอ ไม่ใช้ a/an"}, "tip": "'a friend of mine' ฟังดูเหมือนซ้ำซ้อน (double possessive) แต่เป็นโครงสร้างที่ถูกต้องตามหลักไวยากรณ์ภาษาอังกฤษ ต่างจากภาษาไทยที่พูดตรงๆ ว่า 'เพื่อนของฉันคนหนึ่ง'", "summary": ["a friend of mine/yours/his/hers/ours/theirs = เพื่อนคนหนึ่งของฉัน/คุณ ฯลฯ (ไม่ใช้ a friend of me)", "my own/your own ฯลฯ = สิ่งที่เป็นของตัวเองเท่านั้น ไม่ได้แชร์/ยืมมา (ห้ามใช้ an own)", "on my own/by myself = คนเดียว/ลำพัง ใช้แทนกันได้"]}, {"unit": 84, "section": "Pronouns and determiners", "title": "there... และ it...", "pattern": "there is/was = บอกว่าสิ่งหนึ่งมีอยู่ (ครั้งแรก)  ·  it = สิ่งที่เจาะจงแล้ว/ระยะทาง-เวลา-อากาศ", "sections": [{"label": "A", "explain": "เราใช้ there is/was เมื่อพูดถึงสิ่งหนึ่งเป็นครั้งแรกเพื่อบอกว่ามันมีอยู่ ส่วน it ใช้แทนสิ่งที่เจาะจงแล้ว (สถานที่ ข้อเท็จจริง สถานการณ์ที่รู้กันแล้วว่าคืออะไร)", "examples": ["**There's** a new restaurant in Hill Street.", "I'm sorry I'm late.  **There was** a lot of traffic. (not It was)", "We went to the new restaurant.  **It's** very good. (It = the restaurant)", "The house is unoccupied.  **There's** nobody living **there**. (there = ในบ้านนั้น)"]}, {"label": "B", "explain": "there ใช้ร่วมกับกริยาช่วย/passive ได้หลายรูปแบบ: there will be, there must be, there used to be, there is bound to be, there is supposed to be", "examples": ["If people drove more carefully, **there wouldn't be** so many accidents.", "**There must have been** somebody at home.", "**There used to be** a cinema here, but it closed a few years ago."]}, {"label": "C", "explain": "เราใช้ it ขึ้นต้นประโยคในโครงสร้าง It's + adjective + to..., และใช้ it พูดถึงระยะทาง เวลา และสภาพอากาศ", "examples": ["**It's dangerous** to walk in the road. (not To walk in the road is dangerous)", "**It's a shame** (that) you can't come to the party.", "How far **is it** from here to the airport?", "**It was windy.** but **There was a cold wind.**"]}], "notes": [], "mistake": {"wrong": "It was a lot of traffic.", "right": "There was a lot of traffic.", "note": "บอกว่าสิ่งหนึ่ง 'มีอยู่' เป็นครั้งแรกต้องใช้ there ไม่ใช่ it"}, "tip": "ใช้ there เมื่อ 'บอกว่ามีอะไรอยู่' (introduce existence) และใช้ it เมื่อ 'พูดถึงสิ่งที่ระบุแล้ว' หรือพูดถึงระยะทาง เวลา สภาพอากาศ", "summary": ["there is/was ใช้บอกว่าสิ่งหนึ่งมีอยู่เป็นครั้งแรก", "it ใช้แทนสิ่งที่เจาะจงแล้ว (ที่พูดถึงไปแล้ว) หรือข้อเท็จจริง/สถานการณ์", "it ใช้พูดถึงระยะทาง เวลา สภาพอากาศ และในโครงสร้าง It's + adjective + to..."]}, {"unit": 85, "section": "Pronouns and determiners", "title": "some และ any", "pattern": "some (ประโยคบอกเล่า/เสนอของ) ·  any (ประโยคปฏิเสธ/คำถามทั่วไป/อันไหนก็ได้)", "sections": [{"label": "A", "explain": "โดยทั่วไปเราใช้ some (รวมถึง somebody/someone/something) ในประโยคบอกเล่า และใช้ any (รวมถึง anybody/anyone/anything) ในประโยคปฏิเสธ", "examples": ["We bought **some flowers**.  We didn't buy **any flowers**.", "There's **somebody** at the door.  There isn't **anybody** at the door.", "She went out without **any money**. (ความหมายปฏิเสธ)", "It's a very easy exam.  **Hardly anybody** fails."]}, {"label": "B", "explain": "ในประโยคคำถามใช้ได้ทั้ง some และ any: ใช้ some เมื่อขอ/เสนอของ หรือคาดว่ามีอยู่แล้ว, ใช้ any เมื่อไม่รู้ว่ามีหรือไม่", "examples": ["Can I have **some sugar**, please? (คิดว่ามีอยู่)", "Would you like **something** to eat?", "Do you have **any luggage**? (ไม่รู้ว่ามีหรือเปล่า)"]}, {"label": "C", "explain": "เราใช้ any หลัง if หรือในประโยคที่มีความหมายแฝงเงื่อนไข (if)", "examples": ["Let me know if you need **anything**.", "I'm sorry for **any trouble** I've caused. (= if I have caused any trouble)"]}, {"label": "D", "explain": "any ยังใช้ในความหมาย 'อันไหนก็ได้ ไม่สำคัญว่าอันไหน'", "examples": ["You can take **any bus**.  They all go to the centre.", "Come and see me **any time** you want."]}], "notes": ["somebody/someone/anybody/anyone เป็นคำเอกพจน์ แต่เราใช้ they/them/their ตามหลัง: 'Someone has forgotten their umbrella.'"], "mistake": {"wrong": "Do you have some luggage?", "right": "Do you have any luggage?", "note": "ในประโยคคำถามทั่วไปที่ไม่แน่ใจคำตอบ ใช้ any ไม่ใช่ some"}, "tip": "ใช้ some เมื่อ 'คาดว่ามี' หรือ 'เสนอ/ขอของ' ใช้ any เมื่อ 'ไม่รู้ว่ามีหรือไม่' (คำถามทั่วไป) หรือประโยคปฏิเสธ", "summary": ["some ใช้ในประโยคบอกเล่า, any ใช้ในประโยคปฏิเสธ", "ในคำถาม: some เมื่อขอ/เสนอของ หรือคาดว่ามีอยู่, any เมื่อไม่แน่ใจ", "any ยังหมายถึง 'อันไหนก็ได้ไม่สำคัญ' ได้ด้วย; somebody/anybody เป็นเอกพจน์แต่ตามด้วย they/them/their"]}, {"unit": 86, "section": "Pronouns and determiners", "title": "no/none/any, nothing/nobody", "pattern": "no + noun = not a/not any  ·  none (ไม่มีคำนาม)  ·  nothing/nobody = not...anything/anybody", "sections": [{"label": "A", "explain": "เราใช้ no + noun ซึ่งมีความหมายเท่ากับ not a หรือ not any และใช้ none โดยไม่มีคำนามตามหลัง (หรือใช้ none of + พหูพจน์)", "examples": ["We had to walk home.  **There was no bus**. (= There wasn't a bus.)", "'How much money do you have?' '**None**.' (= no money)", "**None of it** is mine.", "**None of the students were** happy. (or was — กริยาได้ทั้งเอกพจน์และพหูพจน์)"]}, {"label": "B", "explain": "nothing/nobody(no-one)/nowhere สามารถขึ้นต้นประโยค หรือตอบคำถามแบบลอยๆ ได้ และมีความหมายเท่ากับ not + anything/anybody/anywhere — ห้ามใช้คู่กับกริยาปฏิเสธอีก (double negative)", "examples": ["'What happened?' '**Nothing**.'", "**I said nothing.** = I didn't say anything. (not I didn't say nothing)", "They have **nowhere** to live. (= they don't have anywhere to live)"]}, {"label": "C", "explain": "หลัง nobody/no-one เราใช้ they/them/their ได้เช่นเดียวกับ somebody/anybody", "examples": ["**Nobody** is perfect, are **they**?", "No-one did what I asked **them** to do."]}, {"label": "D", "explain": "no- มีความหมายว่า 'ไม่มีเลย/เป็นไปไม่ได้' ต่างจาก any- ที่หมายถึง 'อันไหนก็ได้ไม่สำคัญ'", "examples": ["There was **no bus**, so we walked home.", "You can take **any bus**. They all go to the centre. (= ไม่สำคัญว่าคันไหน)", "It's a very easy job.  **Anybody** can do it. vs It's a difficult job.  **Nobody** wants to do it."]}], "notes": [], "mistake": {"wrong": "I didn't say nothing.", "right": "I said nothing. / I didn't say anything.", "note": "ห้ามใช้ double negative (didn't + nothing) ในภาษาอังกฤษมาตรฐาน"}, "tip": "no/none/nothing/nobody มีความหมายปฏิเสธในตัวเองแล้ว จึงห้ามใช้คู่กับกริยาปฏิเสธ (isn't/didn't) อีก", "summary": ["no + noun = not a/not any; none ใช้แทนคำนามที่กล่าวถึงแล้ว (หรือ none of + พหูพจน์)", "nothing/nobody/nowhere ใช้แทน not...anything/anybody/anywhere ห้ามใช้ซ้ำกับกริยาปฏิเสธ", "no- = เป็นไปไม่ได้เลย/ไม่มีเลย, any- = อันไหนก็ได้ไม่สำคัญ"]}, {"unit": 87, "section": "Pronouns and determiners", "title": "much, many, little, few, a lot, plenty", "pattern": "much/little + นับไม่ได้  ·  many/few + พหูพจน์  ·  a little/a few (พอมี) vs little/few (แทบไม่มี)", "sections": [{"label": "A", "explain": "เราใช้ much/little กับคำนามนับไม่ได้ และ many/few กับคำนามพหูพจน์นับได้ ส่วน a lot of/lots of/plenty of ใช้ได้กับทั้งสองแบบ; much ไม่ค่อยใช้ในประโยคบอกเล่าปกติ (ยกเว้น too much/so much/as much)", "examples": ["**much luck**, **little energy** (นับไม่ได้)", "**many friends**, **few cars** (พหูพจน์)", "**plenty of time** (= มากกว่าที่ต้องการ)", "We spent **a lot of money**. (not usually We spent much money.)", "We spent **too much money**. (too much ใช้ได้ปกติ)"]}, {"label": "B", "explain": "little = not much (รู้สึกลบ ไม่พอ), few = not many (รู้สึกลบ ไม่พอ) มักใช้คู่กับ very", "examples": ["Gary has **little time** for other things. (= not much)", "Vicky has **few friends** there. (= not many)", "Gary has **very little time**.  Vicky has **very few friends**."]}, {"label": "C", "explain": "a little = some/a small amount (รู้สึกบวก พอมีอยู่), a few = some/a small number (รู้สึกบวก พอมีอยู่) — เราพูด only a little/only a few เสมอ (not only little/only few)", "examples": ["We have **a little time** before the train leaves.", "I have **a few friends** and we meet often.", "Hurry! We only have **a little time**. (not only little time)", "There were only **a few houses**. (not only few houses)"]}], "notes": ["we say 'many years/many weeks/many days' (ไม่ใช้ a lot of years ตามปกติ): 'We've lived here for many years.'"], "mistake": {"wrong": "I know only little English.", "right": "I know only a little English.", "note": "only ต้องคู่กับ a little/a few เสมอ ไม่ใช่ little/few เฉยๆ"}, "tip": "little/few (ไม่มี a) ให้ความรู้สึกลบ ('แทบไม่มีเลย') ส่วน a little/a few (มี a) ให้ความรู้สึกบวก ('มีอยู่บ้างนะ พอใช้ได้')", "summary": ["much/little ใช้กับนับไม่ได้, many/few ใช้กับพหูพจน์นับได้, a lot of/plenty of ใช้ได้กับทั้งคู่", "much ไม่ค่อยใช้ในประโยคบอกเล่าปกติ (ยกเว้น too much/so much/as much)", "little/few (ไม่พอ, รู้สึกลบ) ต่างจาก a little/a few (พอมีอยู่บ้าง, รู้สึกบวก)"]}, {"unit": 88, "section": "Pronouns and determiners", "title": "all/all of, most/most of, no/none of", "pattern": "quantifier + noun (ทั่วไป)  ·  quantifier + of + the/my/this... (เจาะจง)  ·  + of + it/us/you/them (บังคับมี of)", "sections": [{"label": "A", "explain": "เราใช้ all/some/any/most/much/many/(a) little/(a) few/no + คำนามได้โดยตรง (ไม่มี of) เมื่อพูดถึงคำนามทั่วไป", "examples": ["**All cars** have wheels.", "**Many people** drive too fast.", "I go away **most weekends**.", "I feel really tired.  I've got **no energy**.", "ห้ามพูด **all of cars**, **some of people**"]}, {"label": "B", "explain": "เมื่อคำนามที่ตามมาถูกทำให้เจาะจงแล้วด้วย the/my/this/these/that ฯลฯ เราต้องใส่ of ก่อนคำนามนั้น (all และ half ไม่จำเป็นต้องมี of)", "examples": ["**Some of the people** I work with are very strange.", "**None of this money** is mine.", "I spent **most of the day** in bed.", "**All my friends** live near here. or **All of my friends** …"]}, {"label": "C", "explain": "เมื่อตามด้วยสรรพนาม (it/us/you/them) เราต้องมี of เสมอ ไม่มีข้อยกเว้น", "examples": ["**All of us** were late. (not all us)", "I've only read **half of it**. (not half it)", "Do **any of you** want to come to a party tonight?"]}, {"label": "D", "explain": "เราสามารถใช้ some/most/none ฯลฯ เดี่ยวๆ โดยไม่มีคำนามตามหลังก็ได้ ถ้าบริบทชัดเจนอยู่แล้ว", "examples": ["Some cars have four doors and **some** have two.", "A few of the shops were open, but **most (of them)** were closed."]}], "notes": [], "mistake": {"wrong": "Some of people learn more easily.", "right": "Some people learn more easily.", "note": "ห้ามใช้ of ตามหลัง quantifier เมื่อคำนามที่ตามมาเป็นคำนามทั่วไป (ไม่มี the/my/this นำหน้า)"}, "tip": "กฎสำคัญ: มี of เมื่อคำนามที่ตามมาถูกทำให้เจาะจงแล้วด้วย the/my/this/these/that หรือเป็นสรรพนาม (it/us/you/them); ไม่มี of เมื่อพูดถึงคำนามทั่วไป", "summary": ["quantifier + noun ตรงๆ (ไม่มี of) เมื่อพูดถึงคำนามทั่วไป: all cars, some people", "quantifier + of + the/my/this/these ฯลฯ เมื่อพูดถึงกลุ่มที่เจาะจง: some of the people", "ต้องมี of เสมอก่อน it/us/you/them: all of us, none of it"]}, {"unit": 89, "section": "Pronouns and determiners", "title": "both/both of, neither/neither of, either/either of", "pattern": "both/neither/either (สองสิ่ง)  ·  both of/neither of/either of + the/us/them", "sections": [{"label": "A", "explain": "เราใช้ both/neither/either สำหรับ 'สองสิ่ง' เท่านั้น ใช้ได้ทั้งกับคำนามตามหลังหรือใช้เดี่ยวๆ", "examples": ["**Both restaurants** are good. (not the both restaurants)", "**Neither restaurant** is expensive.", "We can go to **either restaurant**. (= อันไหนก็ได้ ไม่สำคัญ)", "'Tea or coffee?' '**Either**. I don't mind.'", "'British or American?' '**Neither**. She's Australian.'"]}, {"label": "B", "explain": "เราใช้ both of/neither of/either of + the/these/my ฯลฯ หรือ + us/you/them (ต้องมี of ก่อนสรรพนามเสมอ แต่ both ไม่จำเป็นต้องมี of ก่อนคำนามที่เจาะจง)", "examples": ["**Both of these restaurants** are good. or **Both these restaurants** are good.", "**Neither of the restaurants** we went to was expensive.", "**Both of us** were tired. (not Both us)", "**Neither of them is/are** at home. (กริยาเอกพจน์หรือพหูพจน์ได้)"]}, {"label": "C", "explain": "เราใช้ both...and..., neither...nor..., either...or... เพื่อเชื่อมสองสิ่ง/สองประโยคเข้าด้วยกัน", "examples": ["**Both Chris and Paul** were late.", "**Neither Chris nor Paul** came to the party.", "She's **either Spanish or Italian**."]}, {"label": "D", "explain": "both/neither/either ใช้กับสองสิ่งเท่านั้น หากมีมากกว่าสองสิ่งต้องเปลี่ยนไปใช้ all/none/any แทน", "examples": ["We tried two hotels.  **Neither of them** had a room.", "We tried a lot of hotels.  **None of them** had a room.", "We tried two hotels.  **Both of them** were full. vs We tried a lot of hotels.  **All of them** were full."]}], "notes": [], "mistake": {"wrong": "The both restaurants are good.", "right": "Both restaurants are good. / Both of the restaurants are good.", "note": "ห้ามใช้ 'the' นำหน้า both โดยตรง (the both restaurants ผิด)"}, "tip": "both/neither/either ใช้ได้กับ 'สองสิ่ง' เท่านั้น ถ้ามากกว่าสองสิ่งต้องเปลี่ยนไปใช้ all/none/any แทน", "summary": ["both/neither/either ใช้กับสองสิ่งเท่านั้น (ต่างจาก all/none/any ที่ใช้กับมากกว่าสอง)", "both of/neither of/either of + the/my/this ฯลฯ หรือ + us/you/them (ต้องมี of ก่อนสรรพนาม)", "both...and..., neither...nor..., either...or... ใช้เชื่อมสองสิ่ง/สองประโยค"]}, {"unit": 90, "section": "Pronouns and determiners", "title": "all, every, whole", "pattern": "everybody/everyone/everything (ใช้แทน all เดี่ยวๆ)  ·  whole (ทั้งหมด/สมบูรณ์ + นามเอกพจน์)", "sections": [{"label": "A", "explain": "เราใช้ everybody/everyone/everything แทนการใช้ all เดี่ยวๆ (all ไม่ค่อยใช้ลอยๆ แบบนี้) ส่วน all ใช้ในรูป all+noun, all of+us/you/them, we/you/they all, all about..., หรือ all=สิ่งเดียวที่", "examples": ["**Everybody** was happy. (not all were happy)", "He thinks he knows **everything**. (not knows all)", "**All my friends** were happy.  **All of us** were happy.  We were **all** happy.", "**All I've eaten today** is a banana. (= สิ่งเดียวที่กินวันนี้)"]}, {"label": "B", "explain": "whole = ทั้งหมด/สมบูรณ์ ใช้กับคำนามนับได้เอกพจน์เท่านั้น (ต้องมี the/my/a นำหน้า) ไม่ใช้กับคำนามนับไม่ได้ (ให้ใช้ all แทน)", "examples": ["Did you read **the whole book**? (= ทั้งเล่ม ไม่ใช่แค่บางส่วน)", "I ate **a whole packet** of biscuits.", "Did you spend **all the money** I gave you? (not the whole money)", "I read **all the information** carefully. (not the whole information)"]}, {"label": "C", "explain": "every day (ความถี่: ทุกๆ วัน) ต่างจาก all day/the whole day (ตลอดทั้งวันตั้งแต่ต้นจนจบ); all the time (=ตลอดเวลา) ต่างจาก every time (=ทุกครั้งที่)", "examples": ["We went to the beach **every day**. (ความถี่)", "We spent **all day** on the beach. or **the whole day**.", "They are at home **all the time**. (= เสมอ)", "**Every time** I see you, you look different. (= ทุกครั้งที่)"]}, {"label": "D", "explain": "every/everybody/everyone/everything เป็นคำเอกพจน์ (ใช้กริยาเอกพจน์) แต่เราใช้ they/them/their ตามหลัง", "examples": ["**Every seat** in the theatre **was** taken.", "**Everybody has** arrived. (not have)", "Everybody said **they** enjoyed **themselves**."]}], "notes": ["เราพูด all day (not all the day), all week (not all the week)"], "mistake": {"wrong": "I spent the whole money.", "right": "I spent all the money.", "note": "whole ไม่ใช้กับคำนามนับไม่ได้ (money, water, information) ให้ใช้ all แทน"}, "tip": "whole ต้องมีคำนำหน้า (the/my/a) เสมอ และใช้กับนามนับได้เอกพจน์เท่านั้น ต่างจาก all ที่ใช้ได้กว้างกว่า", "summary": ["everybody/everyone/everything ใช้แทน all ในการพูดถึงคน/สิ่งของทั้งหมดแบบไม่มีคำนามตามหลัง", "whole = ทั้งหมด/สมบูรณ์ ใช้กับนามนับได้เอกพจน์เท่านั้น (the whole book) ไม่ใช้กับนามนับไม่ได้", "every day (ความถี่) ต่างจาก all day/the whole day (ตลอดทั้งวัน); every/everybody เป็นเอกพจน์แต่ตามด้วย they/their"]}, {"unit": 91, "section": "Pronouns and determiners", "title": "each และ every", "pattern": "each = มองแยกทีละอัน  ·  every = มองรวมเป็นกลุ่ม (คล้าย all)", "sections": [{"label": "A", "explain": "each ใช้เมื่อมองสิ่งต่างๆ แยกกันทีละอัน (มักใช้กับจำนวนน้อย และใช้ได้กับสองสิ่ง) ส่วน every ใช้เมื่อมองสิ่งต่างๆ รวมเป็นกลุ่มทั้งหมด (ความหมายคล้าย all มักใช้กับจำนวนมาก ไม่ใช้กับสองสิ่ง)", "examples": ["**Each book** was a different colour. (มองทีละเล่ม)", "**Every window** in the house was open. (มองรวมทั้งหมด)", "In football, **each team** has eleven players. (not every team — ใช้กับสองฝ่ายได้)", "Kate has read **every book** in the library. (= all the books)"]}, {"label": "B", "explain": "เราใช้ every (ไม่ใช่ each) เพื่อบอกว่าสิ่งหนึ่งเกิดขึ้นบ่อยแค่ไหน และเราพูด each of + the/these/them ส่วน every ต้องมี 'one' แทรกก่อน of เสมอ (every one of, ไม่ใช่ every of)", "examples": ["'How often?' '**Every day**.' (not Each day)", "There's a bus **every ten minutes**. (not each ten minutes)", "**Each of the books** was a different colour. (not each of books)", "I've read **every one of those books**. (not every of those books)"]}, {"label": "C", "explain": "เราใช้ each กลางประโยคได้ และใช้ในสำนวนบอกราคาต่อหน่วย (X pounds each)", "examples": ["The students were **each** given a book. (= Each student was given a book.)", "These oranges are 40 pence **each**. (= ราคาผลละ 40 เพนนี)"]}, {"label": "D", "explain": "everyone (คำเดียว) ใช้กับคนเท่านั้น (= everybody) ส่วน every one (สองคำ) ใช้ได้ทั้งคนและสิ่งของ", "examples": ["**Everyone** enjoyed the party. (= Everybody …)", "Sarah is invited to lots of parties and she goes to **every one**. (= every party)"]}], "notes": [], "mistake": {"wrong": "I've read every of these books.", "right": "I've read every one of these books.", "note": "ต้องมี 'one' แทรกก่อน of เสมอ (every one of, ไม่ใช่ every of)"}, "tip": "each มองทีละหน่วยแยกกัน คล้ายการชี้นิ้วไปทีละอัน ส่วน every มองเป็นภาพรวมทั้งกลุ่ม คล้ายกับ all — ถ้าพูดถึงความถี่ (ทุกๆ...) ต้องใช้ every เท่านั้น", "summary": ["each = มองแต่ละอันแยกกัน (ใช้ได้กับสองสิ่งขึ้นไป), every = มองรวมเป็นกลุ่ม (ใช้กับจำนวนมาก ไม่ใช้กับสองสิ่ง)", "ใช้ every (ไม่ใช่ each) บอกความถี่ (every day, every ten minutes)", "each of + the/these/them, every one of + the/these/them (ต้องมี 'one'); everyone (คน) ต่างจาก every one (คน/สิ่งของ)"]}, {"unit": 92, "section": "Relative clauses", "title": "Relative clause 1: who/that/which", "pattern": "who (คน)  ·  that/which (สิ่งของ)  ·  what = the thing(s) that", "sections": [{"label": "A", "explain": "เราใช้ who ในอนุประโยคขยายความสำหรับคน (ไม่ใช้กับสิ่งของ) และใช้ that ได้ทั้งกับคนและสิ่งของ ส่วน which ใช้กับสิ่งของเท่านั้น", "examples": ["The woman **who** lives next door to me is a doctor.", "I don't like people **who** complain all the time.", "An architect is someone **who** designs buildings.", "The woman **that** lives next door to me is a doctor. (that ใช้กับคนได้)", "I don't like stories **that** have unhappy endings. (or which)"]}, {"label": "B", "explain": "ในอนุประโยคขยายความ เราใช้ who/that/which แทนคำนามที่กล่าวถึง ห้ามใส่ he/she/they/it ซ้ำอีกครั้ง", "examples": ["I met a Canadian woman **who** is an English teacher. (not ...woman. She is...)", "Where are the keys **that** were on the table? (not the keys they were)"]}, {"label": "C", "explain": "what มีความหมายในตัวเองว่า 'สิ่งที่' (= the thing(s) that) จึงต่างจาก that ที่ต้องตามหลังคำนามที่มีอยู่แล้ว", "examples": ["**What** happened was my fault. (= the thing that happened)", "**Everything that** happened was my fault. (not Everything what happened)", "The machine **that** broke down is working again now. (not The machine what broke down)"]}], "notes": [], "mistake": {"wrong": "I don't like stories who have unhappy endings.", "right": "I don't like stories that have unhappy endings.", "note": "ใช้ who กับคนเท่านั้น สิ่งของต้องใช้ that/which"}, "tip": "what ไม่ใช่ relative pronoun แบบเดียวกับ that/which/who — what มีความหมายในตัวเองแล้วว่า 'สิ่งที่' จึงห้ามใช้ what ตามหลังคำนามที่มีอยู่แล้ว (the machine what... ผิด)", "summary": ["who ใช้กับคน, that/which ใช้กับสิ่งของ (that ใช้ได้กับคนด้วยในบางกรณี)", "ห้ามใช้ he/she/they/it ซ้ำกับ who/that/which ในประโยคเดียวกัน", "what = the thing(s) that (มีความหมายในตัวเอง ไม่ใช้ตามหลังคำนาม)"]}, {"unit": 93, "section": "Relative clauses", "title": "Relative clause 2: มีและไม่มี who/that/which", "pattern": "who/that/which เป็นประธาน (ต้องมีเสมอ)  ·  เป็นกรรม (ละได้)  ·  บุพบทวางท้ายอนุประโยค", "sections": [{"label": "A", "explain": "เมื่อ who/that/which ทำหน้าที่เป็นประธาน (subject) ของอนุประโยค เราต้องใช้เสมอ ห้ามละทิ้ง", "examples": ["The woman **who** lives next door to me is a doctor. (who = ประธาน)", "Where are the keys **that** were on the table? (that = ประธาน)"]}, {"label": "B", "explain": "เมื่อ who/that/which ทำหน้าที่เป็นกรรม (object) ของอนุประโยค เราสามารถละทิ้งได้ (แต่ห้ามใส่สรรพนามซ้ำท้ายประโยค)", "examples": ["The woman **(who)** I wanted to see was away on holiday.", "Did you find the keys **(that)** you lost?", "**The dress Lisa bought** doesn't fit her very well. (ละ that ได้)", "**the keys you lost** (not the keys you lost them)"]}, {"label": "C", "explain": "เมื่ออนุประโยคมีบุพบท (to/in/for ฯลฯ) เรามักวางบุพบทไว้ท้ายอนุประโยคตามปกติ (ไม่ใช่หน้า who/that) และห้ามใส่สรรพนามซ้ำท้ายประโยค", "examples": ["Do you know the woman Tom is **talking to**? (or the woman who/that Tom is talking to)", "The bed I **slept in** wasn't comfortable.", "The man I was sitting **next to** on the plane talked all the time.", "**the books you were looking for** (not the books you were looking for them)"]}, {"label": "D", "explain": "เราใช้ that (หรือละได้) แทน what เมื่อมีคำนามนำหน้าอยู่แล้ว (ทบทวนจาก Unit 92)", "examples": ["Everything **(that)** they said was true. (not Everything what they said)", "**What** they said was true. (= The things that they said)"]}], "notes": [], "mistake": {"wrong": "The man I was sitting next to him talked all the time.", "right": "The man I was sitting next to talked all the time.", "note": "ห้ามใส่สรรพนาม (him/it/them) ซ้ำท้ายประโยคหลังตัดกรรมออกไปแล้ว"}, "tip": "ตรวจสอบว่า who/that/which ทำหน้าที่เป็นประธาน (subject) หรือกรรม (object) ของอนุประโยค — ถ้าเป็นประธานต้องมีเสมอ ถ้าเป็นกรรมสามารถละได้", "summary": ["ต้องใช้ who/that/which เสมอเมื่อเป็นประธานของอนุประโยค", "สามารถละ who/that/which ได้เมื่อเป็นกรรมของอนุประโยค", "เมื่อมีบุพบท ให้วางไว้ท้ายอนุประโยคตามปกติ และห้ามใส่สรรพนามซ้ำท้ายประโยค"]}, {"unit": 94, "section": "Relative clauses", "title": "Relative clause 3: whose/whom/where", "pattern": "whose (แสดงความเป็นเจ้าของ)  ·  whom (รูปทางการของ who ที่เป็นกรรม)  ·  where (สถานที่)", "sections": [{"label": "A", "explain": "เราใช้ whose ส่วนใหญ่กับคน เพื่อแสดงความเป็นเจ้าของที่ฝังอยู่ในอนุประโยค (แทน his/her/their) ห้ามสับสนกับ who's (= who is/who has)", "examples": ["We helped some people **whose** car had broken down. (= their car had broken down)", "A widow is a woman **whose** husband is dead.", "I met a man **who** knows you. (he knows you) vs I met a man **whose** sister knows you. (his sister knows you)", "I have a friend **who's** learning Arabic. (who's = who is — ไม่ใช่ whose)"]}, {"label": "B", "explain": "whom เป็นรูปทางการของ who ที่ใช้เมื่อเป็นกรรมของกริยา มักใช้คู่กับบุพบทนำหน้า (to whom, with whom) แต่ในภาษาพูดทั่วไปนิยมใช้ who/that หรือละไปเลยมากกว่า", "examples": ["George is a person **whom** I admire very much. (I admire him)", "It's important to have friends **with whom** you can relax.", "**friends you can relax with** (ภาษาพูดทั่วไป, ไม่ใช้ whom)"]}, {"label": "C", "explain": "เราใช้ where ในอนุประโยคขยายความเพื่อพูดถึงสถานที่", "examples": ["I recently went back to the town **where** I grew up.", "The restaurant **where** we had lunch was near the airport.", "I would like to live in a place **where** there is plenty of sunshine."]}, {"label": "D", "explain": "เราพูด 'the day/the year/the last time/the reason' + (that) โดยไม่จำเป็นต้องมี relative pronoun เสมอไป", "examples": ["That's **the day (that)** I'm going away.", "**The last time (that)** I saw her, she looked great.", "**The reason (that/why)** I'm calling you is to ask your advice."]}], "notes": [], "mistake": {"wrong": "I met someone who's brother I went to school with.", "right": "I met someone whose brother I went to school with.", "note": "whose (แสดงความเป็นเจ้าของ) ≠ who's (=who is/who has) ห้ามสับสน"}, "tip": "whose ทำหน้าที่เหมือนคำแสดงความเป็นเจ้าของ (his/her/their) ที่ฝังอยู่ในประโยคขยาย ลองแทนด้วย his/her/their แล้วดูว่าใจความยังตรงไหม", "summary": ["whose = แสดงความเป็นเจ้าของ ใช้กับคนเป็นหลัก (ระวังสับสนกับ who's)", "whom = รูปทางการของ who เมื่อเป็นกรรม มักใช้คู่กับบุพบทนำหน้า (with whom, to whom)", "where = ใช้แทนสถานที่; the day/time/reason (that) ใช้ได้โดยไม่ต้องมี relative pronoun เสมอไป"]}, {"unit": 95, "section": "Relative clauses", "title": "Relative clause 4: ประโยคขยายแบบข้อมูลเสริม (1)", "pattern": "Type 1: บอกว่าคือใคร/อะไร (ไม่มีจุลภาค, ใช้ that ได้, ละได้)  ·  Type 2: ข้อมูลเสริม (มีจุลภาค, ห้ามใช้ that, ห้ามละ)", "sections": [{"label": "A", "explain": "อนุประโยคขยายความมีสองแบบ: Type 1 (identifying) บอกว่ากำลังพูดถึงคน/สิ่งไหน ไม่มีจุลภาคคั่น ส่วน Type 2 (extra information) ให้ข้อมูลเสริมเกี่ยวกับสิ่งที่รู้อยู่แล้วว่าเป็นใคร/อะไร ต้องมีจุลภาคคั่น", "examples": ["The woman **who lives next door to me** is a doctor. (Type 1: บอกว่าคือผู้หญิงคนไหน)", "My brother Ben, **who lives in Hong Kong**, is an architect. (Type 2: ข้อมูลเสริม รู้อยู่แล้วว่าคือใคร)", "We stayed at the Park Hotel, **which a friend of ours recommended**. (Type 2)"]}, {"label": "B", "explain": "ใน Type 1 เราใช้ that ได้ และละ who/which/that ได้เมื่อเป็นกรรม แต่ใน Type 2 ห้ามใช้ that เด็ดขาด และห้ามละ who/which ออก", "examples": ["Do you know anyone **who/that** speaks French? (Type 1, that ใช้ได้)", "John, **who** speaks French and Italian, works as a tour guide. (not that — Type 2 ห้ามใช้ that)", "We stayed at the Park Hotel, **which** a friend of ours recommended. (ห้ามละ which)"]}, {"label": "C", "explain": "whose และ where ใช้ได้ทั้งสองแบบ (Type 1 และ Type 2) โดยไม่เปลี่ยนรูป", "examples": ["We helped some people **whose** car had broken down. (Type 1)", "Lisa, **whose** car had broken down, was in a very bad mood. (Type 2)", "What's the name of the place **where** you went on holiday? (Type 1)", "Kate has just been to Sweden, **where** her daughter lives. (Type 2)"]}], "notes": [], "mistake": {"wrong": "John, that speaks French and Italian, works as a tour guide.", "right": "John, who speaks French and Italian, works as a tour guide.", "note": "ประโยคขยายแบบให้ข้อมูลเสริม (มีจุลภาคคั่น) ห้ามใช้ that ต้องใช้ who/which เท่านั้น"}, "tip": "กฎง่ายๆ: ถ้ามีจุลภาคคั่น (Type 2/extra info) ห้ามใช้ that และห้ามละ who/which ออก ถ้าไม่มีจุลภาค (Type 1) ใช้ that ได้และละได้เมื่อเป็นกรรม", "summary": ["Type 1 (identifying, ไม่มีจุลภาค) บอกว่าคือคน/สิ่งไหน ใช้ that ได้ และละ who/which/that ได้เมื่อเป็นกรรม", "Type 2 (extra info, มีจุลภาค) ให้ข้อมูลเสริมเกี่ยวกับสิ่งที่รู้อยู่แล้ว ห้ามใช้ that และห้ามละ who/which", "whose และ where ใช้ได้ทั้งสองแบบ (มีหรือไม่มีจุลภาคก็ได้)"]}, {"unit": 96, "section": "Relative clauses", "title": "Relative clause 5: ประโยคขยายแบบข้อมูลเสริม (2)", "pattern": "preposition + whom/which (ทางการ)  ·  all of/most of/none of + whom/which  ·  which (ไม่ใช่ what) อ้างถึงทั้งประโยค", "sections": [{"label": "A", "explain": "เราใช้ preposition + whom (คน) และ preposition + which (สิ่งของ) ในภาษาทางการ ส่วนภาษาพูดทั่วไปมักวางบุพบทไว้หลังกริยาในอนุประโยคแทน และไม่ใช้ whom เมื่อบุพบทอยู่ตำแหน่งนั้น", "examples": ["Mr Lee, **to whom** I spoke at the meeting, is interested in our proposal.", "Fortunately we had a good map, **without which** we would have got lost.", "Katherine works for a company called 'Latoma', **which** I'd never heard of before. (บุพบทอยู่ท้าย)", "Mr Lee, **who** I spoke **to** at the meeting... (not whom ... to)"]}, {"label": "B", "explain": "เราใช้ all of/most of/none of/both of ฯลฯ + whom (คน) หรือ + which (สิ่งของ) เพื่อบอกสัดส่วนของกลุ่มที่กล่าวถึง", "examples": ["Helen has three brothers, **all of whom** are married.", "They asked me a lot of questions, **most of which** I couldn't answer.", "Martin tried on three jackets, **none of which** fitted him.", "The house was damaged in a fire, **the cause of which** was never established."]}, {"label": "C", "explain": "เราใช้ which (ไม่ใช่ what) เมื่ออ้างถึงข้อเท็จจริงหรือเหตุการณ์ทั้งหมดของประโยคก่อนหน้า ไม่ได้อ้างถึงคำนามคำใดคำหนึ่ง", "examples": ["Sarah couldn't meet us, **which** was a shame. (not what was a shame)", "The weather was good, **which** we hadn't expected.", "Joe got the job, **which** surprised everybody. (which = the fact that Joe got the job)"]}], "notes": [], "mistake": {"wrong": "Sarah couldn't meet us, what was a shame.", "right": "Sarah couldn't meet us, which was a shame.", "note": "ใช้ which (ไม่ใช่ what) เมื่ออ้างถึงข้อเท็จจริงทั้งประโยคก่อนหน้า"}, "tip": "which ในโครงสร้างนี้ไม่ได้อ้างถึงคำนามคำใดคำหนึ่ง แต่อ้างถึง 'เหตุการณ์/ข้อเท็จจริงทั้งหมด' ของประโยคก่อนหน้า ลองแทนด้วย 'and this' แล้วดูว่าใจความตรงไหม", "summary": ["preposition + whom/which ใช้ในภาษาทางการ; ภาษาพูดมักวางบุพบทไว้ท้ายประโยคและไม่ใช้ whom เมื่อบุพบทอยู่ท้าย", "all of/most of/none of/both of + whom (คน) / which (สิ่งของ) ใช้บอกสัดส่วนของกลุ่มที่กล่าวถึง", "which (ไม่ใช่ what) ใช้อ้างถึงข้อเท็จจริง/เหตุการณ์ทั้งประโยคก่อนหน้า"]}, {"unit": 97, "section": "Relative clauses", "title": "อนุประโยค -ing และ -ed", "pattern": "-ing clause (active, กำลังทำ)  ·  -ed clause (passive, ถูกกระทำ)  ·  there is/was + -ing/-ed", "sections": [{"label": "A", "explain": "เราใช้ -ing clause เพื่อบอกว่าคน/สิ่งของ 'กำลังทำ' อะไรอยู่ (ความหมาย active) ไม่ว่าจะเป็นช่วงเวลาหนึ่งหรือเป็นข้อเท็จจริงถาวรก็ได้", "examples": ["Who is the woman **talking to Tom**? (the woman is talking to Tom)", "Police **investigating the crime** are looking for three men.", "The road **connecting the two villages** is very narrow. (ข้อเท็จจริงถาวร)", "I have a large room **overlooking the garden**."]}, {"label": "B", "explain": "เราใช้ -ed clause (past participle) เพื่อบอกว่าคน/สิ่งของ 'ถูกกระทำ' (ความหมาย passive) รวมถึง past participle ที่ไม่ปกติ (stolen/made/built)", "examples": ["The boy **injured in the accident** was taken to hospital. (he was injured)", "George showed me some pictures **painted by his father**.", "The police never found the money **stolen in the robbery**.", "Most of the goods **made in this factory** are exported."]}, {"label": "C", "explain": "เราสามารถใช้ there is/there was ตามด้วย -ing clause หรือ -ed clause ได้ และคำว่า left ในโครงสร้างนี้หมายถึง 'ยังเหลืออยู่/ยังไม่ถูกใช้'", "examples": ["There were some children **swimming in the river**.", "There was a big red car **parked outside the house**.", "We've eaten nearly all the chocolates.  There are only a few **left**."]}], "notes": [], "mistake": {"wrong": "The boy injuring in the accident was taken to hospital.", "right": "The boy injured in the accident was taken to hospital.", "note": "เมื่อคนหรือสิ่งของ 'ถูกกระทำ' ต้องใช้ -ed clause (passive) ไม่ใช่ -ing (active)"}, "tip": "ถามตัวเองว่าคำนามนั้น 'กำลังทำ' อะไรอยู่ (-ing, active) หรือ 'ถูกกระทำ' (-ed, passive) — the woman talking (เธอพูด) ต่างจาก the boy injured (เขาถูกทำให้บาดเจ็บ)", "summary": ["-ing clause = active, บอกว่ากำลังทำอะไรอยู่ (ชั่วขณะหรือถาวรก็ได้)", "-ed clause = passive, บอกว่าถูกกระทำ (ใช้ past participle รวมถึงรูปไม่ปกติ)", "there is/was + -ing/-ed clause ใช้บอกว่ามีคน/สิ่งของกำลังทำ/ถูกกระทำอะไรอยู่ตรงนั้น"]}, {"unit": 98, "section": "Adjectives and adverbs", "title": "คำคุณศัพท์ลงท้าย -ing และ -ed: boring/bored", "pattern": "-ing = ทำให้เกิดความรู้สึก  ·  -ed = รู้สึกอย่างนั้น", "sections": [{"label": "A", "explain": "-ing adjective บรรยายสิ่งของ/สถานการณ์/คนที่ 'ทำให้เกิดความรู้สึกนั้น' ส่วน -ed adjective บรรยาย 'ความรู้สึกของคน' ที่ได้รับผลกระทบ", "examples": ["Jane's job is **boring**. (งานน่าเบื่อ)", "Jane is **bored** with her job. (เจนรู้สึกเบื่อ)", "Paul always talks about the same things.  He's really **boring**. (ถ้าคนเป็นคนน่าเบื่อ แปลว่าทำให้คนอื่นเบื่อ)"]}, {"label": "B", "explain": "คู่คำ -ing/-ed อื่นๆ ที่ใช้บ่อย ใช้หลักการเดียวกัน", "examples": ["My job is **boring/interesting/tiring/satisfying/depressing**. (-ing = บรรยายงาน)", "I'm **bored/interested/tired/satisfied/depressed**. (-ed = บรรยายความรู้สึก)", "Julia is **interested** in politics. (not interesting in politics)", "The news was **shocking**.  I was **shocked** when I heard the news."]}], "notes": [], "mistake": {"wrong": "I am boring.", "right": "I am bored.", "note": "ต้องแยกให้ออกว่า -ing (ทำให้คนอื่นรู้สึก) กับ -ed (ตัวเองรู้สึก) ผิดกันคนละความหมาย"}, "tip": "จำง่ายๆ ว่า -ing = ทำให้เกิดความรู้สึก (สิ่งของ/สถานการณ์/คนที่น่าเบื่อ), -ed = รู้สึกอย่างนั้น (คนที่ได้รับผลกระทบ)", "summary": ["-ing adjective บรรยายสิ่งของ/สถานการณ์/คนที่ 'ทำให้เกิดความรู้สึกนั้น'", "-ed adjective บรรยาย 'ความรู้สึกของคน' ที่ได้รับผลกระทบ", "ถ้าคนเป็น -ing (เช่น boring) แปลว่าคนคนนั้นทำให้คนอื่นรู้สึกแบบนั้น (น่าเบื่อ)"]}, {"unit": 99, "section": "Adjectives and adverbs", "title": "คำคุณศัพท์: a nice new house, you look tired", "pattern": "opinion + fact (ลำดับคำคุณศัพท์)  ·  adjective หลัง be/look/feel/seem", "sections": [{"label": "A", "explain": "เมื่อใช้คำคุณศัพท์หลายตัวติดกัน คำคุณศัพท์แสดงความคิดเห็น (opinion: nice, beautiful) มักมาก่อนคำคุณศัพท์บอกข้อเท็จจริง (fact: new, large, wooden) และคำคุณศัพท์บอกข้อเท็จจริงหลายตัวเรียงตามลำดับ ขนาด→อายุ→สี→แหล่งกำเนิด→วัสดุ", "examples": ["My brother lives in **a nice new house**. (opinion+fact)", "a **tall young** man (ขนาด→อายุ)", "a **large wooden** table (ขนาด→วัสดุ)", "an **old Russian** song (อายุ→แหล่งกำเนิด)", "a **small black plastic** bag (ขนาด→สี→วัสดุ)", "a **black and white** dress (สีหลายสีใช้ and เชื่อม)"]}, {"label": "B", "explain": "เราใช้คำคุณศัพท์ (ไม่ใช่ adverb) หลัง be/get/become/seem และหลัง look/feel/sound/taste/smell เพื่อบอกลักษณะ", "examples": ["Be careful!  I'm **tired** and I'm getting **hungry**.", "Your friend seems **very nice**.", "You **look tired**. / I **feel tired**. / She **sounds tired**.", "Drive **carefully**! (not Drive careful — เปรียบเทียบกับ adverb)"]}, {"label": "C", "explain": "เราพูด 'the first two days', 'the next few weeks', 'the last ten minutes' โดยเรียงลำดับคำแบบนี้เท่านั้น", "examples": ["I didn't enjoy **the first two days** of the course. (not the two first days)", "They'll be away for **the next few weeks**. (not the few next weeks)"]}], "notes": [], "mistake": {"wrong": "a wooden beautiful table", "right": "a beautiful wooden table", "note": "opinion adjective (beautiful) ต้องมาก่อน fact adjective (wooden) เสมอ"}, "tip": "ลำดับคำคุณศัพท์ข้อเท็จจริงจำง่ายๆ ด้วย 'ขนาด-อายุ-สี-แหล่งกำเนิด-วัสดุ' (size-age-colour-origin-material) ก่อนคำนาม", "summary": ["ลำดับคำคุณศัพท์: ความคิดเห็น (opinion) มาก่อนข้อเท็จจริง (fact); ข้อเท็จจริงเรียงตาม ขนาด→อายุ→สี→แหล่งกำเนิด→วัสดุ", "ใช้คำคุณศัพท์ (ไม่ใช่ adverb) หลัง be/get/become/seem และหลัง look/feel/sound/taste/smell", "the first two days / the next few weeks / the last ten minutes (เรียงลำดับนี้เท่านั้น)"]}, {"unit": 100, "section": "Adjectives and adverbs", "title": "คำคุณศัพท์และกริยาวิเศษณ์ (1): quick/quickly", "pattern": "adjective ขยายคำนาม  ·  adverb ขยายกริยา/adjective อื่น/adverb อื่น/past participle", "sections": [{"label": "A", "explain": "adverb ส่วนใหญ่มาจาก adjective + ly แต่ไม่ใช่ทุกคำที่ลงท้าย -ly จะเป็น adverb เสมอไป (บางคำเป็น adjective)", "examples": ["Our holiday was too short — the time passed very **quickly**.", "Two people were **seriously** injured in the accident.", "It was **a lovely day**. (lovely เป็น adjective ไม่ใช่ adverb แม้จะลงท้าย -ly)", "**friendly/lively/elderly/lonely/lovely** = adjectives ที่ลงท้าย -ly"]}, {"label": "B", "explain": "adjective ใช้ขยายคำนาม (บอกว่าสิ่งนั้นเป็นอย่างไร) ส่วน adverb ใช้ขยายกริยา (บอกว่าทำอย่างไร)", "examples": ["Sam is **a careful driver**. (not a carefully driver)", "Sam drove **carefully** along the narrow road. (not drove careful)", "We didn't go out because of **the heavy rain**.", "We didn't go out because it was raining **heavily**."]}, {"label": "C", "explain": "เราใช้ adverb ขยาย adjective อื่นหรือ adverb อื่นได้ด้วย", "examples": ["**reasonably cheap** (adverb+adjective)", "**terribly sorry** (adverb+adjective)", "**incredibly quickly** (adverb+adverb)", "The exam was **surprisingly easy**."]}, {"label": "D", "explain": "เราใช้ adverb ขยาย past participle (injured/organised/written) ที่ทำหน้าที่เป็นคำคุณศัพท์ด้วย", "examples": ["Two people were **seriously injured** in the accident. (not serious injured)", "The conference was **badly organised**."]}], "notes": [], "mistake": {"wrong": "Sam is a carefully driver.", "right": "Sam is a careful driver.", "note": "ขยายคำนามต้องใช้คำคุณศัพท์ ไม่ใช่ adverb"}, "tip": "ถามตัวเองว่ากำลังขยาย 'คำนาม' (ใช้ adjective) หรือ 'กริยา/คำคุณศัพท์อื่น/adverb อื่น' (ใช้ adverb) — กฎนี้ใช้ได้แม้กระทั่งกับ past participle ที่ทำหน้าที่เป็นคำคุณศัพท์", "summary": ["adverb ส่วนใหญ่มาจาก adjective + ly (คำที่ลงท้าย -ly ไม่ใช่ adverb ทั้งหมด เช่น friendly, lively, lonely)", "adjective ขยายคำนาม, adverb ขยายกริยา (บอกว่าทำอย่างไร)", "adverb ยังใช้ขยายคำคุณศัพท์อื่น adverb อื่น และ past participle ได้ด้วย"]}, {"unit": 101, "section": "Adjectives and adverbs", "title": "คำคุณศัพท์และกริยาวิเศษณ์ (2): well, fast, late, hard/hardly", "pattern": "good(adj)/well(adv)  ·  fast/hard/late (adj=adv รูปเดียวกัน)  ·  hardly = แทบไม่", "sections": [{"label": "A", "explain": "good เป็นคำคุณศัพท์ ส่วน well เป็นกริยาวิเศษณ์ของมัน แต่ well ยังใช้กับ past participle (well-known) และใช้เป็นคำคุณศัพท์แปลว่า 'สุขภาพดี' ได้ด้วย", "examples": ["Your English is **good**. / You speak English **well**.", "Sophie's father is a **well-known** writer.", "'How are you?'  'I'm very **well**, thanks.' (well = สุขภาพดี)"]}, {"label": "B", "explain": "fast/hard/late เป็นได้ทั้งคำคุณศัพท์และกริยาวิเศษณ์ในรูปเดียวกัน (ไม่เติม -ly) ส่วน lately เป็นคำละคำที่แปลว่า 'เมื่อเร็วๆ นี้'", "examples": ["Darren is **a fast runner**. / Darren can run **fast**.", "It's **hard** to find a job. / Kate **works hard**. (not works hardly)", "Sorry I'm **late**. / I got up **late**.", "**lately** = recently: Have you seen Kate lately?"]}, {"label": "C", "explain": "hardly ไม่ใช่ adverb ของ hard แต่มีความหมายว่า 'น้อยมาก/แทบไม่' และวางไว้หน้ากริยาเสมอ; 'can hardly do' = แทบเป็นไปไม่ได้", "examples": ["Sarah **hardly spoke** to me. (= พูดน้อยมาก)", "We **hardly know** each other. (not We know each other hardly)", "My leg was hurting.  I **could hardly walk**. (= แทบเดินไม่ได้เลย)"]}, {"label": "D", "explain": "hardly ใช้คู่กับ any/anybody/anyone/anything/anywhere และ hardly ever = แทบไม่เคยเลย; hardly ยังแปลว่า 'แน่นอนว่าไม่' ได้ด้วย", "examples": ["'How much money do we have?'  '**Hardly any**.' (=แทบไม่มีเลย)", "The exam results were bad.  **Hardly anybody** in our class passed.", "I'm nearly always at home.  I **hardly ever** go out.", "It's **hardly surprising** that you're tired. (= แน่นอนว่าไม่แปลกใจเลย)"]}], "notes": [], "mistake": {"wrong": "Kate works hardly.", "right": "Kate works hard.", "note": "hard (adverb) = ทำงานหนัก ต่างจาก hardly = แทบไม่ (ความหมายตรงข้ามกันโดยสิ้นเชิง)"}, "tip": "hard กับ hardly ไม่ใช่คำเดียวกันที่ผันรูป -ly ธรรมดา แต่มีความหมายตรงข้ามกันโดยสิ้นเชิง ต้องจำแยกเป็นคำคนละคำ", "summary": ["good (adjective) / well (adverb); well ยังใช้เป็น adjective แปลว่าสุขภาพดี และใช้กับ past participle (well-known)", "fast/hard/late เป็นได้ทั้ง adjective และ adverb รูปเดียวกัน (lately ≠ late ในความหมาย)", "hardly = แทบไม่/น้อยมาก (ไม่ใช่ adverb ของ hard) ใช้กับ any/anybody/anything/ever ได้; hardly ยังแปลว่า 'แน่นอนว่าไม่' ได้ด้วย"]}, {"unit": 102, "section": "Adjectives and adverbs", "title": "so และ such", "pattern": "so + adjective/adverb  ·  such (a) + noun  ·  so...that / such...that", "sections": [{"label": "A", "explain": "เราใช้ so ตามด้วยคำคุณศัพท์หรือกริยาวิเศษณ์ (ไม่มีคำนาม) และใช้ such ตามด้วยคำนาม (หรือ such + adjective + noun); เราพูด 'such a' ไม่ใช่ 'a such'", "examples": ["The story was **so stupid**.", "Everything happened **so quickly**.", "It was **such a stupid story**. (not a so stupid story)", "They are **such nice people**. (not so nice people)", "I've had a busy day.  I'm **so tired**."]}, {"label": "B", "explain": "เราใช้ so...that และ such...that เพื่อบอกผลลัพธ์ที่ตามมา โดยมักละ that ได้", "examples": ["I was **so tired that** I fell asleep. = I was so tired I fell asleep.", "We had **such a good time** that we didn't want to leave.", "It was **such nice weather that** we spent the whole day on the beach."]}, {"label": "C", "explain": "so และ such ยังใช้ในความหมาย 'ขนาดนี้/แบบนี้' ได้ด้วย รวมถึงสำนวน no such (= สิ่งนี้ไม่มีอยู่จริง)", "examples": ["I don't usually get up **so early**.", "I didn't realise it was **such an old house**.", "There's **no such word**. (= คำนี้ไม่มีอยู่จริง)"]}, {"label": "D", "explain": "สำนวนเฉพาะ: so long/so far/so much/so many ใช้ so ตรงๆ แต่ 'a long time', 'a long way', 'a lot (of)' เป็นคำนาม จึงต้องใช้ such a", "examples": ["I haven't seen her for **so long**.", "I haven't seen her for **such a long time**. (not so long time)", "I'm sorry I'm late — there was **so much traffic**.", "there was **such a lot of traffic**."]}], "notes": [], "mistake": {"wrong": "I haven't seen her for so long time.", "right": "I haven't seen her for such a long time.", "note": "'long time' เป็นคำนาม (time) จึงต้องใช้ such a ไม่ใช่ so"}, "tip": "ตรวจสอบว่าคำที่ตามมาเป็นคำคุณศัพท์/คำวิเศษณ์ล้วนๆ (ใช้ so) หรือมีคำนามตามมาด้วย (ใช้ such/such a)", "summary": ["so + adjective/adverb (ไม่มีคำนาม), such (a) + noun หรือ such (a) + adjective + noun", "so...that / such...that ใช้บอกผลลัพธ์ (มักละ that ได้)", "so/such ยังหมายถึง 'ขนาดนี้/แบบนี้' ได้ (so early, such an old house); ระวังสำนวน such a long time/such a lot of ที่ใช้ such ไม่ใช่ so"]}, {"unit": 103, "section": "Adjectives and adverbs", "title": "enough และ too", "pattern": "enough หลัง adjective/adverb, หน้า noun  ·  too (มากเกินไป) vs not...enough (น้อยเกินไป)", "sections": [{"label": "A", "explain": "enough วางหลังคำคุณศัพท์และกริยาวิเศษณ์ แต่วางหน้าคำนามตามปกติ และสามารถใช้เดี่ยวๆ ได้โดยไม่มีคำนาม/คำคุณศัพท์ตามหลัง", "examples": ["I'm not **fit enough**. (not enough fit)", "We've waited **long enough**.", "We have **enough money**.  We don't need any more.", "We don't need more money.  We have **enough**."]}, {"label": "B", "explain": "too = มากเกินความจำเป็น ส่วน not...enough = น้อยกว่าที่จำเป็น (ความหมายตรงข้ามกัน)", "examples": ["You never stop working.  You work **too hard**. (= มากกว่าที่จำเป็น)", "You're lazy.  You don't work **hard enough**. (= น้อยกว่าที่จำเป็น)", "There's **too much furniture** in this room.  There's **not enough space**."]}, {"label": "C", "explain": "เราใช้ enough/too + for + somebody/something และ enough/too + to + verb เพื่อบอกจุดประสงค์หรือผลลัพธ์", "examples": ["Does Joe have **enough experience for the job**?", "That shirt is **too small for you**.", "Does Joe have **enough experience to do the job**?", "She's not **old enough to have** a driving licence.", "The bridge is **just wide enough for two cars to pass** one another."]}, {"label": "D", "explain": "ในโครงสร้าง too...to / enough...to ห้ามใส่กรรม (it/them) ซ้ำท้ายประโยค เพราะกรรมนั้นถูกอ้างถึงไปแล้วในส่วนต้นของประโยค", "examples": ["The food was **too hot to eat**. (not too hot to eat it)", "These boxes are **too heavy to carry**. (not to carry them)", "This chair isn't **strong enough to stand on**. (not to stand on it)"]}], "notes": [], "mistake": {"wrong": "The food was too hot to eat it.", "right": "The food was too hot to eat.", "note": "ห้ามใส่กรรม (it/them) ซ้ำท้ายประโยคหลังโครงสร้าง too...to/enough...to"}, "tip": "enough วางหลัง adjective/adverb แต่วางหน้าคำนาม (ตรงข้ามกัน) — จำโดยเทียบ 'fit enough' (หลัง) กับ 'enough money' (หน้า)", "summary": ["enough วางหลัง adjective/adverb แต่วางหน้าคำนาม", "too = มากเกินไป (บวก), not...enough = น้อยเกินไป (ตรงข้าม)", "enough/too + for + somebody + to do something; ห้ามใส่กรรมซ้ำท้ายประโยคหลัง too...to/enough...to"]}, {"unit": 104, "section": "Adjectives and adverbs", "title": "quite, pretty, rather, fairly", "pattern": "quite/pretty = ค่อนข้าง  ·  rather (มักลบ)  ·  fairly (อ่อนกว่า)  ·  quite = อย่างสมบูรณ์ (กับบางคำ)", "sections": [{"label": "A", "explain": "quite และ pretty มีความหมายใกล้เคียงกัน (=น้อยกว่า very แต่มากกว่า a little) โดย quite ต้องวางหน้า a/an เสมอ ส่วน pretty เป็นคำไม่ทางการ", "examples": ["She's **quite famous**. / She's **pretty famous**.", "We live in **quite an old house**. (not a quite old house)", "It was **quite a surprise**.", "There were **quite a lot of** guests.", "I **quite like** tennis, but it's not my favourite sport."]}, {"label": "B", "explain": "rather มักใช้กับความคิดที่เป็นลบ (ไม่ดี) แต่ถ้าใช้กับความคิดที่เป็นบวก จะมีความหมายว่า 'น่าประหลาดใจ/ผิดคาด'", "examples": ["The weather isn't so good.  It's **rather cloudy**.", "Paul is **rather shy**.  He doesn't talk very much.", "These oranges are **rather good**.  Where did you get them? (= น่าประหลาดใจที่ดี)"]}, {"label": "C", "explain": "fairly มีความหมายอ่อนกว่า quite/rather/pretty คือถ้าอะไรเป็น fairly good แปลว่ายังไม่ค่อยดีนัก และยังดีขึ้นได้อีก", "examples": ["My room is **fairly big**, but I'd prefer a bigger one.", "We see each other **fairly often**, but not as often as we used to."]}, {"label": "D", "explain": "quite ยังหมายถึง 'อย่างสมบูรณ์' (completely) ได้กับคำคุณศัพท์บางกลุ่ม เช่น sure/right/true/clear/different/certain/wrong/safe/obvious", "examples": ["'Are you sure?'  'Yes, **quite sure**.' (= completely sure)", "She was **quite different** from what I expected. (= completely different)", "I **quite agree** with you. (= completely agree)", "**not quite** = ไม่สมบูรณ์: 'Are you ready?'  'Not quite.'"]}], "notes": [], "mistake": {"wrong": "a quite old house", "right": "quite an old house", "note": "quite ต้องวางหน้า a/an เสมอ (quite a/an + adjective + noun)"}, "tip": "quite มีสองความหมาย: 'ค่อนข้าง' (น้อยกว่า very) กับ 'อย่างสมบูรณ์' (completely) — ต้องดูจากคำคุณศัพท์ที่ตามมาว่าเป็นคำที่วัดระดับได้ (interesting) หรือเป็นคำที่ 'แน่นอน/สมบูรณ์แบบ' อยู่แล้ว (sure, true, right)", "summary": ["quite/pretty = ค่อนข้าง (น้อยกว่า very มากกว่า a little); quite ต้องอยู่หน้า a/an", "rather มักใช้กับความหมายลบ แต่ถ้าใช้กับความหมายบวกจะแปลว่า 'น่าประหลาดใจ'", "fairly อ่อนกว่า quite/rather/pretty; quite ยังแปลว่า 'อย่างสมบูรณ์' ได้กับคำบางกลุ่ม (sure/right/true/different ฯลฯ)"]}, {"unit": 105, "section": "Adjectives and adverbs", "title": "Comparative 1: cheaper, more expensive", "pattern": "-er (คำสั้น)  ·  more... (คำยาว/adverb -ly)  ·  irregular: better/worse/further", "sections": [{"label": "A", "explain": "เราสร้าง comparative ด้วย -er หรือ more... และมักตามด้วย than เพื่อเปรียบเทียบ", "examples": ["It's **cheaper** to drive **than** go by train.", "Going by train is **more expensive than** driving."]}, {"label": "B", "explain": "เราใช้ -er กับคำพยางค์เดียว และคำสองพยางค์ที่ลงท้าย -y (เปลี่ยนเป็น -ier) ส่วน more... ใช้กับคำยาวตั้งแต่สองพยางค์ขึ้นไป และ adverb ที่ลงท้าย -ly เสมอ", "examples": ["cheap→**cheaper**, fast→**faster**, large→**larger**", "lucky→**luckier**, easy→**easier**", "**more serious**, **more expensive**, **more comfortable**", "**more slowly**, **more seriously**, **more easily**", "บางคำสองพยางค์ (clever/narrow/quiet/shallow/simple) ใช้ได้ทั้งสองแบบ: **quieter** หรือ **more quiet**"]}, {"label": "C", "explain": "คำคุณศัพท์/กริยาวิเศษณ์บางคำมีรูป comparative ไม่ปกติ", "examples": ["The garden looks **better** since you tidied it up. (good/well→better)", "He did very badly — **worse than** expected. (bad/badly→worse)", "It's a long walk — **further than** I thought. (far→further/farther)", "Let me know if you hear any **further** news. (further ยังแปลว่า 'เพิ่มเติม')"]}], "notes": [], "mistake": {"wrong": "This exam is more easy than the last one.", "right": "This exam is easier than the last one.", "note": "easy เป็นคำสองพยางค์ลงท้าย -y จึงใช้ -er (easier) ไม่ใช่ more"}, "tip": "กฎคร่าวๆ: หนึ่งพยางค์ → -er, สองพยางค์ลงท้าย -y → -ier, สองพยางค์ขึ้นไปอื่นๆ → more, adverb ลงท้าย -ly → more เสมอ", "summary": ["comparative ใช้ -er (คำสั้น) หรือ more (คำยาว/adverb ลงท้าย -ly) + than", "คำสองพยางค์บางคำ (clever, narrow, quiet, shallow, simple) ใช้ได้ทั้งสองแบบ", "good/well→better, bad/badly→worse, far→further/farther (further ยังแปลว่า 'เพิ่มเติม' ได้)"]}, {"unit": 106, "section": "Adjectives and adverbs", "title": "Comparative 2: much better / any better", "pattern": "much/a lot/a bit + comparative  ·  any/no + comparative  ·  the...the...  ·  elder vs older", "sections": [{"label": "A", "explain": "เราใช้ much/a lot/far/a bit/a little/slightly หน้า comparative เพื่อบอกระดับความต่างมากหรือน้อย", "examples": ["I felt ill earlier, but I feel **much better** now. (or a lot better)", "Don't go by train.  It's **a lot more expensive**.", "Could you speak **a bit more slowly**?", "The problem is **far more serious** than we thought."]}, {"label": "B", "explain": "เราใช้ any/no + comparative ในประโยคปฏิเสธ/คำถามเพื่อบอกว่า 'ไม่แม้แต่นิดเดียว'", "examples": ["I've waited long enough.  I'm not waiting **any longer**.", "We expected their apartment to be big, but it's **no bigger than** ours.", "How do you feel now?  Do you feel **any better**?"]}, {"label": "C", "explain": "เราซ้ำ comparative (better and better) เพื่อบอกว่าสิ่งหนึ่งเปลี่ยนแปลงอย่างต่อเนื่อง", "examples": ["Your English is improving.  It's getting **better and better**.", "**More and more** tourists are visiting this part of the country."]}, {"label": "D", "explain": "เราใช้ the...the... เพื่อบอกว่าสิ่งหนึ่งขึ้นอยู่กับอีกสิ่งหนึ่ง (ยิ่ง...ก็ยิ่ง...)", "examples": ["**The sooner** we leave, **the earlier** we'll arrive.", "**The younger** you are, **the easier** it is to learn.", "**The more** expensive the hotel, **the better** the service."]}, {"label": "E", "explain": "comparative ของ old คือ older เสมอ ส่วน elder ใช้ได้เฉพาะนำหน้าคำนามในครอบครัว (my elder brother) และห้ามใช้ elder ตามหลัง than", "examples": ["David looks **older** than he really is. (not looks elder)", "**My elder sister** is a TV producer. (or my older sister)", "My sister is **older than** me. (not elder than me)"]}], "notes": [], "mistake": {"wrong": "My sister is elder than me.", "right": "My sister is older than me.", "note": "elder ใช้เป็นคำคุณศัพท์นำหน้าคำนามในครอบครัวเท่านั้น (my elder sister) ห้ามใช้ตามหลัง than"}, "tip": "elder ใช้ได้เฉพาะตำแหน่งหน้าคำนามในครอบครัว (my elder brother) ไม่สามารถใช้ตามหลัง than ได้เลยไม่ว่ากรณีใด ต่างจาก older ที่ใช้ได้ทุกที่", "summary": ["much/a lot/far/a bit/a little/slightly + comparative บอกระดับความต่าง", "any/no + comparative ใช้ในประโยคปฏิเสธ/คำถาม เพื่อบอกว่า 'ไม่แม้แต่นิดเดียว'", "ซ้ำ comparative (better and better) = เปลี่ยนแปลงต่อเนื่อง; the...the... = ยิ่ง...ยิ่ง...; elder ใช้หน้าคำนามในครอบครัวเท่านั้น ห้ามตามหลัง than"]}, {"unit": 107, "section": "Adjectives and adverbs", "title": "Comparative 3: as...as / than", "pattern": "not as...as (น้อยกว่า)  ·  as...as (เท่ากัน, ใช้ได้ทั้งบวก/ลบ/คำถาม)  ·  the same as", "sections": [{"label": "A", "explain": "เราใช้ not as...as (หรือ not so...as) เพื่อบอกว่าสิ่งหนึ่งน้อยกว่าอีกสิ่งหนึ่ง และ less than มีความหมายใกล้เคียงกัน", "examples": ["Jack isn't **as old as** he looks. (= เขาดูแก่กว่าที่เป็นจริง)", "I don't know **as many people as** you do.", "It's **not as cold** as yesterday. (or not so cold as)", "I spent **less money than** you. (= I didn't spend as much money as you)"]}, {"label": "B", "explain": "เราใช้ as...as (ไม่ใช้ so...as) ในประโยคบอกเล่าเชิงบวกและคำถามด้วย เพื่อบอกว่าเท่ากัน และใช้ twice/three times as...as บอกสัดส่วน", "examples": ["I'm sorry I'm late.  I got here **as fast as** I could.", "You can have **as much as** you want.", "Petrol is **twice as expensive as** it was a few years ago.", "Their house is about **three times as big as** ours."]}, {"label": "C", "explain": "เราพูด 'the same as' (ไม่ใช่ 'the same like')", "examples": ["Laura's salary is **the same as** mine.", "David is **the same age as** James.", "She still looks **the same as** she did ten years ago."]}, {"label": "D", "explain": "หลัง than เราใช้ได้ทั้งสรรพนามกรรม (than me) และประธาน+กริยา (than I am) ทั้งสองแบบถูกต้อง", "examples": ["You're **taller than me**.  or You're **taller than I am**.", "He's not **as clever as her**.  or **as she is**.", "They have **more money than us**.  or **than we have**."]}], "notes": [], "mistake": {"wrong": "Laura's salary is the same like mine.", "right": "Laura's salary is the same as mine.", "note": "ใช้ 'the same as' เสมอ ไม่ใช่ 'the same like'"}, "tip": "as...as ใช้ได้ทั้งประโยคบวกและลบ (แต่ not so...as ใช้เฉพาะประโยคลบเท่านั้น) — จำไว้ว่า so...as เป็นทางเลือกของ not as...as ในประโยคปฏิเสธเท่านั้น", "summary": ["not as...as (หรือ not so...as) = น้อยกว่า; less than คล้ายความหมายเดียวกัน", "as...as ใช้ได้ในประโยคบวก/คำถามด้วย (เท่ากับ); twice/three times as...as บอกสัดส่วน", "the same as (ไม่ใช่ the same like); than me/than I am ใช้ได้ทั้งคู่"]}, {"unit": 108, "section": "Adjectives and adverbs", "title": "Superlative: the longest / the most enjoyable", "pattern": "-est (คำสั้น)  ·  most... (คำยาว)  ·  the + superlative + in/of  ·  present perfect + superlative", "sections": [{"label": "A", "explain": "เราสร้าง superlative ด้วย -est (คำสั้น) หรือ most... (คำยาว) ตามกฎเดียวกับ comparative และมีรูปไม่ปกติบางคำ", "examples": ["What is **the longest** river in the world?", "Yesterday was **the hottest** day of the year.", "It's one of **the most famous** museums in the world.", "good→**best**, bad→**worst**, far→**furthest/farthest**"]}, {"label": "B", "explain": "เราใช้ the (หรือ my/your ฯลฯ) นำหน้า superlative เสมอ และเปรียบเทียบ superlative กับ comparative ได้", "examples": ["This hotel is **the cheapest** in town. (superlative)", "It's **cheaper than** all the others in town. (comparative)", "How old is **your youngest** child?"]}, {"label": "C", "explain": "superlative ของ old คือ oldest เสมอ ส่วน eldest ใช้ได้เฉพาะกับคนในครอบครัวเท่านั้น (เหมือน elder ใน Unit 106)", "examples": ["That church is **the oldest** building in town. (not the eldest)", "Their **eldest son** is 13 years old. (or their oldest son)"]}, {"label": "D", "explain": "หลัง superlative เราใช้ in กับสถานที่และกลุ่มคน/องค์กร แต่ใช้ of กับช่วงเวลา", "examples": ["What's the longest river **in** the world? (not of the world)", "Who is the youngest student **in** the class? (not of the class)", "Yesterday was the hottest day **of** the year.", "What was the happiest day **of** your life?"]}, {"label": "E", "explain": "เรามักใช้ present perfect ตามหลัง superlative เพื่อพูดถึงประสบการณ์ที่ผ่านมาทั้งหมด", "examples": ["What's the most important decision **you've ever made**?", "That was the best holiday **I've had** for a long time."]}], "notes": [], "mistake": {"wrong": "What's the longest river of the world?", "right": "What's the longest river in the world?", "note": "ใช้ in กับสถานที่/กลุ่มคน (not of); ใช้ of กับช่วงเวลา (of the year, of my life)"}, "tip": "ใช้ in กับสถานที่และกลุ่มคน/องค์กร (in the world, in the class, in the company) แต่ใช้ of กับช่วงเวลา (of the year, of my life)", "summary": ["superlative ใช้ -est (คำสั้น) หรือ most (คำยาว) พร้อม the นำหน้าเสมอ", "superlative + in (สถานที่/กลุ่มคน) หรือ + of (ช่วงเวลา); eldest ใช้เฉพาะกับคนในครอบครัวเท่านั้น (เหมือน elder)", "มักใช้ present perfect ตามหลัง superlative (the best... I've ever had)"]}, {"unit": 109, "section": "Adjectives and adverbs", "title": "ลำดับคำในประโยค (1): กริยา+กรรม, สถานที่และเวลา", "pattern": "verb + object (ติดกันเสมอ)  ·  verb + object + place  ·  place ก่อน time", "sections": [{"label": "A", "explain": "กริยาและกรรมของประโยคต้องอยู่ติดกันเสมอ เราไม่แทรกคำอื่น (เช่น very much, fluently, also) คั่นกลางระหว่างกริยากับกรรม", "examples": ["I **like my job** very much. (not I like very much my job)", "Our guide **spoke English** fluently. (not spoke fluently English)", "I lost all my money and I **also lost my passport**. (not lost also my passport)", "At the end of this street you'll **see a supermarket** on your left."]}, {"label": "B", "explain": "ถ้ากริยามีกรรม ลำดับปกติคือ กริยา+กรรม+สถานที่ (place)", "examples": ["We **took the children to the zoo**. (not took to the zoo the children)", "Don't **put anything on the table**.", "Did you **learn English at school**?"]}, {"label": "C", "explain": "เวลา (when?/how often?/how long?) มักอยู่หลังสถานที่ตามลำดับ กริยา+กรรม+สถานที่+เวลา แต่บางครั้งสามารถย้ายไปต้นประโยคได้", "examples": ["Ben **walks to work every morning**. (not every morning to work)", "They've **lived in the same house for a long time**.", "**On Monday** I'm going to Paris.", "**After the party** Sarah gave me a lift home."]}], "notes": [], "mistake": {"wrong": "I like very much my job.", "right": "I like my job very much.", "note": "ห้ามแทรกคำวิเศษณ์คั่นระหว่างกริยากับกรรมเด็ดขาด"}, "tip": "จำลำดับ SVOPT (Subject-Verb-Object-Place-Time) เป็นโครงร่างพื้นฐานของประโยคภาษาอังกฤษ", "summary": ["กริยาและกรรมต้องอยู่ติดกันเสมอ ห้ามแทรกคำอื่นคั่นกลาง", "ลำดับปกติ: กริยา+กรรม+สถานที่", "เวลามักอยู่หลังสถานที่ (SVOPT) แต่สามารถย้ายไปต้นประโยคได้"]}, {"unit": 110, "section": "Adjectives and adverbs", "title": "ลำดับคำในประโยค (2): กริยาวิเศษณ์กับกริยา (always/also/probably)", "pattern": "adverb หน้ากริยาคำเดียว (แต่หลัง be-verb)  ·  adverb หลัง auxiliary ตัวแรก (กริยาหลายคำ)", "sections": [{"label": "A", "explain": "เมื่อกริยาเป็นคำเดียว adverb (always/also/probably ฯลฯ) วางไว้หน้ากริยา แต่ถ้ากริยาคือ am/is/are/was/were adverb จะวางไว้หลังกริยานั้นแทน", "examples": ["Emily **always drives** to work.", "I **cleaned** the house and **also cooked** the dinner. (not cooked also)", "Laura **hardly ever watches** television.", "We were feeling tired and we **were also hungry**. (not also were)", "You're **always late**."]}, {"label": "B", "explain": "เมื่อกริยามีตัวช่วย (auxiliary) ตั้งแต่สองคำขึ้นไป adverb จะวางไว้หลังกริยาช่วยตัวแรกเสมอ และ probably มักวางไว้หน้าคำปฏิเสธ", "examples": ["I **can never remember** her name.", "The meeting **will probably be** cancelled.", "Jack can't cook.  He **can't even boil** an egg.", "I **probably won't** see you. (not I won't probably)"]}, {"label": "C", "explain": "เราใช้ all และ both ในตำแหน่งเดียวกับ adverb กลางประโยค (หลังกริยาช่วยตัวแรก หรือหน้ากริยาคำเดียว)", "examples": ["We **all felt** ill after the meal. (not felt all ill)", "My parents **are both** teachers.", "Sarah and Jane **have both applied** for the job."]}, {"label": "D", "explain": "เมื่อใช้ is/will/did ฯลฯ แทนการพูดซ้ำส่วนหนึ่งของประโยค (ทบทวนจาก Unit 51) เราวาง always/never ฯลฯ ไว้หน้ากริยานั้น", "examples": ["He **always says** he won't be late, but he **always is**. (= he is always late)", "I've **never done** it and I **never will**. (= I will never do it)"]}], "notes": [], "mistake": {"wrong": "I have always to phone him.", "right": "I always have to phone him.", "note": "always/usually/also ต้องวางหน้า have to เสมอ"}, "tip": "กฎหลัก: ถ้ากริยาเป็นคำเดียว adverb อยู่หน้ากริยา (ยกเว้น be-verb ที่ adverb อยู่หลัง); ถ้ากริยามีตัวช่วย adverb อยู่หลังตัวช่วยตัวแรก", "summary": ["กริยาคำเดียว: adverb อยู่หน้ากริยา (ยกเว้น am/is/are/was/were ที่ adverb อยู่หลัง)", "กริยาหลายคำ (มี auxiliary): adverb อยู่หลังกริยาช่วยตัวแรก; probably อยู่หน้าคำปฏิเสธเสมอ", "all/both วางตำแหน่งเดียวกับ adverb (กลางประโยค)"]}, {"unit": 111, "section": "Adjectives and adverbs", "title": "still, any more, yet, already", "pattern": "still (ยังคงเดิม)  ·  not...any more/no longer (เปลี่ยนไปแล้ว)  ·  already (เร็วกว่าคาด)  ·  yet (จนถึงตอนนี้)", "sections": [{"label": "A", "explain": "เราใช้ still เพื่อบอกว่าสถานการณ์หรือการกระทำยังคงดำเนินต่อไป ไม่เปลี่ยนแปลง (มักอยู่กลางประโยคกับกริยา) และ still ยังหมายถึง 'ถึงกระนั้นก็ตาม' ได้ด้วย", "examples": ["It's ten o'clock and Joe is **still** in bed.", "Do you **still** want to go away?", "He has everything he needs, but he's **still** unhappy. (= ถึงกระนั้นก็ตาม)"]}, {"label": "B", "explain": "เราใช้ not...any more หรือ not...any longer (ท้ายประโยค) เพื่อบอกว่าสถานการณ์เปลี่ยนไปแล้ว หรือใช้ no longer (กลางประโยค) แทนได้ — ห้ามใช้ 'no more' ในความหมายนี้", "examples": ["Lucy doesn't work here **any more**. (or any longer)", "We used to be good friends, but we aren't **any more**.", "Lucy **no longer** works here. (กลางประโยค)", "We are **no longer** friends. (not we are no more friends)"]}, {"label": "C", "explain": "เราใช้ already เพื่อบอกว่าบางสิ่งเกิดขึ้นเร็วกว่าที่คาดไว้ (มักอยู่กลางประโยคหรือท้ายประโยค)", "examples": ["'What time is Sue leaving?'  'She has **already** left.' (= เร็วกว่าที่คาด)", "I've just had lunch and I'm **already** hungry.", "She's **already** left.  or She's left **already**."]}, {"label": "D", "explain": "เราใช้ yet ส่วนใหญ่ในประโยคปฏิเสธและคำถาม (ท้ายประโยค) เพื่อบอกว่า 'จนถึงตอนนี้' และแสดงว่าผู้พูดคาดว่าสิ่งนั้นจะเกิดขึ้น; still...not แสดงความประหลาดใจ/หงุดหงิดมากกว่า", "examples": ["It's 10 o'clock and Joe isn't here **yet**.", "Have you decided what to do **yet**?", "Mike lost his job and is **still** unemployed. vs Mike hasn't found another job **yet**.", "I sent him an invitation weeks ago and he **still hasn't replied**. (= ควรจะตอบมาแล้ว)"]}], "notes": [], "mistake": {"wrong": "We are no more friends.", "right": "We are no longer friends. / We aren't friends any more.", "note": "'no more' ไม่ใช้ในความหมายนี้ ให้ใช้ 'no longer' หรือ 'not...any more' แทน"}, "tip": "still บอกว่า 'เหมือนเดิม ยังต่อเนื่องอยู่', any more/no longer บอกว่า 'เปลี่ยนไปแล้ว', yet ใช้ถามหรือปฏิเสธสิ่งที่คาดว่าจะเกิดขึ้น, already บอกว่า 'เร็วกว่าที่คาด'", "summary": ["still = ยังคงดำเนินอยู่ (ไม่เปลี่ยน) อยู่กลางประโยค", "not...any more/any longer (ท้ายประโยค) หรือ no longer (กลางประโยค) = เปลี่ยนไปแล้ว (ไม่ใช่ no more)", "already = เร็วกว่าที่คาดไว้; yet = จนถึงตอนนี้ (ใช้ในประโยคปฏิเสธ/คำถามท้ายประโยค)"]}, {"unit": 112, "section": "Adjectives and adverbs", "title": "even", "pattern": "even (เน้นสิ่งที่ไม่ปกติ)  ·  even + comparative  ·  even though/even when/even if + ประธาน+กริยา", "sections": [{"label": "A", "explain": "เราใช้ even เพื่อบอกว่าสิ่งหนึ่งไม่ปกติหรือน่าประหลาดใจ วางตำแหน่งเดียวกับ adverb กลางประโยค และใช้กับประโยคปฏิเสธได้ (not even, can't even)", "examples": ["She has a television in every room, **even** the bathroom.", "Laura has travelled everywhere.  She's **even been** to the Antarctic.", "I can't cook.  I **can't even boil** an egg.", "They **didn't even say** hello."]}, {"label": "B", "explain": "เราใช้ even + comparative เพื่อบอกว่ายิ่งไปกว่านั้นอีก", "examples": ["I got up very early, but Jack got up **even earlier**.", "I knew I didn't have much money, but I have **even less** than I thought.", "We were **even more surprised** when she came to see us."]}, {"label": "C", "explain": "เราใช้ even though/even when/even if ตามด้วยประธาน+กริยาเต็มรูป ห้ามใช้ even เดี่ยวๆ ตามด้วยประธาน+กริยาโดยตรง", "examples": ["**Even though** Tina can't drive, she has a car. (not even she can't drive)", "He never shouts, **even when** he's angry.", "It's dangerous to swim here, **even if** you're a strong swimmer.", "We're going to the beach tomorrow.  We're going **even if** the weather is bad."]}], "notes": [], "mistake": {"wrong": "Even she can't drive, she has a car.", "right": "Even though she can't drive, she has a car.", "note": "ห้ามใช้ even เดี่ยวๆ ตามด้วยประธาน+กริยาโดยตรง ต้องใช้ even though/even when/even if"}, "tip": "even (คำเดียว) ใช้เน้นคำ/วลีในประโยค ส่วน even though/even when/even if (สามคำ) ใช้นำหน้าอนุประโยคที่มีประธาน+กริยาเต็มรูป", "summary": ["even ใช้เน้นสิ่งที่ไม่ปกติ/น่าประหลาดใจ วางตำแหน่งเดียวกับ adverb กลางประโยค ใช้กับ negative ได้ (not even, can't even)", "even + comparative บอกว่ายิ่งไปกว่านั้นอีก (even earlier, even more)", "even though/even when/even if + ประธาน+กริยา (ห้ามใช้ even เดี่ยวๆ แทน)"]}, {"unit": 113, "section": "Conjunctions and prepositions", "title": "although, though, even though, in spite of, despite", "pattern": "although/though/even though + ประธาน+กริยา  ·  in spite of/despite + noun/-ing", "sections": [{"label": "A", "explain": "although ตามด้วยประธาน+กริยาเต็มรูปเสมอ ใช้บอกความขัดแย้งระหว่างสองสิ่ง (แปลว่า 'แม้ว่า')", "examples": ["**Although** it rained a lot, they had a good time. (= It rained a lot, but they...)", "I didn't apply for the job **although** I had the necessary qualifications.", "We went out **although** it was raining heavily. (เทียบกับ because ที่บอกเหตุผล)"]}, {"label": "B", "explain": "in spite of และ despite ตามด้วยคำนาม สรรพนาม (this/that/what) หรือ -ing เท่านั้น ไม่ใช่ประโยคเต็ม", "examples": ["**In spite of** the rain, we had a good time.", "She wasn't well, but **despite this** she continued working. (not despite of this)", "I didn't apply for the job **despite having** the necessary qualifications.", "I didn't apply **in spite of the fact (that)** I had the qualifications."]}, {"label": "C", "explain": "เปรียบเทียบโครงสร้าง: although + ประโยคเต็ม ในขณะที่ in spite of/despite + คำนาม/-ing เท่านั้น ห้ามสลับโครงสร้างกัน", "examples": ["**Although** the traffic was bad, we arrived on time.", "**In spite of** the traffic, we arrived on time. (not in spite of the traffic was bad)", "I couldn't sleep **although** I was very tired.", "I couldn't sleep **despite being** very tired. (not despite I was tired)"]}, {"label": "D", "explain": "though มีความหมายเหมือน although และในภาษาพูดมักใช้ท้ายประโยค (=but); even though เน้นย้ำมากกว่า although ธรรมดา", "examples": ["I didn't apply for the job **though** I had the necessary qualifications.", "The house isn't so nice.  I like the garden **though**. (= but I like the garden)", "**Even though** I was really tired, I couldn't sleep. (not even I was really tired)"]}], "notes": [], "mistake": {"wrong": "Despite of the rain, we had a good time.", "right": "Despite the rain, we had a good time. / In spite of the rain, we had a good time.", "note": "despite ไม่มี of ต่างจาก in spite of ที่มี of"}, "tip": "although ตามด้วยประโยคเต็ม (subject+verb) เสมอ ส่วน in spite of/despite ตามด้วยคำนามหรือ -ing เท่านั้น ห้ามสลับโครงสร้าง", "summary": ["although/though/even though + subject + verb (แปลว่า 'แม้ว่า')", "in spite of + noun/pronoun/-ing (despite เหมือนกันแต่ไม่มี of)", "though ใช้ท้ายประโยคในภาษาพูดได้ (=but); even though เน้นย้ำมากกว่า although ธรรมดา"]}, {"unit": 114, "section": "Conjunctions and prepositions", "title": "in case", "pattern": "in case + present tense (บอกเหตุผลของการเตรียมล่วงหน้า)", "sections": [{"label": "A", "explain": "in case + ประโยค (มักใช้ present tense) หมายถึง 'เพราะเป็นไปได้ว่าจะเกิดสิ่งนั้น' เราจึงเตรียมการล่วงหน้าไว้ก่อน ห้ามใช้ will หลัง in case", "examples": ["I'd better write down my password **in case I forget** it.", "Your car should have a spare wheel **in case you have** a puncture.", "I'll write down my password **in case I forget** it. (not in case I will forget)", "I don't think it will rain, but I'll take an umbrella **just in case**."]}, {"label": "B", "explain": "in case ต่างจาก if: in case บอกว่าทำสิ่งหนึ่งไว้ล่วงหน้าไม่ว่าอีกเหตุการณ์จะเกิดหรือไม่ ส่วน if บอกว่าทำก็ต่อเมื่อเหตุการณ์นั้นเกิดขึ้นจริง", "examples": ["We'll buy some more food **in case** Tom comes. (= ซื้อไว้ก่อนไม่ว่าเขาจะมาหรือไม่)", "We'll buy some more food **if** Tom comes. (= ซื้อก็ต่อเมื่อเขามาเท่านั้น)", "You should insure your bike **in case** it is stolen.", "You should inform the police **if** your bike is stolen."]}, {"label": "C", "explain": "เราใช้ in case + past เพื่ออธิบายเหตุผลของการกระทำในอดีต", "examples": ["I gave him my phone number **in case he needed** to contact me.", "I drew a map for Sarah **in case she had** a problem finding our house.", "We rang the doorbell again **in case they hadn't heard** it the first time."]}, {"label": "D", "explain": "in case of (+ noun) = if there is... มักใช้ในประกาศหรือคำแนะนำ", "examples": ["**In case of fire**, please leave the building as quickly as possible.", "**In case of emergency**, call this number."]}], "notes": [], "mistake": {"wrong": "I'll take an umbrella in case it will rain.", "right": "I'll take an umbrella in case it rains.", "note": "ห้ามใช้ will หลัง in case ให้ใช้ present tense แทนแม้จะพูดถึงอนาคต"}, "tip": "in case ≠ if — in case บอกเหตุผลว่าทำไมทำสิ่งหนึ่ง 'ล่วงหน้า' (ก่อนที่อีกเหตุการณ์จะเกิด) ในขณะที่ if บอกเงื่อนไขว่าจะทำสิ่งหนึ่ง 'ก็ต่อเมื่อ' อีกเหตุการณ์เกิดขึ้นก่อน", "summary": ["in case + present tense = เพราะเป็นไปได้ว่าจะเกิดสิ่งนั้น (ทำล่วงหน้าไว้ก่อน) ห้ามใช้ will", "in case ต่างจาก if: in case ทำล่วงหน้าไม่ว่าจะเกิดหรือไม่, if ทำก็ต่อเมื่อเกิดขึ้นจริง", "in case + past ใช้อธิบายเหตุผลของการกระทำในอดีต; in case of = if there is (ใช้ในประกาศ/คำแนะนำ)"]}, {"unit": 115, "section": "Conjunctions and prepositions", "title": "unless, as long as, provided/providing", "pattern": "unless = except if  ·  as long as/provided/providing = if, on condition that", "sections": [{"label": "A", "explain": "unless มีความหมายเท่ากับ 'except if' หรือ 'if...not' ใช้บอกว่าสิ่งหนึ่งจะไม่เกิดขึ้น ยกเว้นมีเงื่อนไขหนึ่งเกิดขึ้น", "examples": ["You can't go in **unless** you are a member. (= except if you are a member)", "I'll see you tomorrow **unless** I have to work late.", "'Shall I tell Lisa?'  'Not **unless** she asks you.'", "**Unless we leave now**, we'll be late. = **If we don't leave now**, we'll be late."]}, {"label": "B", "explain": "as long as/so long as และ provided (that)/providing (that) มีความหมายเท่ากับ 'if, on condition that' ใช้บอกเงื่อนไขที่ต้องเป็นจริง", "examples": ["You can borrow my car **as long as** you promise not to drive too fast.", "Travelling by car is convenient **provided (that)** you have somewhere to park.", "**Providing (that)** the room is clean, I don't mind which hotel we stay at."]}, {"label": "C", "explain": "เมื่อพูดถึงอนาคต เราไม่ใช้ will หลัง unless/as long as/so long as/provided/providing ใช้ present tense แทน", "examples": ["I'm not going out **unless it stops** raining. (not unless it will stop)", "**Providing the weather is good**, we're going to have a picnic tomorrow. (not providing the weather will be good)"]}], "notes": [], "mistake": {"wrong": "I'll go unless it will rain.", "right": "I'll go unless it rains.", "note": "ห้ามใช้ will หลัง unless/as long as/provided/providing แม้จะพูดถึงอนาคต ใช้ present tense แทน"}, "tip": "unless เทียบเท่ากับ 'if...not' — ลองแทนที่ unless ด้วย 'if...not' แล้วดูว่าความหมายตรงกันไหม เพื่อตรวจสอบว่าใช้ unless ถูกบริบทหรือไม่", "summary": ["unless = except if (เทียบเท่า if...not)", "as long as/so long as/provided (that)/providing (that) = if, on condition that (เงื่อนไขที่ต้องมี)", "เมื่อพูดถึงอนาคต ห้ามใช้ will หลัง unless/as long as/provided/providing ใช้ present tense แทน"]}, {"unit": 116, "section": "Conjunctions and prepositions", "title": "as (= at the same time as / because)", "pattern": "as = เกิดพร้อมกัน (subject+verb)  ·  as = because", "sections": [{"label": "A", "explain": "เราใช้ as เมื่อสองเหตุการณ์เกิดขึ้นพร้อมกันในเวลาเดียวกัน ไม่ว่าจะเป็นช่วงสั้นๆ หรือช่วงเวลานานก็ตาม", "examples": ["We all waved goodbye to Liz **as she drove away**.", "**As I walked along the street**, I looked in the shop windows.", "Kate slipped **as she was getting off** the bus.", "**Just as I sat down**, the doorbell rang. (=exactly at that moment)", "**As the day went on**, the weather got worse. (ช่วงเวลานาน)"]}, {"label": "B", "explain": "as (=พร้อมกัน) ใช้ได้เฉพาะเมื่อสองเหตุการณ์เกิดขึ้นพร้อมกันจริงๆ ถ้าเหตุการณ์หนึ่งเกิดขึ้น 'หลังจาก' อีกเหตุการณ์ ให้ใช้ when แทน", "examples": ["**When I got home**, I had something to eat. (not as I got home — เกิดหลังจากถึงบ้าน ไม่ใช่พร้อมกัน)", "David lost his passport **when he was on holiday**. (= during the time he was away)"]}, {"label": "C", "explain": "as ยังหมายถึง 'because' (บอกเหตุผล) ได้ด้วย และสามารถใช้ since แทนได้ในความหมายนี้", "examples": ["**As I was hungry**, I decided to find somewhere to eat.", "**As it's late** and we're tired, let's get a taxi home.", "David wasn't in the office **as he was on holiday**. (= because he was on holiday)", "**Since it's late** and we're tired, let's get a taxi home."]}], "notes": [], "mistake": {"wrong": "Julia got married as she was 22.", "right": "Julia got married when she was 22.", "note": "ใช้ when (ไม่ใช่ as) เมื่อเหตุการณ์หนึ่งเกิดขึ้น 'ในช่วงเวลาที่' อีกเหตุการณ์เป็นจริง (ไม่ใช่สองเหตุการณ์เกิดขึ้นพร้อมกันจริงๆ)"}, "tip": "as (=พร้อมกัน) ใช้ได้เฉพาะเมื่อสองเหตุการณ์เกิดขึ้นพร้อมกันจริงๆ ไม่ใช่แค่ 'ในช่วงเวลาเดียวกัน' แบบกว้างๆ — ถ้าไม่แน่ใจให้ใช้ when แทนจะปลอดภัยกว่า", "summary": ["as = เกิดขึ้นพร้อมกันในเวลาเดียวกัน (ต่างจาก when ที่ใช้เมื่อเหตุการณ์หนึ่งเกิดหลังอีกเหตุการณ์)", "as = because (บอกเหตุผล) ก็ใช้ได้ (since ก็ใช้แทนได้)", "as ต่างจาก when: as ต้องเป็นสองเหตุการณ์ที่เกิดพร้อมกันจริงๆ"]}, {"unit": 117, "section": "Conjunctions and prepositions", "title": "like และ as", "pattern": "like (preposition) = คล้ายกับ  ·  as + subject+verb = ในแบบเดียวกับ  ·  as (preposition) = ในฐานะที่เป็น", "sections": [{"label": "A", "explain": "like เป็นบุพบท แปลว่า 'คล้ายกับ/เหมือนกับ' ตามด้วยคำนาม สรรพนาม หรือ -ing และยังใช้ในความหมาย 'ตัวอย่างเช่น' ได้ (=such as)", "examples": ["What a beautiful house!  It's **like a palace**. (not as a palace)", "It's raining again.  I hate weather **like this**. (not as this)", "'What's that noise?'  'It sounds **like a baby crying**.'", "I enjoy water sports, **like** surfing, scuba diving... (= such as)"]}, {"label": "B", "explain": "as (+ subject + verb) แปลว่า 'ในแบบเดียวกับที่.../ในสภาพเดียวกับที่...' เราใช้ as usual/as always และ 'the same as' (ไม่ใช่ the same like)", "examples": ["I left everything **as it was**.", "You should have done it **as I showed you**. (or like I showed you)", "You should have done it **like this**. (not as this)", "You're late **as usual**.  As always, Nick was the first to complain.", "Your phone is **the same as** mine. (not the same like)"]}, {"label": "C", "explain": "as (+ subject + verb) ยังใช้ในสำนวน do as you like, as you know, as I said, as she expected ได้ด้วย", "examples": ["You can do **as you like**. (= do what you like)", "**As you know**, it's Emma's birthday next week.", "Andy failed his driving test, **as he expected**.", "**As I said** yesterday, I'm sure we can solve the problem. (or Like I said...)"]}, {"label": "D", "explain": "as ยังเป็นบุพบทได้ (as + noun) แปลว่า 'ในฐานะที่เป็น/ในตำแหน่งของ' ซึ่งมีความหมายต่างจาก like (=คล้ายกับ แต่ไม่ใช่จริงๆ)", "examples": ["**As a taxi driver**, I spend most of my working life in a car. (ฉันเป็นคนขับแท็กซี่จริงๆ)", "I'm **like a taxi driver**. (ฉันไม่ใช่คนขับแท็กซี่ แต่คล้ายๆ)", "Many years ago I worked **as a photographer**. (ฉันเคยเป็นช่างภาพจริงๆ)", "The news came **as a great shock**."]}], "notes": [], "mistake": {"wrong": "I'm as a taxi driver for my family.", "right": "I'm like a taxi driver for my family.", "note": "as (preposition) = จริงๆ เป็นสิ่งนั้น ต่างจาก like = คล้ายกับ แต่ไม่ใช่จริงๆ"}, "tip": "as (preposition) บอกว่า 'เป็นจริงๆ' (in the position of) ส่วน like บอกว่า 'คล้ายกับ แต่ไม่ใช่จริงๆ' — เปรียบเทียบ 'as a taxi driver' (อาชีพจริง) กับ 'like a taxi driver' (ทำตัวคล้ายๆ)", "summary": ["like (preposition) = คล้ายกับ/เหมือนกับ + noun/pronoun/-ing; ยังแปลว่า 'ตัวอย่างเช่น' ได้ (= such as)", "as + subject + verb = ในแบบเดียวกับที่..., ในสภาพเดียวกับที่... (as usual, as I showed you, as you know)", "as (preposition) = ในฐานะที่เป็น.../ในตำแหน่งของ... (บอกว่าเป็นจริงๆ) ต่างจาก like ที่บอกว่าคล้ายแต่ไม่ใช่จริง"]}, {"unit": 118, "section": "Conjunctions and prepositions", "title": "as if / as though / like", "pattern": "look/sound/feel + like/as if/as though + subject+verb  ·  as if + past (unreal present)", "sections": [{"label": "A", "explain": "เราใช้ like หรือ as if (หรือ as though) ตามด้วยประธาน+กริยา เพื่อบอกว่าคน/สิ่งของนั้นดูเหมือน/ฟังดูเหมือน/รู้สึกเหมือนอะไร", "examples": ["That house looks **like it's going to fall down**. or **as if it's going to fall down**.", "Amy sounded **like she had a cold**. or **as if she had a cold**.", "I don't feel **like I've had a holiday**. or **as if I've had a holiday**. or **as though**..."]}, {"label": "B", "explain": "สำนวน it looks like.../it sounds like... เป็นรูปแบบที่ใช้บ่อยมาก", "examples": ["Sarah is very late.  **It looks like she isn't coming**. or **It looks as if she isn't coming**.", "The noise is loud next door.  **It sounds like they're having a party**.", "**It sounds as though** they're having a party."]}, {"label": "C", "explain": "เราใช้ like/as if/as though กับกริยาอื่นๆ ได้ด้วย ไม่จำกัดแค่ look/sound/feel", "examples": ["He ran **like he was running for his life**.", "The speaker went on talking **as if nothing had happened**.", "They looked at me **as though I was mad**."]}, {"label": "D", "explain": "หลัง as if เราบางครั้งใช้ past tense เมื่อพูดถึงปัจจุบันที่ไม่เป็นจริง (unreal) เหมือนกับหลัง wish/if — ไม่ใช้ like ในความหมายนี้ปกติ และสามารถใช้ were แทน was ได้", "examples": ["I don't like him.  He talks **as if he knew** everything. (เขาไม่ได้รู้ทุกอย่างจริงๆ)", "She's always asking me to do things — **as if I didn't have** enough to do already.", "Joe's only 40.  Why do you talk about him **as if he was an old man**?", "Why do you talk about him **as if he were an old man**? (were แทน was ก็ได้)"]}], "notes": [], "mistake": {"wrong": "He talks as if he knows everything.", "right": "He talks as if he knew everything.", "note": "หลัง as if เมื่อพูดถึงสิ่งที่ไม่จริง (unreal) ในปัจจุบัน ให้ใช้ past tense (knew) ไม่ใช่ present tense"}, "tip": "as if + past tense (unreal) ใช้หลักการเดียวกับ if/wish แบบ unreal past — บอกว่าสิ่งนั้นไม่เป็นความจริง ไม่ใช่บอกเวลาที่ผ่านมาแล้ว", "summary": ["like/as if/as though ใช้บอกว่าดูเหมือน/ฟังดูเหมือน/รู้สึกเหมือนอะไร (as though เป็นทางการกว่า like เล็กน้อย)", "it looks like.../it sounds like... เป็นสำนวนที่ใช้บ่อย", "หลัง as if ใช้ past tense เมื่อพูดถึงสิ่งที่ไม่จริงในปัจจุบัน (unreal) เช่นเดียวกับ wish/if; ใช้ were แทน was ได้"]}, {"unit": 119, "section": "Conjunctions and prepositions", "title": "during, for, while", "pattern": "during + noun (เมื่อไร)  ·  for + ระยะเวลา (นานแค่ไหน)  ·  while + subject+verb", "sections": [{"label": "A", "explain": "during + คำนาม ใช้บอกว่าเหตุการณ์หนึ่งเกิดขึ้น 'เมื่อไร' (ในช่วงเวลาระหว่างจุดเริ่มต้นและจุดจบของสิ่งหนึ่ง)", "examples": ["I fell asleep **during the movie**.", "We met really nice people **during our holiday**.", "The ground is wet.  It must have rained **during the night**.", "It's lovely here **during the summer**. (or in the summer)"]}, {"label": "B", "explain": "for (+ ระยะเวลา) ใช้บอกว่าสิ่งหนึ่งดำเนินต่อไป 'นานแค่ไหน' เราไม่ใช้ during เพื่อบอกระยะเวลานานเท่าไร", "examples": ["We watched TV **for two hours** last night.", "It rained **for three days** without stopping. (not during three days)", "'When did you fall asleep?'  'During the movie.'  'How long were you asleep?'  '**For half an hour**.'"]}, {"label": "C", "explain": "during + คำนาม มีโครงสร้างคู่ขนานกับ while + ประธาน+กริยา และเมื่อพูดถึงอนาคตหลัง while ใช้ present tense (ไม่ใช้ will)", "examples": ["I fell asleep **during the movie**. = I fell asleep **while I was watching** TV.", "We met interesting people **during our holiday**. = **while we were on holiday**.", "I hope the weather **will be good while I'm there**. (not while I will be)", "What are you going to do **while you're waiting**? (not while you'll be waiting)"]}], "notes": [], "mistake": {"wrong": "It rained during three days.", "right": "It rained for three days.", "note": "ห้ามใช้ during เพื่อบอกระยะเวลานานเท่าไร (how long) ต้องใช้ for แทน"}, "tip": "during ตอบคำถาม 'เมื่อไร' (when) ส่วน for ตอบคำถาม 'นานแค่ไหน' (how long) — during+noun, while+subject+verb (โครงสร้างคู่ขนานกัน)", "summary": ["during + noun = บอกว่าเกิดขึ้น 'เมื่อไร' (ในช่วงเวลาไหน) ไม่ใช่นานเท่าไร", "for + ระยะเวลา = บอกว่า 'นานแค่ไหน' (ไม่ใช้ during กับการบอกระยะเวลา)", "while + subject + verb ใช้แทน during + noun ได้ (โครงสร้างคู่ขนานกัน); ไม่ใช้ will หลัง while เมื่อพูดถึงอนาคต"]}, {"unit": 120, "section": "Conjunctions and prepositions", "title": "by และ until, by the time", "pattern": "by = ไม่เกินเวลานั้น (จุดเดียว)  ·  until/till = ดำเนินต่อเนื่องจนถึงเวลานั้น  ·  by the time", "sections": [{"label": "A", "explain": "by = ไม่ช้ากว่าเวลาที่กำหนด (จุดหนึ่งเดียว ไม่ใช่ช่วงเวลาต่อเนื่อง) ส่วน until (หรือ till) ใช้บอกว่าสถานการณ์หนึ่งดำเนินต่อเนื่องไปจนถึงเวลานั้น", "examples": ["I sent the documents today, so they should arrive **by Monday**. (= ไม่ช้ากว่าวันจันทร์)", "We have to be home **by 5 o'clock**.", "Where's Sarah?  She should be here **by now**.", "Let's wait **until it stops raining**. (= รอต่อไปจนกว่าฝนจะหยุด)", "I stayed in bed **until half past ten**. (= อยู่บนเตียงต่อเนื่องจนถึง 10:30)"]}, {"label": "B", "explain": "เราใช้ 'by the time + ประโยค' เพื่อบอกผลลัพธ์สะสมเมื่อถึงเวลาหนึ่ง (present สำหรับอนาคต, past สำหรับอดีต)", "examples": ["It's too late.  **By the time we get there**, it will be closed.", "**By the time** you check in and go through security, it will be time for your flight.", "Karen's car broke down.  **By the time she arrived**, most of the guests had left.", "I was very tired **by the time I finished**."]}, {"label": "C", "explain": "เราสามารถใช้ by then หรือ by that time เพื่ออ้างถึงเวลาที่กล่าวถึงไปแล้วในประโยคก่อนหน้า", "examples": ["Karen finally got to the party at midnight, but **by then** most of the other guests had left.", "...but **by that time**, most of the other guests had left."]}, {"label": "D", "explain": "เปรียบเทียบ until (สถานการณ์ดำเนินต่อเนื่องไปจนถึงเวลานั้นแล้วจึงเปลี่ยน) กับ by (เหตุการณ์เกิดขึ้นสำเร็จไม่ช้ากว่าเวลานั้น)", "examples": ["Joe will be away **until Monday**. (= เขาจะกลับมาวันจันทร์)", "Joe will be back **by Monday**. (= ไม่ช้ากว่าวันจันทร์)", "I'll be working **until 11.30**. (= หยุดทำงานตอน 11.30)", "I'll have finished my work **by 11.30**. (= จะเสร็จไม่ช้ากว่า 11.30)"]}], "notes": [], "mistake": {"wrong": "I'll stay here by 10 o'clock.", "right": "I'll stay here until 10 o'clock.", "note": "by ใช้บอกจุดที่ไม่เกินเวลานั้น (เหตุการณ์เกิดขึ้นครั้งเดียว) ส่วน until ใช้บอกว่าสถานการณ์ดำเนินต่อไปจนถึงเวลานั้น"}, "tip": "by = ทำสำเร็จ/เกิดขึ้นไม่เกินเวลานั้น (จุดเดียว), until = ดำเนินต่อเนื่องไปจนถึงเวลานั้น (ช่วงเวลาต่อเนื่อง) — มักใช้ by กับ finish/arrive/be ready และใช้ until กับ wait/stay/continue", "summary": ["by = ไม่เกินเวลาที่กำหนด (จุดเดียว), until/till = ดำเนินต่อเนื่องไปจนถึงเวลานั้น", "by the time + ประโยค = บอกผลลัพธ์สะสมเมื่อถึงเวลาหนึ่ง (ใช้ present สำหรับอนาคต, past สำหรับอดีต)", "by then/by that time ใช้อ้างถึงเวลาที่กล่าวถึงไปแล้ว"]}, {"unit": 121, "section": "Prepositions", "title": "at/on/in (เวลา)", "pattern": "at + เวลานาฬิกา  ·  on + วัน/วันที่  ·  in + ช่วงเวลายาว", "sections": [{"label": "A", "explain": "เราใช้ at กับเวลานาฬิกา, on กับวันและวันที่, และ in กับช่วงเวลาที่ยาวกว่า (เดือน/ปี/ฤดู/ทศวรรษ/ศตวรรษ)", "examples": ["They arrived **at 5 o'clock**.", "They arrived **on Friday**.", "They arrived **in June**. / **in 2012**.", "in the **1990s**, in the **20th century**, in **winter**"]}, {"label": "B", "explain": "สำนวนที่ใช้ at คงที่: at the moment/at present (=ตอนนี้), at the same time, at the weekend, at Christmas, at night (ทั่วไป) vs in the night (คืนใดคืนหนึ่ง)", "examples": ["Can we talk later?  I'm busy **at the moment**.", "Kate and I arrived **at the same time**.", "Will you be here **at the weekend**?", "I don't like working **at night**. but I was woken up by a noise **in the night**."]}, {"label": "C", "explain": "เราใช้ in the morning(s)/in the afternoon(s)/in the evening(s) โดยทั่วไป แต่ใช้ on กับเช้า/บ่าย/เย็นของวันที่เจาะจง และไม่ใช้ at/on/in หน้า last/next/this/every", "examples": ["I'll see you **in the morning**.", "I'll see you **on Friday morning**.", "I'll see you **next Friday**. (not on next Friday)", "They got married **last June**. (ไม่มีคำบุพบทนำหน้า)"]}, {"label": "D", "explain": "เราใช้ in + ระยะเวลา เพื่อบอกว่า 'อีกกี่นาที/วัน/ปีข้างหน้า' หรือ 'ใช้เวลานานเท่าไรในการทำสิ่งหนึ่งให้เสร็จ'", "examples": ["The train will be leaving **in a few minutes**. (= อีกไม่กี่นาทีจากนี้)", "Andy has gone away.  He'll be back **in a week**.", "I learnt to drive **in four weeks**. (= ใช้เวลาสี่สัปดาห์)"]}], "notes": [], "mistake": {"wrong": "I'll see you on next Friday.", "right": "I'll see you next Friday.", "note": "ไม่ใช้ at/on/in หน้า last/next/this/every"}, "tip": "จำหลักพื้นฐาน: at = จุดเวลาแคบที่สุด (นาฬิกา), on = วันหนึ่งวัน, in = ช่วงเวลากว้าง (เดือน/ปี/ฤดู) — ยิ่งช่วงเวลากว้างขึ้น ยิ่งใช้ in", "summary": ["at กับเวลานาฬิกา (at 5 o'clock), on กับวันและวันที่ (on Friday), in กับช่วงเวลายาว (in June, in 2012)", "at the moment/at the weekend/at night(ทั่วไป) ต่างจาก in the night (คืนใดคืนหนึ่ง)", "ไม่ใช้ at/on/in หน้า last/next/this/every; in + ระยะเวลา = อีกเท่าไรข้างหน้า หรือใช้เวลานานเท่าไร"]}, {"unit": 122, "section": "Prepositions", "title": "on time / in time, at the end / in the end", "pattern": "on time = ตรงเวลาที่วางแผนไว้  ·  in time = ทันเวลา (ก่อนสาย)  ·  at the end (จุดที่สิ้นสุด)  ·  in the end = ในที่สุด", "sections": [{"label": "A", "explain": "on time = ตรงเวลาตามแผน (ไม่สาย) ส่วน in time (for/to do something) = ทันเวลาพอดี (ก่อนจะสายเกินไป) ตรงข้ามกับ too late", "examples": ["The 11.45 train left **on time**. (= ออกตรงเวลา 11.45)", "Will you be home **in time for dinner**? (= ทันเวลาสำหรับมื้อเย็น)", "I got home **too late** to watch the game.", "We got to the station **just in time** for our train. (= เกือบสายแล้ว)"]}, {"label": "B", "explain": "at the end (of something) = ตอนที่สิ้นสุดของสิ่งหนึ่ง (จุดเวลา) ตรงข้ามกับ at the beginning; ห้ามพูดว่า 'in the end of...'", "examples": ["I'm going away **at the end of January**.", "**At the end of the concert**, everyone applauded.", "I'm going away **at the beginning of January**. (not in the beginning)"]}, {"label": "C", "explain": "in the end = ในที่สุด (ใช้บอกผลลัพธ์สุดท้ายของสถานการณ์ ไม่ใช่จุดเวลา) ตรงข้ามกับ at first", "examples": ["We had a lot of problems with our car.  We sold it **in the end**. (= ในที่สุดก็ขายมันไป)", "He got more and more angry.  **In the end** he just walked out.", "**At first** we didn't get on well, but **in the end** we became good friends."]}], "notes": [], "mistake": {"wrong": "He didn't go anywhere at the end.", "right": "He didn't go anywhere in the end.", "note": "in the end = ในที่สุด (บอกผลลัพธ์สุดท้าย) ไม่ใช่ at the end ที่บอกจุดเวลาสิ้นสุด"}, "tip": "on time เทียบกับตารางเวลาที่วางแผนไว้ (ไม่สาย), in time เทียบกับเส้นตายที่จะพลาด (ทันเวลาก่อนสายเกินไป), at the end บอกจุดเวลา, in the end บอกผลลัพธ์สุดท้าย", "summary": ["on time = ตรงเวลาตามแผน; in time (for/to) = ทันเวลาก่อนจะสายเกินไป (ตรงข้ามกับ too late)", "at the end (of + noun) = จุดเวลาที่สิ้นสุด (ตรงข้ามกับ at the beginning) ห้ามพูด 'in the end of'", "in the end = ในที่สุด (บอกผลลัพธ์สุดท้ายของสถานการณ์ ตรงข้ามกับ at first)"]}, {"unit": 123, "section": "Prepositions", "title": "in/at/on (ตำแหน่ง) 1", "pattern": "in (พื้นที่ปิดล้อม)  ·  at (จุด)  ·  on (พื้นผิว)", "sections": [{"label": "A", "explain": "เราใช้ in กับพื้นที่ที่มีขอบเขตล้อมรอบ เช่น ห้อง อาคาร กล่อง สวน เมือง สระน้ำ ทะเล แม่น้ำ", "examples": ["There's no-one **in the room / in the building / in the garden**.", "What do you have **in your hand / in your mouth**?", "There were some people swimming **in the pool / in the sea / in the river**."]}, {"label": "B", "explain": "เราใช้ at กับ 'จุด' หนึ่งเฉพาะ เช่น ป้ายรถเมล์ ประตู หน้าต่าง สัญญาณไฟจราจร ทางแยก", "examples": ["Who is that man standing **at the bus stop / at the door / at the window**?", "Turn left **at the traffic lights / at the roundabout**.", "I'll meet you **at the entrance** to the hotel. (= นอกอาคาร)", "I'll meet you **in the hotel lobby**. (= ในอาคาร)"]}, {"label": "C", "explain": "เราใช้ on กับพื้นผิว เช่น พื้น เพดาน ผนัง กระดาษ เกาะ (ที่คิดเป็นพื้นผิว)", "examples": ["I sat **on the floor / on the ground / on a chair**.", "There's a dirty mark **on the ceiling / on your shirt**.", "Did you see the notice **on the wall / on the door**?", "There is a label **on the bottle**. (ต่างจาก 'water in the bottle')"]}], "notes": [], "mistake": {"wrong": "There is somebody on the door.", "right": "There is somebody at the door.", "note": "at the door = มีคนยืนอยู่ตรงประตู (จุด) ส่วน on the door = มีสิ่งของติดอยู่บนแผ่นประตู (พื้นผิว) เช่น a notice on the door"}, "tip": "in = ข้างในพื้นที่ปิดล้อม, at = จุดหนึ่งจุด, on = บนพื้นผิว — ลองนึกภาพสามมิติ: in คือปริมาตร, at คือจุด, on คือระนาบ", "summary": ["in ใช้กับพื้นที่ปิดล้อม (ห้อง อาคาร กล่อง สระน้ำ แม่น้ำ)", "at ใช้กับจุดหนึ่งเฉพาะ (ป้ายรถเมล์ ประตู หน้าต่าง สัญญาณไฟ)", "on ใช้กับพื้นผิว (พื้น เพดาน ผนัง หน้ากระดาษ)"]}, {"unit": 124, "section": "Prepositions", "title": "in/at/on (ตำแหน่ง) 2", "pattern": "in (แถว, รูปภาพ, ประเทศ)  ·  on (ซ้าย/ขวา, ชั้น, แผนที่, ทาง)  ·  at (บน/ล่าง/ปลายสุด)", "sections": [{"label": "A", "explain": "เราใช้ in กับ: แถว/คิว, รูปภาพ, หนังสือพิมพ์/นิตยสาร, แผนก, ท้องฟ้า/โลก, ชนบท (ไม่ใช่ในเมือง)", "examples": ["When I go to the cinema, I like to sit **in the front row**.", "Amy works **in the sales department**.", "Who is the woman **in that picture**?", "Do you live **in a city** or **in the country**?"]}, {"label": "B", "explain": "เราใช้ on กับ: ซ้าย/ขวา, ชั้นของอาคาร, แผนที่/เมนู/รายการ/หน้า/เว็บไซต์, แม่น้ำ/ถนน/ชายฝั่ง, และ 'ระหว่างทาง'", "examples": ["Do you drive **on the left** or **on the right**?", "Our apartment is **on the second floor**.", "You'll find the information **on our website**.", "Vienna is **on the (river) Danube**.", "We stopped at a shop **on the way** home."]}, {"label": "C-D-E", "explain": "เราใช้ at กับ top/bottom/end ของบางสิ่ง; in the front/back (ในรถ) แต่ at the front/back (ของอาคาร/โรงละคร/กลุ่มคน); on the front/back (ของซองจดหมาย); in the corner (ของห้อง) แต่ at/on the corner (ของถนน)", "examples": ["Write your name **at the top** of the page.", "I was **in the back** (of the car) when we had the accident.", "The garden is **at the back** of the house.", "I wrote the date **on the back** of the photo.", "The TV is **in the corner** of the room.  There is a small shop **at the corner** of the street."]}], "notes": [], "mistake": {"wrong": "Write your name in the top of the page.", "right": "Write your name at the top of the page.", "note": "at the top/bottom/end (of) ใช้ at เสมอ ไม่ใช่ in"}, "tip": "จำคู่ตรงข้ามสำคัญ: in the front/back (ในรถ, พื้นที่ปิดล้อม) vs at the front/back (ของอาคาร/กลุ่มคน, ตำแหน่งภายนอก) vs on the front/back (ของกระดาษ, พื้นผิว)", "summary": ["in ใช้กับแถว/คิว, รูปภาพ, หนังสือพิมพ์, แผนก, ท้องฟ้า, ชนบท", "on ใช้กับซ้าย/ขวา, ชั้นอาคาร, แผนที่/เมนู/เว็บไซต์, แม่น้ำ/ถนน, 'ระหว่างทาง'", "at the top/bottom/end (of); in the front/back (รถ) ≠ at the front/back (อาคาร/กลุ่มคน) ≠ on the front/back (กระดาษ)"]}, {"unit": 125, "section": "Prepositions", "title": "in/at/on (ตำแหน่ง) 3", "pattern": "in bed/hospital/prison  ·  at home/work/school/an event  ·  in/at buildings  ·  on a bus/in a car", "sections": [{"label": "A", "explain": "เราพูดว่าคนอยู่ in bed/in hospital/in prison แต่พูดว่าอยู่ at home/at work/at school/at university และใช้ at an event (at a party, at a concert)", "examples": ["James isn't up yet.  He's still **in bed**.", "Anna's mother is **in hospital**.", "I'll be **at work** until 5.30.", "Were there many people **at the party / at the meeting**?"]}, {"label": "B", "explain": "เราใช้ทั้ง in และ at กับอาคารได้ (in/at a restaurant) แต่มักใช้ at เมื่อพูดถึงสถานที่จัดงาน (event) และใช้ at somebody's house/at the doctor's", "examples": ["We went to a concert **at the National Concert Hall**.", "I was **at Helen's house** last night. (= at Helen's)", "It's always cold **in Helen's house**. (พูดถึงตัวอาคารเอง)", "There's no need to meet me **at the station**."]}, {"label": "C", "explain": "เราใช้ in กับเมือง/ประเทศ/หมู่บ้าน แต่ใช้ at เมื่อมองสถานที่นั้นเป็น 'จุดแวะพัก' บนเส้นทางการเดินทาง", "examples": ["The Louvre is a famous art museum **in Paris**. (not at Paris)", "Does this train stop **at Oxford**? (= สถานี Oxford)"]}, {"label": "D", "explain": "เราใช้ on กับรถบัส/รถไฟ/เครื่องบิน/เรือ แต่ใช้ in กับรถยนต์/แท็กซี่ และใช้ on กับจักรยาน/มอเตอร์ไซค์/ม้า", "examples": ["The bus was very full.  There were too many people **on it**.", "Laura arrived **in a taxi**.", "Jane passed me **on her bike**."]}], "notes": [], "mistake": {"wrong": "I was at Helen's house, it's always cold at Helen's house.", "right": "I was at Helen's house. It's always cold in Helen's house.", "note": "at Helen's house = ไปเยี่ยม (บริบทเหตุการณ์), in Helen's house = พูดถึงตัวอาคาร (อุณหภูมิภายใน)"}, "tip": "at เน้น 'จุดหมาย/เหตุการณ์' (at work, at a party, at Helen's) ส่วน in เน้น 'ตัวอาคาร/พื้นที่ภายใน' (in the office building, in Helen's house)", "summary": ["in bed/in hospital/in prison แต่ at home/at work/at school/at university; at an event (at a party)", "in/at ใช้ได้กับอาคารทั่วไป แต่ at เมื่อพูดถึงสถานที่จัดงาน หรือ at somebody's house/at the station/at the airport", "in ใช้กับเมือง/ประเทศ (in Paris) แต่ at เมื่อมองเป็นจุดแวะ (at Oxford = สถานี); on รถสาธารณะ/จักรยาน แต่ in รถยนต์/แท็กซี่"]}, {"unit": 126, "section": "Prepositions", "title": "to, at, in, into", "pattern": "to (การเคลื่อนที่)  ·  in/at (ตำแหน่ง)  ·  into = เข้าไปข้างใน  ·  home (ไม่มีบุพบท)", "sections": [{"label": "A", "explain": "เราใช้ to กับกริยาที่บ่งบอกการเคลื่อนที่ (go/come/travel/return/be taken) ไปยังสถานที่หรือเหตุการณ์ และเปรียบเทียบ to (การเคลื่อนที่) กับ in/at (ตำแหน่งนิ่ง)", "examples": ["When are your friends going back **to Italy**? (not going back in Italy)", "Three people were taken **to hospital**.", "They are going **to France**. but They live **in France**.", "I've **been to** Italy four times, but never **been to** Rome."]}, {"label": "B", "explain": "เราใช้ get to + สถานที่ (ทุกกรณี) แต่ arrive ใช้ arrive in (เมือง/ประเทศ) หรือ arrive at (อาคาร/เหตุการณ์อื่นๆ) — ไม่ใช้ 'arrive to'", "examples": ["They **got to** the hotel at midnight.", "They **arrived in** Madrid / in Spain a week ago.", "What time did you **arrive at** the hotel / at the party?"]}, {"label": "C", "explain": "เราไม่ใช้คำบุพบทใดๆ กับ home (go home, come home, get home, arrive home) — ไม่พูดว่า 'to home'", "examples": ["What time did you **get home**? (not get to home)", "I met Lisa **on my way home**."]}, {"label": "D", "explain": "into (หรือบางครั้ง in กับกริยา go/get/put) = เข้าไปข้างใน (ตรงข้ามกับ out of); สำหรับรถบัส/รถไฟ/เครื่องบิน ใช้ get on/get off", "examples": ["I opened the door, **went into** the room and sat down.", "She **got in(to)** the car and drove away.", "She **got out of** the car and **went into** a shop.", "You need to **get off** (the train) at the next station."]}], "notes": [], "mistake": {"wrong": "What time did you get to home?", "right": "What time did you get home?", "note": "home ไม่ใช้คำบุพบทนำหน้าเมื่อตามหลังกริยาการเคลื่อนที่ (go home, get home)"}, "tip": "to = ทิศทางการเคลื่อนที่ไปยังที่ใดที่หนึ่ง, in/at = ตำแหน่งที่อยู่นิ่ง — เปรียบเทียบ 'going to France' (เคลื่อนที่) กับ 'living in France' (อยู่นิ่ง)", "summary": ["to ใช้กับกริยาการเคลื่อนที่ไปยังสถานที่/เหตุการณ์; arrive in (เมือง/ประเทศ) หรือ arrive at (อาคาร/เหตุการณ์) ไม่ใช้ arrive to", "home ไม่ใช้คำบุพบทนำหน้าเลย (go home, get home, arrive home)", "into = เข้าไปข้างใน (ตรงข้าม out of); รถบัส/รถไฟ/เครื่องบิน ใช้ get on/get off"]}, {"unit": 127, "section": "Prepositions", "title": "in/on/at (การใช้อื่นๆ)", "pattern": "in (สภาพอากาศ/ภาษา/อารมณ์)  ·  on (สื่อ/กิจกรรม/การเดินทางเพื่อธุระ)  ·  at + อัตรา/อายุ", "sections": [{"label": "A", "explain": "เราใช้ in กับ: สภาพอากาศ (in the rain/in the sun/in the dark), ภาษา/สกุลเงิน (in Russian), ความรัก/อารมณ์ (in love, in a mood), และความคิดเห็น (in my opinion)", "examples": ["Don't go out **in the rain**.  Wait until it stops.", "How do you say 'thank you' **in Russian**?", "They're very happy together.  They're **in love**.", "**In my opinion** the movie wasn't very good."]}, {"label": "B", "explain": "เราใช้ on กับ: สื่อ (on TV/on the radio/on the phone), on fire, on purpose, on the whole", "examples": ["I didn't see the news **on TV**.", "I've never met her, but I've spoken to her **on the phone**.", "Look!  That car is **on fire**.", "Sometimes I have problems at work, but **on the whole** I enjoy my job."]}, {"label": "C", "explain": "เราใช้ on กับกิจกรรม/การเดินทางประเภทหนึ่ง: on holiday, on a trip/tour/cruise, on business, on strike, on a diet", "examples": ["I'm going **on holiday** next week.", "Emma's away **on business** at the moment.", "There are no trains today.  The drivers are **on strike**.", "I've put on weight.  I'll have to go **on a diet**."]}, {"label": "D", "explain": "เราใช้ at กับอายุและอัตรา/ความเร็ว: at the age of, at ... miles an hour, at ... degrees", "examples": ["Tracy left school **at 16**. (or at the age of 16)", "The train was travelling **at 120 miles an hour**.", "Water boils **at 100 degrees Celsius**."]}], "notes": [], "mistake": {"wrong": "I heard it in the radio.", "right": "I heard it on the radio.", "note": "สื่อกระจายเสียง/ภาพ (TV, radio, phone) ใช้ on ไม่ใช่ in"}, "tip": "สำนวนเหล่านี้เป็นกลุ่มคำนามคงที่ (fixed expressions) ที่ต้องท่องจำเป็นวลี ไม่สามารถเดาได้จากกฎ in/at/on ทั่วไป", "summary": ["in ใช้กับสภาพอากาศ (in the rain), ภาษา (in Russian), อารมณ์/ความรู้สึก (in love, in a mood), ความคิดเห็น (in my opinion)", "on ใช้กับสื่อ (on TV/on the radio/on the phone), on fire, on purpose, on the whole", "on ใช้กับกิจกรรมประเภทหนึ่ง (on holiday, on business, on strike, on a diet); at ใช้กับอายุและอัตรา (at 16, at 100 degrees)"]}, {"unit": 128, "section": "Prepositions", "title": "by", "pattern": "by chance/mistake/accident  ·  by + วิธีเดินทาง/วิธีทำ  ·  by (passive/ผู้แต่ง)  ·  by = next to  ·  by = ต่างกันเท่าไร", "sections": [{"label": "A", "explain": "เราพูด by chance/by mistake/by accident (ไม่มี the/a นำหน้า) และแยกจาก on purpose (=ตั้งใจ) และเราใช้ by + วิธีเดินทาง (by car/by train) หรือ by + วิธีทำสิ่งหนึ่ง (by post/by hand/by credit card) — แต่ใช้ in my car, on the train, on foot", "examples": ["We hadn't arranged to meet.  We met **by chance**.", "I didn't do it **on purpose**.  It was an accident.", "Jess usually goes to work **by bus**. but **in my car** (not by my car), **on foot** (not by foot).", "Can I pay **by credit card**?"]}, {"label": "B", "explain": "เราใช้ by ในประโยค passive เพื่อบอกว่าใครเป็นผู้กระทำ และใช้บอกผู้แต่งงานศิลปะ/วรรณกรรม", "examples": ["Have you ever been bitten **by a dog**?", "The programme was watched **by millions** of people.", "Have you read any poems **by Shakespeare**?", "The door must have been opened **with a key**. (with = เครื่องมือ, ต่างจาก by = ผู้กระทำ)"]}, {"label": "C", "explain": "by ยังหมายถึง 'ข้างๆ/ติดกับ' ได้ด้วย", "examples": ["The light switch is **by the door**.", "Come and sit **by me**. (= next to me)"]}, {"label": "D", "explain": "เราใช้ by เพื่อบอกว่าสิ่งหนึ่งต่างจากอีกสิ่งหนึ่งเท่าไร (ปริมาณความต่าง)", "examples": ["Clare's salary has increased **by ten per cent**.", "Carl won the race **by five metres**."]}], "notes": [], "mistake": {"wrong": "The door was opened by a key.", "right": "The door was opened with a key.", "note": "with ใช้บอกเครื่องมือที่ใช้กระทำ (with a key) ส่วน by ใช้บอกผู้กระทำที่เป็นคน/สิ่งมีชีวิต (by somebody)"}, "tip": "by chance/mistake/accident ไม่มี a/the นำหน้า (ต่างจากภาษาไทยที่อาจคิดว่าต้องมีคำนำหน้า) — ท่องจำเป็นวลีคงที่", "summary": ["by chance/mistake/accident (ไม่มี a/the); by + วิธีเดินทาง/ทำสิ่งหนึ่ง (by bus, by post) แต่ in my car, on foot", "by ใช้บอกผู้กระทำใน passive (by a dog) และผู้แต่งงานศิลปะ (a play by Shakespeare); with ใช้บอกเครื่องมือ", "by = ข้างๆ/ติดกับ (by the door); by = ปริมาณความต่าง (increased by ten per cent)"]}, {"unit": 129, "section": "Prepositions", "title": "คำนาม + บุพบท (reason for, cause of ฯลฯ)", "pattern": "noun + for/of/in/with/to (คู่คำนามคงที่)", "sections": [{"label": "A", "explain": "คำนามกลุ่มนี้ตามด้วย for: a demand/need for, a reason for", "examples": ["There's no **demand for** its product any more.", "There's no **excuse for** behaviour like that.", "Nobody knew the **reason for** the delay. (not reason of)"]}, {"label": "B", "explain": "คำนามกลุ่มนี้ตามด้วย of: a picture/photo/map of, a cause of", "examples": ["Rachel showed me some **pictures of** her family.", "The **cause of** the explosion is unknown."]}, {"label": "C", "explain": "คำนามกลุ่มนี้ตามด้วย in: an increase/decrease/rise/fall in", "examples": ["There has been an **increase in** the number of road accidents.", "There was a big **fall in** sales."]}, {"label": "D", "explain": "คำนามกลุ่มนี้ตามด้วย with (สำหรับสองสิ่ง) หรือ between (ระหว่างสองสิ่ง): a relationship/connection/contact with, a difference between", "examples": ["Do you have a good **relationship with** your parents?", "There are some **differences between** British and American English."]}, {"label": "E", "explain": "คำนามกลุ่มนี้ตามด้วย to: a solution to, a key to, an answer to, damage to, an invitation to, an attitude to/towards", "examples": ["I hope we find a **solution to** the problem. (not solution of)", "The accident was my fault, so I paid for the **damage to** the other car.", "Did you get an **invitation to** the wedding?"]}], "notes": [], "mistake": {"wrong": "I hope we find a solution of the problem.", "right": "I hope we find a solution to the problem.", "note": "solution ตามด้วย to เสมอ ไม่ใช่ of"}, "tip": "คู่คำนาม+บุพบทเหล่านี้เป็นวลีคงที่ (fixed collocations) ต้องท่องจำเป็นคู่ ไม่สามารถเดาจากคำแปลภาษาไทยได้เสมอไป", "summary": ["noun + for (demand for, need for, reason for), noun + of (picture of, cause of)", "noun + in (increase/decrease/rise/fall in), noun + with/between (relationship with, difference between)", "noun + to (solution to, key to, answer to, damage to, invitation to)"]}, {"unit": 130, "section": "Prepositions", "title": "คำคุณศัพท์ + บุพบท 1", "pattern": "nice/kind + OF + คน  ·  nice/kind + TO + คน  ·  pleased/satisfied + WITH  ·  surprised/shocked + AT/BY  ·  sorry ABOUT/FOR  ·  angry ABOUT/WITH...FOR", "sections": [{"label": "A", "explain": "เมื่อประเมิน 'อุปนิสัย' ของคนจากการกระทำ ใช้ adjective + of + somebody (nice/kind/generous/silly of you to...) ส่วนเมื่อพูดถึง 'การปฏิบัติต่อคนอื่น' ใช้ adjective + to + somebody", "examples": ["It was very **nice of you** to help me.", "It was **stupid of me** to go out without a coat.", "They have always been very **nice to me**. (not with me)", "Why were you so **unfriendly to** Lucy?"]}, {"label": "B", "explain": "pleased/satisfied/happy/delighted/disappointed ตามด้วย with เมื่อพูดถึงสิ่งที่ได้รับหรือประสบการณ์; surprised/shocked/amazed/astonished/upset ตามด้วย at หรือ by", "examples": ["They were **delighted with** the present I gave them.", "Were you **happy with** your exam results?", "Everybody was **surprised at** the news. (or by the news)"]}, {"label": "C", "explain": "sorry about ใช้กับสถานการณ์/สิ่งที่เกิดขึ้น; sorry for/about ใช้กับสิ่งที่ตัวเองทำ; angry/annoyed/upset about + เรื่อง, with + คน + for + สิ่งที่ทำ", "examples": ["I'm **sorry about** the mess.  I'll clear it up later.", "I'm **sorry for** shouting at you yesterday. (or sorry about shouting)", "Are you **annoyed with me for** being late?"]}, {"label": "D", "explain": "คำคุณศัพท์อื่นๆ ที่ใช้กับ about/with: excited/worried/nervous about, impressed with/by, sorry for (คนที่อยู่ในสถานการณ์แย่), fed up/bored with, tired of", "examples": ["Are you **nervous about** the exam?", "I'm very **impressed with** her English. (or by)", "I **feel sorry for** Mark. (not sorry about Mark)", "I'm **fed up with** it. / I'm **tired of** waiting."]}], "notes": [], "mistake": {"wrong": "They have always been very nice with me.", "right": "They have always been very nice to me.", "note": "adjective (nice/kind/rude ฯลฯ) + to + somebody เมื่อพูดถึงการปฏิบัติต่อคนอื่น ไม่ใช้ with"}, "tip": "แยกสองความหมาย: adjective + of + somebody (ประเมินอุปนิสัยจากการกระทำ) กับ adjective + to + somebody (การปฏิบัติต่อกัน) — 'it was nice of you to help' vs 'they were nice to me'", "summary": ["nice/kind/silly + of + somebody (to do) = ประเมินอุปนิสัย; nice/kind/rude + to + somebody = การปฏิบัติต่อกัน", "pleased/satisfied/disappointed + with (สิ่งที่ได้รับ); surprised/shocked/amazed + at/by", "sorry about (สถานการณ์) / sorry for (สิ่งที่ทำ); angry/annoyed about + เรื่อง, with + คน + for + การกระทำ"]}, {"unit": 131, "section": "Prepositions", "title": "คำคุณศัพท์ + บุพบท 2", "pattern": "afraid/good/fond/similar/dependent/interested/famous/married + บุพบทเฉพาะ", "sections": [{"label": "A", "explain": "คำคุณศัพท์กลุ่มนี้ตามด้วย of: afraid/scared/frightened of, fond/proud/ashamed/jealous of, suspicious/aware/capable of, typical of", "examples": ["'Are you **afraid of** spiders?'  'Yes, I'm **terrified of** them.'", "Why is he so **jealous of** other people?", "I'm sure you are **capable of** doing the job well.", "It's **typical of** him to keep everybody waiting."]}, {"label": "B", "explain": "good/bad/better + at (ความสามารถ); similar to; dependent on (แต่ independent of); interested in; famous for; different from/to; keen on; married to (แต่ married with children)", "examples": ["I'm not very **good at** repairing things. (not good in)", "Your handwriting is **similar to** mine.", "I don't want to be **dependent on** anybody.", "Are you **interested in** art?", "The city is **famous for** its art treasures.", "Louise is **married to** an American. (not married with)"]}, {"label": "C", "explain": "responsible for, full/short of, crowded with (people); certain/sure of or about", "examples": ["Who was **responsible for** all that noise?", "Amy is always **full of** energy.", "I'm a bit **short of** money.", "The streets were **crowded with** tourists. (but full of tourists)"]}], "notes": [], "mistake": {"wrong": "I'm not very good in repairing things.", "right": "I'm not very good at repairing things.", "note": "good/bad ตามด้วย at เมื่อพูดถึงความสามารถ ไม่ใช่ in"}, "tip": "คำคุณศัพท์+บุพบทกลุ่มนี้เป็นคู่คำคงที่ (collocations) — ระวังคำที่ภาษาไทยอาจแปลตรงตัวผิด เช่น 'good at' (ไม่ใช่ good in), 'married to' (ไม่ใช่ married with เมื่อพูดถึงคู่สมรส)", "summary": ["afraid/fond/proud/ashamed/jealous/capable/typical + of", "good/bad + at; similar + to; dependent + on (independent + of); interested + in; famous + for", "responsible + for; full/short + of; crowded + with; married + to (แต่ married with + ลูก)"]}, {"unit": 132, "section": "Prepositions", "title": "กริยา + บุพบท 1: to และ at", "pattern": "talk/listen/explain + to  ·  look/laugh/shout + at  ·  phone/answer (ไม่มีบุพบท)", "sections": [{"label": "A", "explain": "กริยากลุ่มนี้ตามด้วย to: talk/speak to, listen to, apologise to, explain (something) to (somebody) — ตรงข้ามกับ ask/thank/phone/answer ที่ไม่มี to", "examples": ["Who were you **talking to**?", "I like to **listen to** the radio. (not listen the radio)", "They **apologised to** me for their mistake. (not apologised me)", "Can you **explain this word to me**? (not explain me this word)"]}, {"label": "B", "explain": "กริยากลุ่มนี้ไม่ใช้บุพบทเลย: ask somebody, thank somebody, phone/call/email/text somebody", "examples": ["If there's anything you want to know, you can **ask me**. (not ask to me)", "He **thanked me** for helping him. (not thanked to me)", "I **called the airline** to cancel my flight. (not called to the airline)"]}, {"label": "C", "explain": "กริยากลุ่มนี้ตามด้วย at: look/stare/glance at, laugh at", "examples": ["Why are you **looking at** me like that?", "Everybody will **laugh at** me."]}, {"label": "D", "explain": "บางกริยาใช้ได้ทั้ง at และ to โดยความหมายต่างกัน: shoot/point/aim at (เล็งเพื่อทำร้าย) vs shout to (เพื่อให้ได้ยิน), throw at (เพื่อขว้างใส่) vs throw to (เพื่อให้รับ)", "examples": ["Don't point that knife **at** me.  It's dangerous.", "He **shouted at** me. (โกรธ) vs He **shouted to** me from across the street. (เพื่อให้ได้ยิน)", "Somebody **threw** an egg **at** the politician. vs Lisa **threw** the keys **to** me. (ให้ฉันรับ)"]}], "notes": [], "mistake": {"wrong": "Can you explain me this word?", "right": "Can you explain this word to me?", "note": "explain ต้องมี to นำหน้ากรรม (คน) เสมอ ห้ามใช้ explain + คน โดยตรง"}, "tip": "กริยาบางตัวที่ภาษาไทยอาจคิดว่าต้องมีบุพบท (ask, thank, phone) จริงๆ แล้วไม่มีบุพบทเลย ส่วน explain/apologise ที่ดูเหมือนไม่ต้องมี กลับต้องมี to เสมอ — ต้องท่องจำเป็นคู่", "summary": ["talk/speak to, listen to, apologise to, explain...to (ต้องมี to)", "ask, thank, phone/call/email/text (ไม่มีบุพบทเลย)", "look/stare/glance at, laugh at; shoot/point/aim at (ทำร้าย) vs shout/throw to (ให้ได้ยิน/ให้รับ)"]}, {"unit": 133, "section": "Prepositions", "title": "กริยา + บุพบท 2: about/for/of/after", "pattern": "apply for, look for, wait for, care for/about  ·  take care of, look after (ไม่ใช่ look for)", "sections": [{"label": "A", "explain": "กริยากลุ่มนี้ตามด้วย for: apply for, search for, look for, leave (a place) for (another place), ask somebody for, wait for — ยกเว้น discuss (ไม่มี about)", "examples": ["Why don't you **apply for** it?", "I've lost my keys.  Can you help me **look for** them?", "She **left** home **for** work. (not left to work)", "We **discussed** what we should do. (not discussed about)", "I'm **waiting for** the rain to stop."]}, {"label": "B", "explain": "care มีสามความหมายต่างกันตามบุพบทที่ตามมา: care for (=ดูแล หรือ =ชอบ ในรูปปฏิเสธ), care about (=ให้ความสำคัญ), care + question word (ไม่มีบุพบท)", "examples": ["Alan needs somebody to **care for him**. (=ดูแล)", "I don't **care for** hot weather. (=ไม่ชอบ)", "He's selfish.  He doesn't **care about** other people.", "I don't **care what** you do. (ไม่มี about)"]}, {"label": "C", "explain": "take care of และ look after มีความหมายเหมือนกัน (=ดูแล) แต่ look for แปลว่า 'ค้นหา' (คนละความหมายกับ look after)", "examples": ["I'll **take care of** the travel arrangements.", "Alan needs somebody to **look after** him. (not look for)", "I've lost my keys.  I need to **look for** them. (=ค้นหา)"]}], "notes": [], "mistake": {"wrong": "We discussed about the problem.", "right": "We discussed the problem.", "note": "discuss ไม่มีบุพบทตามหลังเลย (ไม่ใช้ discuss about)"}, "tip": "ระวังคำที่หน้าตาคล้ายกันแต่ความหมายต่างกันมาก: look for (ค้นหา) vs look after (ดูแล) — และ discuss ที่ไม่มีบุพบทตามหลังเลย ต่างจาก 'have a discussion about'", "summary": ["apply for, search for, look for, leave...for, ask...for, wait for (มี for); discuss ไม่มีบุพบท (not discuss about)", "care for (=ดูแล/ชอบ), care about (=ให้ความสำคัญ), care + question word (ไม่มีบุพบท)", "take care of = look after (ดูแล) ≠ look for (ค้นหา)"]}, {"unit": 134, "section": "Prepositions", "title": "กริยา + บุพบท 3: about และ of", "pattern": "hear about/of/from  ·  think of/about  ·  dream of/about  ·  remind...of/about", "sections": [{"label": "A", "explain": "hear about = ได้รับรู้เรื่องราวหนึ่ง, hear of = รู้ว่าคน/สิ่งของนั้นมีอยู่, hear from = ได้ติดต่อกับใคร", "examples": ["Did you **hear about** the fire at the hotel?", "'Who is Tom Hart?'  'I've never **heard of** him.' (not heard from him)", "'Have you **heard from** Jane recently?'  'Yes, she called me.'"]}, {"label": "B", "explain": "think about = พิจารณา/ครุ่นคิดถึง, think of = คิดขึ้นมาได้ (ไอเดีย) หรือให้ความเห็น", "examples": ["I'll **think about** it. (=พิจารณาก่อน)", "It was my idea.  I **thought of** it first. (not thought about it)", "'What did you **think of** the movie?'  'I didn't think much of it.'"]}, {"label": "C", "explain": "dream about (ฝันตอนนอนหลับ) และ dream of/about (=จินตนาการถึงอนาคต) ใช้ใกล้เคียงกัน; wouldn't dream of doing = จะไม่มีวันทำแบบนั้นเด็ดขาด", "examples": ["I **dreamt about** you last night.", "Do you **dream of** being rich and famous? (or dream about)", "'Don't tell anyone.'  'No, I **wouldn't dream of** it.'"]}, {"label": "D", "explain": "complain (to somebody) about = บ่นเรื่องที่ไม่พอใจ, complain of a pain/illness = บอกว่ามีอาการ", "examples": ["We **complained to** the manager **about** the food.", "George was **complaining of** a pain in his stomach."]}, {"label": "E", "explain": "remind somebody about = เตือนไม่ให้ลืม, remind somebody of = ทำให้นึกถึง (คนหรือสิ่งของอื่น)", "examples": ["It's good you **reminded me about** the meeting.", "This house **reminds me of** the one I lived in as a child."]}], "notes": [], "mistake": {"wrong": "I've never heard from him.", "right": "I've never heard of him.", "note": "hear of = รู้ว่ามีคนนี้อยู่ (ไม่เคยรู้จักมาก่อน) ต่างจาก hear from = เคยติดต่อกัน"}, "tip": "แยกให้ออก: hear of/about (รับรู้ข้อมูล) ≠ hear from (ติดต่อกัน); think of (คิดขึ้นได้/ให้ความเห็น) ≠ think about (พิจารณา/ครุ่นคิด)", "summary": ["hear about (ได้รับรู้เรื่อง), hear of (รู้ว่ามีอยู่), hear from (ได้ติดต่อกับ)", "think about (พิจารณา), think of (คิดไอเดียขึ้นมาได้/ให้ความเห็น)", "complain (to)...about (บ่น), complain of (บอกอาการป่วย); remind...about (เตือน), remind...of (ทำให้นึกถึง)"]}, {"unit": 135, "section": "Prepositions", "title": "กริยา + บุพบท 4: of/for/from/on", "pattern": "accuse/suspect of, congratulate/compliment on, approve/disapprove of, die of/from, suffer from, depend/rely on", "sections": [{"label": "A", "explain": "accuse/suspect somebody ตามด้วย of; approve/disapprove ตามด้วย of; die ตามด้วย of หรือ from", "examples": ["Tina **accused** me **of** being selfish.", "His parents **disapprove of** what he does.", "'What did he **die of**?'  'A heart attack.'"]}, {"label": "B", "explain": "congratulate/compliment somebody ตามด้วย on; thank/forgive somebody ตามด้วย for; apologise (to somebody) ตามด้วย for", "examples": ["I **congratulated** her **on** doing so well in her exams.", "I'll never **forgive** them **for** what they did.", "I **apologised** (to them) **for** my mistake."]}, {"label": "C", "explain": "suffer ตามด้วย from; protect somebody/something ตามด้วย from", "examples": ["There's been an increase in people **suffering from** heart disease.", "Sun cream **protects** the skin **from** the sun."]}, {"label": "D", "explain": "live ตามด้วย on (เงิน/อาหาร); consist ตามด้วย of; pay (somebody) ตามด้วย for (แต่ pay a bill/rent/fee/tax ไม่มีบุพบท)", "examples": ["It isn't enough to **live on**.", "The meal **consisted of** seven courses.", "We didn't have money to **pay for** the meal. (not pay the meal)", "We didn't have money to **pay the rent**. (ไม่มีบุพบท)"]}, {"label": "E", "explain": "blame somebody ตามด้วย for (หรือ blame something ตามด้วย on); depend/rely ตามด้วย on", "examples": ["Everybody **blamed me for** the accident.", "It wasn't my fault.  Don't **blame it on** me.", "You can **rely on** Anna.  She always keeps her promises."]}], "notes": [], "mistake": {"wrong": "We didn't have enough money to pay the meal.", "right": "We didn't have enough money to pay for the meal.", "note": "pay for + สิ่งของ/บริการ (ต้องมี for) แต่ pay a bill/rent/fee/tax ไม่มีบุพบท"}, "tip": "ระวังคำที่ตามด้วยบุพบทต่างกันตามบริบท: die of/from (ใกล้เคียงกัน) ต่างจาก suffer from (ตายตัว); pay for (สิ่งของ) ต่างจาก pay + bill/rent (ไม่มีบุพบท)", "summary": ["accuse/suspect + of; congratulate/compliment + on; approve/disapprove + of; die + of/from", "thank/forgive + for; suffer/protect + from; live + on; consist + of", "pay for + สิ่งของ (แต่ pay the bill ไม่มีบุพบท); blame + somebody + for หรือ blame + something + on; depend/rely + on"]}, {"unit": 136, "section": "Prepositions", "title": "กริยา + บุพบท 5: in/into/with/to/on", "pattern": "believe in, specialise in, break into, collide with, concentrate on, provide...with, prefer...to, succeed in, insist on", "sections": [{"label": "A", "explain": "believe in = เชื่อว่าสิ่งนั้นมีอยู่จริง/เชื่อว่าถูกต้อง (ต่างจาก believe something/somebody ที่ไม่มีบุพบท); specialise ตามด้วย in", "examples": ["Do you **believe in** God?", "I **believe in** saying what I think.", "The story can't be true.  I don't **believe it**. (not believe in it)", "Helen **specialises in** company law."]}, {"label": "B", "explain": "break into (=งัดเข้าไป); divide/cut/split something into; crash/drive/bump/run into; translate...from...into", "examples": ["Our house was **broken into** a few days ago.", "The book is **divided into** three parts.", "He lost control and **crashed into** a wall.", "Her books have been **translated into** many languages."]}, {"label": "C", "explain": "collide with; provide/supply somebody with; fill something with (แต่ full of)", "examples": ["A bus **collided with** a car.", "The school **provides** all students **with** books.", "Take this saucepan and **fill it with** water."]}, {"label": "D", "explain": "happen to; prefer one thing to another; invite somebody to (a party/wedding)", "examples": ["What **happened to** that gold watch you used to have?", "I **prefer** tea **to** coffee.", "They only **invited** a few people **to** their wedding."]}, {"label": "E", "explain": "concentrate on; spend (money) on; succeed in; insist on", "examples": ["I tried to **concentrate on** my work.", "How much do you **spend on** food each week?", "I hope you **succeed in** finding the job you want.", "Some friends **insisted on** coming with me."]}], "notes": [], "mistake": {"wrong": "The story can't be true.  I don't believe in it.", "right": "The story can't be true.  I don't believe it.", "note": "believe + something/somebody (ไม่มีบุพบท) = เชื่อว่าเป็นจริง ต่างจาก believe in (=เชื่อว่ามีอยู่จริง/เชื่อว่าถูกต้อง)"}, "tip": "believe (ไม่มีบุพบท) = เชื่อคำพูด/เรื่องราวว่าจริง ต่างจาก believe in = เชื่อว่าสิ่งนั้นมีอยู่จริงหรือเป็นหลักการที่ถูกต้อง — สองความหมายนี้ต่างกันมาก ต้องแยกให้ออก", "summary": ["believe in (เชื่อว่ามีอยู่จริง/หลักการที่ถูกต้อง) ≠ believe + something (ไม่มีบุพบท, เชื่อว่าเป็นจริง); specialise in", "break into, divide/crash into, translate...into; collide with, provide/supply...with, fill...with", "happen to, prefer...to, invite...to; concentrate on, spend...on, succeed in, insist on"]}, {"unit": 137, "section": "Phrasal verbs", "title": "กริยาวลี (Phrasal Verbs) บทนำ", "pattern": "verb + particle (in/out/on/off/up/down ฯลฯ)  ·  ตำแหน่งกรรม: คำนามวางได้สองที่, สรรพนามวางกลางเท่านั้น", "sections": [{"label": "A", "explain": "กริยาวลีคือกริยาที่ใช้คู่กับคำเสริม (particle) เช่น in/out/on/off/up/down/away/back มักใช้กับการเคลื่อนที่", "examples": ["The bus was full.  We couldn't **get on**.", "A woman got into the car and **drove off**.", "Sarah is leaving tomorrow and **coming back** on Saturday.", "When I touched him on the shoulder, he **turned round**."]}, {"label": "B", "explain": "บ่อยครั้งคำที่สอง (particle) ทำให้กริยามีความหมายพิเศษที่ต่างไปจากความหมายเดิมของกริยาโดยสิ้นเชิง", "examples": ["Sorry I'm late.  The car **broke down**. (= เครื่องยนต์เสีย)", "I never **found out** who sent me the flowers. (= ไม่เคยรู้)", "I tried many times to contact her.  In the end I **gave up**. (= เลิกพยายาม)", "My French isn't good, but it's enough to **get by**. (= พอเอาตัวรอดได้)"]}, {"label": "C", "explain": "บางครั้งกริยาวลีตามด้วยบุพบทอีกชั้นหนึ่ง", "examples": ["We **looked up at** the plane as it flew above us.", "Why did you **run away from** me?", "I can't **keep up with** you.", "Are you **looking forward to** your trip?"]}, {"label": "D", "explain": "เมื่อกริยาวลีมีกรรมเป็นคำนาม สามารถวางกรรมได้สองตำแหน่ง (ก่อนหรือหลัง particle) แต่ถ้ากรรมเป็นสรรพนาม (it/them/him ฯลฯ) ต้องวางไว้ระหว่างกริยากับ particle เท่านั้น", "examples": ["I **turned on the light**. = I **turned the light on**.", "I **turned it on**. (not turned on it)", "Don't **throw this box away**. / Don't **throw it away**. (not throw away it)"]}], "notes": [], "mistake": {"wrong": "I turned on it.", "right": "I turned it on.", "note": "ถ้ากรรมเป็นสรรพนาม (it/them/him ฯลฯ) ต้องวางไว้ระหว่างกริยากับ particle เท่านั้น ห้ามวางหลัง particle"}, "tip": "กริยาวลีบางคำมีความหมายตรงตัวจากคำสองคำรวมกัน (get on = ขึ้นรถ) แต่บางคำมีความหมายที่ไม่เกี่ยวกับคำเดิมเลย (get on = ทำได้เป็นอย่างไรบ้าง) ต้องท่องจำเป็นหน่วยเดียว", "summary": ["phrasal verb = กริยา + คำเสริม (in/out/on/off/up/down ฯลฯ) มักใช้กับการเคลื่อนที่ หรือมีความหมายพิเศษที่ต่างจากคำเดิม", "บาง phrasal verb ตามด้วยบุพบทเพิ่มอีกชั้น (look forward to, keep up with)", "กรรมที่เป็นคำนามวางได้สองตำแหน่ง (turn on the light / turn the light on) แต่กรรมที่เป็นสรรพนามต้องวางกลางเท่านั้น (turn it on)"]}, {"unit": 138, "section": "Phrasal verbs", "title": "กริยาวลี 2: in/out", "pattern": "in = เข้าไปข้างใน  ·  out = ออกไปข้างนอก  ·  fill in/out, drop in, eat out, drop out, leave out, cross out, join in, take in, plug in", "sections": [{"label": "A", "explain": "in = เข้าไปข้างในห้อง/อาคาร/รถ เป็นต้น (ในกรณีนี้ไม่มีกรรมตามหลัง ต่างจาก into ที่มีกรรม)", "examples": ["How did the thieves **get in**?", "Here's a key, so you can **let yourself in**.", "Lisa walked to the edge of the pool and **dived in**.", "I'm **moving in** on Friday. = I'm **moving into** my new flat."]}, {"label": "B", "explain": "out = ออกจากห้อง/อาคาร/รถ (ไม่มีกรรมตามหลัง ต่างจาก out of ที่มีกรรม)", "examples": ["Stay in the car.  Don't **get out**.", "I had no key, so I was **locked out**.", "She swam up and down the pool, and then **climbed out**.", "We paid the hotel bill and **checked out**."]}, {"label": "C", "explain": "สำนวนเฉพาะที่ใช้บ่อย: fill in/fill out (กรอกฟอร์ม), drop in (แวะเยี่ยม), eat out (กินข้าวนอกบ้าน), drop out (of) (เลิกเรียนกลางคัน), get out of (หลีกเลี่ยง), leave out (ไม่รวม/ละไว้), cross out (ขีดฆ่า), join in (ร่วมทำ), take somebody in (หลอกลวง), plug in (เสียบปลั๊ก)", "examples": ["Please **fill in** the application form. (or fill out)", "I **dropped in** to see Chris on my way home.", "Gary went to university but **dropped out** after a year.", "You can **leave out** the word 'that'.", "They were playing cards, so I **joined in**.", "The fridge isn't working because you haven't **plugged it in**."]}], "notes": [], "mistake": {"wrong": "I moved in my new flat.", "right": "I moved into my new flat. / I'm moving in (on Friday).", "note": "move in (ไม่มีกรรมตามหลัง) ต่างจาก move into + สถานที่ (มีกรรมตามหลัง)"}, "tip": "in/into แยกกันตามว่ามีคำนามตามหลังหรือไม่ — ถ้าไม่มีกรรมตามหลังใช้ in เฉยๆ (moving in), ถ้ามีกรรมสถานที่ตามหลังใช้ into (moving into my flat)", "summary": ["in = เข้าไปข้างในสถานที่ (get in, let somebody in, dive in) ต่างจาก into ที่ตามด้วยกรรม", "out = ออกจากสถานที่ (get out, check out, climb out) ต่างจาก out of ที่ตามด้วยกรรม", "สำนวนเฉพาะ: fill in/out (กรอกฟอร์ม), drop in (แวะเยี่ยม), eat out, drop out (of), leave out (ไม่รวม), cross out (ขีดฆ่า), join in, take somebody in (หลอก), plug in"]}, {"unit": 139, "section": "Phrasal verbs", "title": "กริยาวลี 3: out (เพิ่มเติม)", "pattern": "out (ไฟ/เปลวไฟดับ)  ·  work out (หลายความหมาย)  ·  carry out, point out, sort out, find out, turn out, run out (of)", "sections": [{"label": "A", "explain": "out ใช้กับไฟ/เปลวไฟที่ดับลง: go out, put out, turn out, blow out", "examples": ["Suddenly all the lights in the building **went out**.", "I **put** the fire **out** with a fire extinguisher.", "I **turned** the lights **out** before leaving.", "You can **blow** the candle **out**."]}, {"label": "B", "explain": "work out มีหลายความหมาย: ออกกำลังกาย, พัฒนา/เป็นไปด้วยดี, คำนวณ, หรือหาคำตอบ (=figure out)", "examples": ["Rachel **works out** at the gym three times a week. (=ออกกำลังกาย)", "I hope everything **works out well** for you. (=เป็นไปด้วยดี)", "I can't **work** it **out** in my head. (=คำนวณ)", "Investigators are trying to **work out** what caused the accident. (=หาคำตอบ)"]}, {"label": "C", "explain": "สำนวนอื่นที่ใช้บ่อย: carry out (ปฏิบัติตามคำสั่ง/แผน), point out (ชี้ให้เห็น), sort out (จัดการแก้ไข), find out (ค้นพบข้อมูล), turn out (to be) (กลายเป็นว่า), give/hand out (แจก), run out (of) (ใช้หมด), try out (ทดลองใช้)", "examples": ["Soldiers are expected to **carry out** orders.", "The tour guide **pointed out** all the sights.", "There are a few problems we need to **sort out**.", "The police never **found out** who committed the crime.", "Nobody believed Paul at first, but he **turned out to be** right.", "We **ran out of** petrol on the motorway.", "The company is **trying out** some new software."]}], "notes": [], "mistake": {"wrong": "We ran out petrol.", "right": "We ran out of petrol.", "note": "run out of + สิ่งของ ต้องมี of เสมอ"}, "tip": "work out มีหลายความหมายมาก (ออกกำลังกาย, เป็นไปด้วยดี, คำนวณ, หาคำตอบ) — ต้องดูบริบทเพื่อแยกความหมาย", "summary": ["out (ไฟ/เปลวไฟ) = ดับ: go out, put out, turn out, blow out", "work out = ออกกำลังกาย/เป็นไปด้วยดี/คำนวณ/หาคำตอบ (ความหมายหลากหลายตามบริบท); carry out = ปฏิบัติตาม; point out = ชี้ให้เห็น; sort out = จัดการแก้ไข", "find out = ค้นพบข้อมูล; turn out (to be) = กลายเป็นว่า; give/hand out = แจก; run out of = ใช้หมด; try out = ทดลองใช้"]}, {"unit": 140, "section": "Phrasal verbs", "title": "กริยาวลี 4: on/off (1)", "pattern": "on/off ไฟ/เครื่องใช้ไฟฟ้า  ·  put on/take off/try on (เสื้อผ้า)  ·  put off, set off, take off, see off, call off", "sections": [{"label": "A", "explain": "เราใช้ put/turn/switch + on/off กับไฟและเครื่องใช้ไฟฟ้า", "examples": ["Shall I leave the lights **on** or **turn** them **off**?", "'Is the heating **on**?'  'No, I **switched** it **off**.'", "Let's **put** some music **on**.", "I'll **put** the kettle **on**."]}, {"label": "B", "explain": "เราใช้ put on/take off/try on กับเสื้อผ้า แว่นตา เครื่องสำอาง และ put on weight = อ้วนขึ้น", "examples": ["My hands were cold, so I **put** my gloves **on**.", "I **tried on** a jacket in the shop, but it didn't look right.", "It was warm, so I **took off** my coat.", "I've **put on** two kilos in the last month."]}, {"label": "C", "explain": "off ยังหมายถึง 'ออกจาก/ห่างจาก' ได้ด้วย: put off (เลื่อน), be off (จะไป), walk/run/drive off (จากไป)", "examples": ["The election has been **put off** until January.", "Tomorrow I'm **off** to Paris.", "Anna got on her bike and **rode off**."]}, {"label": "D", "explain": "สำนวนอื่นๆ: go on (=เกิดขึ้น), set off (=ออกเดินทาง), take off (=เครื่องบินขึ้น), see somebody off (=ไปส่งที่สนามบิน/สถานี), call something off (=ยกเลิก)", "examples": ["What's all that noise?  What's **going on**?", "We **set off** early to avoid the traffic.", "After a long delay, the plane finally **took off**.", "We went to the station with her to **see her off**.", "The concert had to be **called off** because of the weather."]}], "notes": [], "mistake": {"wrong": "The election was put off of January.", "right": "The election has been put off until January.", "note": "put off ตามด้วย until (หรือระบุเวลาที่เลื่อนไป) ไม่ใช่ of"}, "tip": "สังเกตว่า put on/take off (สวมใส่/ถอดเสื้อผ้า) กับ take off (เครื่องบินขึ้น) ใช้คำเดียวกันแต่บริบทต่างกันโดยสิ้นเชิง ต้องดูบริบทประกอบเสมอ", "summary": ["on/off ใช้กับไฟ/เครื่องใช้ไฟฟ้า: put/turn/switch on/off; put on (เพลง/กาน้ำ)", "on/off ใช้กับเสื้อผ้า: put on/take off/try on (สวม/ถอด/ลอง); put on weight = อ้วนขึ้น", "off = ออกจาก: put off (เลื่อน), be off (จะไป), set off (ออกเดินทาง), take off (เครื่องบินขึ้น), see off (ไปส่ง), call off (ยกเลิก)"]}, {"unit": 141, "section": "Phrasal verbs", "title": "กริยาวลี 5: on/off (2)", "pattern": "verb+on = ทำต่อเนื่อง  ·  verb+off (doze off, go off, show off, tell off, rip off, put off)  ·  get on", "sections": [{"label": "A", "explain": "verb+on ใช้บอกว่าทำสิ่งหนึ่งต่อเนื่อง: go on (=ดำเนินต่อไป), keep on doing (=ทำซ้ำๆ), drive/walk/play on (=ทำต่อไป), finish something off (=ทำส่วนสุดท้าย)", "examples": ["The party **went on** until 4 o'clock in the morning.", "He **keeps on** criticising me. (or keeps criticising)", "Shall we **drive on** to the next petrol station?", "I'll **finish** it **off** tomorrow."]}, {"label": "B", "explain": "verb+off มีความหมายหลากหลาย: doze/drop/nod off (=หลับไป), go off (=ส่งเสียงเตือน/ระเบิด), show off (=อวด), tell somebody off (=ดุ), rip somebody off (=โกง/คิดราคาแพงเกินไป), put somebody off (=ทำให้ไม่อยากทำอีก)", "examples": ["I **dozed off** during the lecture.  It was very boring.", "Did you hear the alarm **go off**?", "He's just **showing off**.", "Clare's mother **told her off** for wearing dirty shoes.", "I think you **were ripped off**. (= จ่ายแพงเกินไป)", "We were **put off** by the long queue."]}, {"label": "C", "explain": "get on มีหลายความหมาย: ก้าวหน้า/เป็นอย่างไรบ้าง, เข้ากันได้กับคนอื่น, หรือทำงานต่อหลังถูกขัดจังหวะ (get on with)", "examples": ["How are you **getting on** in your new job? (= เป็นไปอย่างไรบ้าง)", "Joanne and Karen don't **get on**.  They're always arguing. (= ไม่เข้ากัน)", "I must **get on with** my work. (= ทำต่อหลังถูกขัดจังหวะ)"]}], "notes": [], "mistake": {"wrong": "Joanne and Karen don't get on well each other.", "right": "Joanne and Karen don't get on (with each other).", "note": "get on (=เข้ากันได้) ไม่ต้องมีกรรมตามหลังโดยตรง ถ้าต้องการระบุคนให้ใช้ get on with somebody"}, "tip": "get on มีสามความหมายหลัก: ก้าวหน้า/เป็นอย่างไรบ้าง (progress), เข้ากันได้ (relationship), และทำต่อหลังถูกขัดจังหวะ (get on with) — ดูบริบทเพื่อแยก", "summary": ["verb+on = ทำต่อเนื่อง: go on, keep on doing, drive on, finish off", "verb+off (หลากหลายความหมาย): doze off (หลับ), go off (เสียงดัง/แจ้งเตือน), show off (อวด), tell off (ดุ), rip off (โกง), put off (ทำให้ไม่อยากทำ)", "get on = ก้าวหน้า/เป็นอย่างไรบ้าง, get on (with somebody) = เข้ากันได้, get on with = ทำต่อหลังถูกขัดจังหวะ"]}, {"unit": 142, "section": "Phrasal verbs", "title": "กริยาวลี 6: up/down", "pattern": "put up/pick up/stand up/turn up (ขึ้น)  ·  take down/put down/sit down/turn down (ลง)  ·  burn down, let down, break down, turn down (ปฏิเสธ)", "sections": [{"label": "A", "explain": "up ใช้กับการยกขึ้น/ติดตั้ง/ยืนขึ้น/เพิ่มระดับ: put up (ติดผนัง), pick up (หยิบขึ้น), stand up, turn up (เพิ่มเสียง)", "examples": ["I **put** a picture **up** on the wall.", "There was a letter on the floor.  I **picked it up**.", "Alan **stood up** and walked out.", "I can't hear the TV.  Can you **turn it up** a bit?"]}, {"label": "B", "explain": "down ใช้กับการนำลง/วางลง/นั่งลง/ลดระดับ: take down (ถอดจากผนัง), put down, sit/bend/lie down, turn down (ลดเสียง/อุณหภูมิ)", "examples": ["I didn't like the picture, so I **took it down**.", "I stopped writing and **put down** my pen.", "I **bent down** to tie my shoelace.", "The oven is too hot.  **Turn it down** to 150 degrees."]}, {"label": "C", "explain": "สำนวน down อื่นๆ ที่ไม่เกี่ยวกับตำแหน่งจริง: burn down (ถูกไฟไหม้จนหมด), slow down, calm down, cut down (on) (ลดการทำ/กิน), close down/shut down (เลิกกิจการ), let somebody down (ทำให้ผิดหวัง), write something down (จด)", "examples": ["They put out the fire before the house **burnt down**.", "You're driving too fast.  **Slow down**.", "I'm trying to **cut down on** coffee.", "You can always rely on Paul.  He'll never **let you down**."]}, {"label": "D", "explain": "knock down (ทุบทำลายอาคาร / ถูกรถชนล้ม), break down (เครื่องยนต์/ความสัมพันธ์เสีย), turn somebody/something down (ปฏิเสธข้อเสนอ)", "examples": ["Some old houses were **knocked down** to make way for a shopping centre.", "A man was **knocked down** by a car.", "The car **broke down** and I had to phone for help.", "I applied for several jobs, but I was **turned down** for all of them."]}], "notes": [], "mistake": {"wrong": "I applied for a job, but they turned down.", "right": "I applied for a job, but I was turned down. / they turned me down.", "note": "turn down (=ปฏิเสธ) ต้องมีกรรม (คนหรือข้อเสนอ) ตามหลังเสมอ"}, "tip": "turn up (เพิ่มเสียง) กับ turn down (ลดเสียง/ปฏิเสธ) เป็นคู่ตรงข้ามที่สำคัญ ต้องแยกสองความหมายของ turn down ให้ออก (ลดระดับเสียง vs ปฏิเสธข้อเสนอ)", "summary": ["up (เกี่ยวกับการยกขึ้น/ติดตั้ง/เพิ่ม): put up, pick up, stand up, turn up", "down (เกี่ยวกับการลดระดับ/วางลง): take down, put down, sit/bend/lie down, turn down", "down (ความหมายพิเศษ): burn down, slow down, calm down, cut down (on), close down, let down (ทำให้ผิดหวัง), write down, knock down, break down, turn down (ปฏิเสธ)"]}, {"unit": 143, "section": "Phrasal verbs", "title": "กริยาวลี 7: up (1)", "pattern": "come/walk up to, set up, grow up, tidy up, take up (a hobby), bring up (a child)  ·  turn up, use up, catch up, end up, be made up of, keep up, give up", "sections": [{"label": "A", "explain": "come/walk up to (=เดินเข้าใกล้), set up (=ก่อตั้ง), grow up (=เติบโตเป็นผู้ใหญ่), clean/tidy up (=ทำความสะอาด/จัดระเบียบ), take up a hobby (=เริ่มทำกิจกรรมใหม่), bring up a child (=เลี้ยงดู)", "examples": ["A man **came up to** me in the street and asked me for money.", "The government has **set up** a committee.", "Amy was born in Hong Kong but **grew up** in Australia.", "Laura **took up** photography a few years ago.", "She was **brought up** by her grandparents."]}, {"label": "B-D", "explain": "turn up/show up (=มาถึง/ปรากฏตัว), use something up (=ใช้จนหมด), take up space/time (=ใช้พื้นที่/เวลา), fix up a meeting (=จัดนัด), catch up (with) (=ตามให้ทัน)", "examples": ["We arranged to meet David last night, but he didn't **turn up**.", "I want to **use** the vegetables **up**.", "Most of the space was **taken up** by a large table.", "We've **fixed up** a meeting for next Monday.", "I'll **catch up with** you."]}, {"label": "E", "explain": "end up (=ลงเอยที่.../ในที่สุดก็...), be made up of (=ประกอบด้วย), keep up (with) (=ตามให้ทัน/รักษาระดับ), give up (=เลิกพยายาม/เลิกทำ)", "examples": ["There was a fight, and three men **ended up** in hospital.", "I couldn't find a hotel and **ended up sleeping** on a bench.", "Air is **made up** mainly **of** nitrogen and oxygen.", "You're walking too fast.  I can't **keep up (with you)**.", "Sue got bored with her job and decided to **give it up**."]}], "notes": [], "mistake": {"wrong": "The population is made from many groups.", "right": "The population is made up of many groups.", "note": "be made up of = ประกอบไปด้วย (สำนวนคงที่ ไม่ใช่ made from ในบริบทนี้)"}, "tip": "end up + สถานที่/การกระทำ (-ing) = สิ่งที่เกิดขึ้นในที่สุด โดยไม่ได้วางแผนไว้ตั้งแต่แรก มักใช้บอกผลลัพธ์ที่ไม่คาดคิด", "summary": ["come/walk up to (เข้าใกล้), set up (ก่อตั้ง), grow up (เติบโต), take up a hobby (เริ่มทำกิจกรรม), bring up a child (เลี้ยงดู)", "turn up/show up (มาถึง), use up (ใช้จนหมด), catch up (ตามทัน), end up (ลงเอยที่...), be made up of (ประกอบด้วย), keep up with (ตามทัน/ต่อเนื่อง)", "give up (เลิกพยายาม), wash up (ล้างจาน), take up space/time (ใช้พื้นที่/เวลา), fix up (จัดนัด)"]}, {"unit": 144, "section": "Phrasal verbs", "title": "กริยาวลี 8: up (2)", "pattern": "bring up (ยกประเด็น), make up (แต่งเรื่อง), tear up, break/split up, do up  ·  look up, put up with, clear up, beat up, come up with, cheer up, blow up, hold up, mix up", "sections": [{"label": "A", "explain": "bring up a topic (=ยกประเด็นขึ้นมาพูด), make something up (=แต่งเรื่องที่ไม่จริง), save up for (=เก็บเงินเพื่อซื้อ), tear something up (=ฉีกเป็นชิ้นๆ), break up/split up (=เลิกกัน), do up (a coat/a building) (=ติดกระดุม/ซ่อมแซม)", "examples": ["Please don't **bring** it **up** again.", "What Kevin told you wasn't true.  He **made** it all **up**.", "Dan is **saving up** for a trip to New Zealand.", "I just **tore** the letter **up** and threw it away.", "I'm surprised to hear that Kate and Paul have **split up**.", "**Do up** your coat before you go out."]}, {"label": "B", "explain": "look something up (ค้นหาในพจนานุกรม), put up with (=ทนกับสิ่งที่ไม่ชอบ), clear up (=อากาศแจ่มใสขึ้น), beat somebody up (=ทำร้ายร่างกาย)", "examples": ["If you don't know a word, you can **look it up**.", "We have to **put up with** a lot of noise from the traffic.", "It was raining, but it **cleared up** later.", "A friend of mine was attacked and **beaten up**."]}, {"label": "C-D", "explain": "come up (=ถูกพูดถึงในบทสนทนา), come up with an idea (=คิดไอเดียขึ้นมาได้), cheer up (=ทำให้ร่าเริงขึ้น), blow up (=ระเบิด), hold up (=ทำให้ล่าช้า), mix up (=สับสน/จำผิด)", "examples": ["Some interesting things **came up** in our discussion.", "Sarah is very creative.  She's always **coming up with** new ideas.", "You look so sad!  **Cheer up**!", "The bridge was **blown up** during the war.", "Don't wait for me.  I don't want to **hold** you **up**.", "The two brothers look similar.  People often **mix them up**."]}], "notes": [], "mistake": {"wrong": "Don't hold up me.", "right": "Don't hold me up.", "note": "กรรมที่เป็นสรรพนามต้องแทรกกลางระหว่างกริยากับ particle เสมอ (ทบทวนจาก Unit 137D)"}, "tip": "put up with (ทน) เป็นกริยาวลีสามคำที่ตามด้วยกรรมโดยตรง (ไม่มีการสลับตำแหน่ง) — ต่างจาก look up (ค้นหาในพจนานุกรม) ที่วางกรรมได้สองตำแหน่ง", "summary": ["bring up (ยกประเด็น), make up (แต่งเรื่อง), save up for, tear up, break/split up (เลิกกัน), do up (ติดกระดุม/ซ่อมแซม)", "look up (ค้นหาคำศัพท์), put up with (อดทน), clear up (อากาศดีขึ้น), beat up (ทำร้ายร่างกาย), come up (ถูกพูดถึง), come up with (คิดไอเดียได้)", "cheer up (ทำให้ร่าเริง), blow up (ระเบิด), hold up (ทำให้ล่าช้า), mix up (สับสน/จำผิด)"]}, {"unit": 145, "section": "Phrasal verbs", "title": "กริยาวลี 9: away/back", "pattern": "away = ออกจากบ้าน/สถานที่/คน  ·  back = กลับบ้าน/กลับไปที่เดิม  ·  keep away, give away, put away, throw away  ·  call back, get away (with), look back, pay back", "sections": [{"label": "A", "explain": "away ใช้บอกการเคลื่อนที่ออกห่างจากบ้าน สถานที่ หรือคน ส่วน back ใช้บอกการกลับมาที่บ้านหรือกลับไปยังที่เดิม", "examples": ["We're going **away** on holiday today.", "Sarah got into her car, started the engine and **drove away**.", "We'll **be back** in three weeks.", "After eating at a restaurant, we **walked back** to our hotel.", "Can you **put** it **back** on the shelf?"]}, {"label": "B", "explain": "สำนวนอื่นที่ใช้ away: keep away (from) (=อย่าเข้าใกล้), give something away (=ให้คนอื่นไปฟรี), put something away (=เก็บเข้าที่), throw something away (=ทิ้ง)", "examples": ["**Keep away** from the edge of the pool.", "'Did you sell your bike?'  'No, I **gave it away** to a friend.'", "When the children finished playing, they **put** their toys **away**.", "I kept the letter, but I **threw away** the envelope."]}, {"label": "C", "explain": "สำนวนอื่นที่ใช้ back: wave/smile/shout/hit back, call/phone/ring somebody back (=โทรกลับ), get back to somebody (=ตอบกลับ), get away (=หลบหนี), get away with something (=ทำผิดโดยไม่ถูกจับได้), look back (on) (=มองย้อนอดีต), pay back (=คืนเงิน)", "examples": ["I waved to her, and she **waved back**.", "I can't talk now.  I'll **call you back** in ten minutes.", "I sent him an email, but he never **got back to me**.", "We tried to catch the thief, but she **got away**.", "I parked in a no-parking zone, but I **got away with** it.", "If you borrow money, you have to **pay it back**."]}], "notes": [], "mistake": {"wrong": "I'll call back you in ten minutes.", "right": "I'll call you back in ten minutes.", "note": "กรรมที่เป็นสรรพนามต้องแทรกกลางระหว่างกริยากับ back เสมอ"}, "tip": "away มักสื่อถึง 'จากไป/หายไป' (การเคลื่อนที่ออกจากจุดเดิม) ส่วน back มักสื่อถึง 'กลับมา/คืนสู่จุดเดิม' — เป็นคำตรงข้ามกันในหลายบริบท (throw away vs give back)", "summary": ["away = ออกจากบ้าน/สถานที่/คน (go away, drive away, fly away); back = กลับบ้าน/กลับไปที่เดิม (come back, walk back, put back)", "verb+away อื่นๆ: keep away (from), give away (ให้ไปฟรี), put away (เก็บเข้าที่), throw away (ทิ้ง)", "verb+back อื่นๆ: call/phone back (โทรกลับ), get back to (ตอบกลับ), get away (with) (หนี/รอดตัว), look back on (มองย้อนอดีต), pay back (คืนเงิน)"]}];